window.STUDY_DATA={"meta": {"language": "zh-Hans", "kind": "原创学习解读，不是信条原文或授权译本", "version": "2026-10-22 v1.0.0", "scope": "威敏33章、小要理107问、大要理196问；逐项入门至进阶学习注释，并不替代完整原文及注释书", "sourceLinks": ["https://opc.org/wcf.html", "https://opc.org/sc.html", "https://opc.org/lc.html"], "editionWarning": "编号参考OPC现行标准；民政、会议、婚姻及良心等处须区别1646—1648历史文本与后续美国长老会修订。欧陆信条对应项为主题对读索引，不表示措辞与论证完全相同。"}, "wcf": [{"n": 1, "title": "圣经", "core": "信仰首先回答谁有最终发言权。创造显出神，却不自行讲明基督的十架；救赎知识需要神的特殊启示。圣经充足、清晰并不意味每节同样容易，而是得救所必需的真理可借普通途径明白。教会承认正典，不能制造正典；以经解经把片段放回整本圣经。", "scripture": "提后3:14—17：保罗在异端与苦难中指向提摩太从小所学圣经，目的包含救恩与善行；彼后1:19—21把先知话语的源头归于圣灵。", "background": "宗教改革之后，传统权威与私人启示的竞争迫使教会说明判断教义的最终准则。", "application": "读一段经文，先问作者、受众、文体、论证，再问它如何位于基督的救赎史中。", "pitfall": "唯独圣经不等于不要教师，也不等于凭感觉逐节拼贴；充分不等于圣经是百科全书。", "continental": "比利时信条2—7；海德堡21。", "memory": "神说→圣灵确证→教会领受。"}, {"n": 2, "title": "神与三位一体", "core": "神不是宇宙中最大的对象，而是自有永有、完全不倚赖受造物的主。父、子、灵不是三个神，也不是一个神轮流戴面具；三位共享同一神性，以永恒关系区别。认识三一不是猜透神的内在机制，而是按神的启示敬拜。", "scripture": "申6:4在以色列面对列邦偶像时宣认独一主；太28:18—20把万民带进父子圣灵同一名下；约1:1—18表明道与神同在并且是神。", "background": "古代大公信经所守护的三一与基督论，构成改革宗的共同根基，而非十七世纪新发明。", "application": "祷告向父、藉子、在灵里；三位的工作不能割裂为互不相关的三个工程。", "pitfall": "不要用水三态解释三一；本质为一与位格为三回答不同问题，并非算术矛盾。", "continental": "比利时8—11；海德堡24—25；尼西亚与亚他那修信经。", "memory": "一本质，三位格；同尊荣，同永恒。"}, {"n": 3, "title": "神永恒的旨意", "core": "神按圣洁智慧定意万事，人的选择仍真实并负责任。预定首先带来谦卑：救恩不是神预先发现我较好；拣选在基督里，也包括信心、圣洁、宣教等途径。定罪按人的罪施行，不能把恩典与刑罚理解为道德上对称的两种制造。", "scripture": "弗1:3—14的拣选处于颂赞、儿子名分与圣灵印记中；罗9—11最后进入敬拜，也仍催促传福音；徒2:23同时确认神定旨与人的罪责。", "background": "奥古斯丁传统、宗教改革及反对意见使恩典与自由成为核心争论。此章要求谨慎宣讲，不能窥探隐秘名单。", "application": "从已启示的基督应许寻找确据，勤用恩典途径，不靠推测隐秘旨意决定是否信靠。", "pitfall": "预定不是宿命，也不是传福音无用；神的主权不能成为犯罪的借口。", "continental": "多特第一教义章；比利时16。", "memory": "在基督里，恩典先行，途径同行。"}, {"n": 4, "title": "创造", "core": "一切受造物从神领受存在，原初世界本为美善。人有身体与灵魂，男女同具神形象，受托管理而非拥有无限主权。创造论为人的尊严、劳动、婚姻与生态责任提供根基；受造不是贬低，而是确定我们在神面前的位置。", "scripture": "创1—2从无序进入有序，人的使命与安息同在；约1:1—3把创造联系于道；西1:15—20把万有的起源与归宿连于基督。", "background": "古代二元论贬低物质；改革宗反对把世界看成神性的一部分，也反对把人降为无目的工具。", "application": "尊重身体、劳动与受造界；以管理者而非掠夺者的心态使用资源。", "pitfall": "告白记述六日创造；有关日的解释与现代科学议题需另作论证，不宜让简短条文替代全部讨论。", "continental": "比利时12、14；海德堡26。", "memory": "从神而有，为神而活，原初甚好。"}, {"n": 5, "title": "护理", "core": "神不仅在起点创造，也持续保存、协同并治理万有。第一因不取消第二因：粮食来自神，也经由耕作；医治出于神，也可借医药。神容许并约束罪，能使其服务良善目的，却不把罪的恶归给神。", "scripture": "创50:15—21里兄长的恶意与神的善意指向同一事件而性质不同；太6:25—34以天父照顾受造物呼吁信靠并先求神国。", "background": "战乱、瘟疫与个人苦难使护理并非抽象哲学，而是教会能否在混乱中继续祷告的根基。", "application": "计划时勤勉，结果中谦卑，患难中求助；既不迷信征兆，也不拒绝合宜的受造途径。", "pitfall": "不要把每次灾难武断解释为某个人的特殊罪，也不要用护理压制悲伤与公义追求。", "continental": "海德堡27—28；比利时13。", "memory": "神掌管，途径真，人负责。"}, {"n": 6, "title": "堕落、罪与刑罚", "core": "亚当的背约带来罪责、败坏与死亡；罪不只是不良习惯，也不是身体本身邪恶。全然败坏是罪影响全人的每一层面，不是每个人都坏到最大程度。人仍有神形象与道德责任，却不能靠自己的能力恢复与神的和好。", "scripture": "创3把不信、羞耻、推责与放逐连在一起；罗5:12—21把亚当与基督作为两个代表比较，而不只提供坏榜样与好榜样。", "background": "反对以道德训练代替救赎，也回应把人原本视为完全自足的救恩观。", "application": "认罪包括思想、欲望、行为与结构中的个人责任；不以环境解释取消悔改，也不羞辱受害者。", "pitfall": "原罪不是说婚姻生育本身污秽；受试探不等于已经犯了该行为之罪。", "continental": "比利时14—15；多特第三四教义章1—5；海德堡3—11。", "memory": "亚当里失落，基督里更新。"}, {"n": 7, "title": "神与人立约", "core": "无限的神主动俯就，借约使受造者与他相交。行为之约揭示亚当受造时真实的顺服责任；堕落后的恩典之约以基督的顺服与赎罪为根基。旧约与新约不是两条得救道路，而是同一救赎应许在不同历史施行中的展开。", "scripture": "创15以应许与立约显出神主动担保；加3:6—29把亚伯拉罕之约、律法及基督连起来；来8—10说明新约的更美成全。", "background": "改革宗以圣约说明整本圣经的统一，避免把以色列与教会割裂，也避免抹去新旧施行的变化。", "application": "读旧约时问应许、预表、律例如何指向基督；记住恩典产生顺服，顺服不购买恩典。", "pitfall": "行为之约与恩典之约不是说旧约全靠行为、新约才靠恩典；每个历史圣约也不能简单互换。", "continental": "海德堡19、74；比利时17、34；欧陆传统对约的内部表述仍有差异。", "memory": "一个救主，一条恩路，多阶段施行。"}, {"n": 8, "title": "中保基督", "core": "救恩的中心是那一位永恒的子成为真人。两性完整、不混乱、不转化、不分裂、不分离；一位中保借先知、祭司、君王三职解决无知、罪责、悖逆。主动顺服与受苦顺服是同一救主完整顺服的两个观察面。", "scripture": "约1:14是道进入历史，不是人逐步升为神；来2:14—18强调与弟兄同有血肉；来7—10说明一次献祭与持续代求；腓2:5—11呈现降卑到升高。", "background": "承接大公教会基督论，抵挡以圣徒、仪式或人的功德分担基督中保的独特地位。", "application": "羞愧时看他的祭司职；迷失时听他的先知话语；惧怕时信他的君王治理。", "pitfall": "不可把两性当成两个位格，也不可把人性看成神性的外壳；无罪不使他较少为人。", "continental": "比利时18—21、26；海德堡12—19、31—52。", "memory": "一位两性，三职两态。"}, {"n": 9, "title": "自由意志", "core": "人的意愿并非外力强拖的机械反应；但自由的实际方向随属灵状态而变。受造时能顺服也能背离，堕落后不能自行爱神至得救，重生后蒙恩争战，荣耀中完全乐于善。恩典医治意志，而非把人变成没有意志。", "scripture": "约8:31—36把真自由与子的释放相连；罗6从罪奴转为义仆；腓2:12—13把信徒努力与神在内的运行连在一起。", "background": "回应救恩是否先由人自主启动的问题，也防止用主权否定人的真实抉择。", "application": "求圣灵改变欲望，并实际拒绝诱惑；分辨能选择日常事务与能自救并非同一能力。", "pitfall": "自由不必定义为对善恶永远同等中立；否则神与荣耀圣徒反而无法被称为自由。", "continental": "多特第三四教义章；海德堡8。", "memory": "受造能善；堕落失能；恩典更新；荣耀坚善。"}, {"n": 10, "title": "有效呼召", "core": "福音外在传给许多人；圣灵使神所拣选的人真实领受基督，光照理性、更新意志并产生信心。它不是另一套隐藏福音，也不是人在无意识中被强迫；人因甘心被更新而甘心来。", "scripture": "罗8:28—30把呼召接在预定与称义之间；徒16:14的吕底亚听保罗讲道，主开她的心；约6:37—45强调父赐与来就基督。", "background": "回应仅靠教育、意志动员即可重生的想法；也说明宣教必须同时重视清楚传讲与迫切祷告。", "application": "清楚讲福音并为听者祷告；邀请人现在信靠基督，不让他们先证明自己已被呼召。", "pitfall": "外在教会身份与一般感动不等于重生；不要凭一次强烈情绪宣布得救。", "continental": "多特第三四教义章11—17；比利时22、24。", "memory": "道传入耳，灵更新心，人甘心来。"}, {"n": 11, "title": "称义", "core": "神在法庭性的宣告中赦罪、接纳罪人为义，根基是基督的义归算，领受的工具是信心。信心本身不是支付救恩的优良行为；称义也不等于神假装罪不存在，而是罪已由中保担当。", "scripture": "罗3:21—4:25在众人有罪的论证之后讲白白称义；林后5:21强调在基督里的义；雅2反对没有生命果子的口头信，不另立功德称义。", "background": "宗教改革关于人在神面前如何站立的争论，直接涉及良心安慰与基督工作的充分性。", "application": "失败时回到基督，不用表现重新买回接纳；同时检视信心是否在爱中工作。", "pitfall": "称义不把道德改造作为宣告的根据；唯独信心却不会永远孤立而没有果子。", "continental": "比利时22—23；海德堡59—64。", "memory": "根基是基督；工具是信心；果子是善行。"}, {"n": 12, "title": "得儿子名分", "core": "救恩不只把被告宣告无罪，还把人接进神的家。信徒得以称神为父，领受儿女的权利、管教与产业。儿子名分是恩赐的法律与关系地位，不表示受造者变成神的本质。", "scripture": "罗8:14—17在圣灵治死罪的上下文中讲呼叫父与一同承受产业；加4:4—7把子的差遣与圣灵的差遣相连。", "background": "在家庭、继承与身份极有重量的社会里，儿女身份将救恩的客观地位变为日常亲近神的根基。", "application": "被拒绝时以天父的接纳重整身份；接受管教并关顾同属一家的人。", "pitfall": "儿女不等于今生免去痛苦；父的管教与定罪不同，教会领袖不能据此合理化虐待。", "continental": "海德堡26、33、120；比利时26。", "memory": "赦罪进入家，呼父承产业。"}, {"n": 13, "title": "成圣", "core": "与基督联合的人借圣灵逐渐被更新，全人受影响，余罪仍真实存在。称义的地位一次确立，成圣的生命持续成长；二者不可混淆，也不可拆散。争战证明成圣尚未完成，不自动证明恩典不存在。", "scripture": "罗6:1—14从与基督同死同活推导不要容罪作王；加5:16—26描画情欲与圣灵的争战以及具体果子。", "background": "抵挡靠行为取得接纳，也抵挡用恩典纵容不悔改；清教徒关注可见的敬虔生活。", "application": "用具体计划对付某项罪，建立祷告、读经、团契习惯，以基督应许为动力。", "pitfall": "成圣不是逐渐获得称义资格，也不是达到今生无罪；不要以进度比较制造属灵阶层。", "continental": "比利时24；海德堡86—91；多特第五教义章。", "memory": "地位已定，生命更新，争战未完。"}, {"n": 14, "title": "得救的信心", "core": "信心认识神的话、认可其真实并倚靠基督；对象的可靠使信心有价值。它能强能弱，主要由圣道产生，并借圣礼、祷告坚固。救恩的核心动作是领受并安息于基督，不是凝视自己相信得够不够。", "scripture": "约20:30—31说明记下神迹使人信耶稣并得生命；罗10:14—17把差遣、传讲、听见、相信连成一线。", "background": "教会需要区别历史知识、短暂感动与真实倚靠，也需要照顾软弱信徒。", "application": "把信心表达为向基督求助，并持续聆听他的应许。", "pitfall": "怀疑不等于完全无信；但长期拒绝基督主权也不能用曾有决定掩盖。", "continental": "海德堡21；比利时22；多特第一教义章12。", "memory": "知其真，认其真，投靠他。"}, {"n": 15, "title": "悔改得生命", "core": "悔改是福音恩典，使人因看见罪的丑恶与神在基督里的怜悯而转向神。它不是补偿罪债的代价，也不是单纯害怕后果；真实悔改有具体承认、恨恶与离弃，同时不绝望于赦免。", "scripture": "路15的归家置于寻找失丧者的怜悯故事中；林后7:8—11区别依神意思的忧愁与致死的忧愁。", "background": "回应把悔罪当赚取赦免的功课，也回应只求免罚却拒绝改变的廉价认罪。", "application": "具体认错，适当赔偿与重建信任；公开罪按影响范围处理，不以笼统道歉躲避责任。", "pitfall": "不能用自己痛苦的强度计算赦罪；受害者不必因施害者认罪就立即恢复同等信任。", "continental": "海德堡88—90；比利时24。", "memory": "看罪，仰恩，离罪，归神。"}, {"n": 16, "title": "善行", "core": "善行以神所命令为准，来自信心与圣灵能力，目的为荣耀神、帮助邻舍并见证恩典。它们不是救恩价格，却不是可有可无的装饰；连最好的善行也仍需基督悦纳。", "scripture": "弗2:8—10先说恩典拯救，随即说在基督里为善行而造；约15:1—8让枝子结果的能力来自与葡萄树相连。", "background": "面对额外功德与自订敬虔的传统，改革宗将善行带回圣经、恩典和日常 vocation 的处境。", "application": "问一项服事是否真爱邻舍、合乎神命令，还是只为建立自己的道德形象。", "pitfall": "不完美不等于无需行动；宗教热情不能使神未命令甚至禁止的事变成好事。", "continental": "海德堡91；比利时24。", "memory": "恩典是根，善行是果。"}, {"n": 17, "title": "圣徒坚忍", "core": "父的拣选、子的代求、圣灵的内住使真信徒被保守到底。坚忍不是信徒凭顽强意志锁住救恩，也不是一次表态后任意生活的保证；神的保守以警戒、悔改和教会扶持等途径实现。", "scripture": "约10:27—30把不被夺去与听主声音、跟随相连；彼前1:3—9同时讲神能力保守、信心与试炼。", "background": "教会经历跌倒与逼迫，必须回答神是否会放弃自己的儿女，同时认真看待背道警告。", "application": "跌倒时及时求助、认罪并回到恩典途径；教会追寻失落者而非轻率给终局判断。", "pitfall": "外在暂时认信可能终止；不能从一个过去仪式替持续拒绝悔改的人保证救恩。", "continental": "多特第五教义章；海德堡54；比利时22、24。", "memory": "神保守，人坚忍；警戒也是保守途径。"}, {"n": 18, "title": "救恩确据", "core": "信徒可以根据神的应许、圣灵的见证与恩典果子得真实确据；它不是每位信徒时时同样强烈的心理状态。确据能因疏忽与罪受损，却可藉日常恩典途径恢复。可靠的中心是基督，不是自我检查的无尽循环。", "scripture": "约壹5:11—13将永生确据指向神在子里的见证；罗8:15—17连接儿女呼求与圣灵见证。", "background": "牧养同时面对自信的伪善者与忧伤的信徒，需要分清信心本质与对信心的反省认识。", "application": "优先听福音应许，再在教会陪伴中辨认真实果子；长期焦虑也可寻求合宜专业帮助。", "pitfall": "缺少强烈确据不必等于没有救恩；主观平安也不能使不悔改的生活变为安全。", "continental": "海德堡1、21；多特第五教义章9—13。", "memory": "应许作根，灵作证，果子印证。"}, {"n": 19, "title": "神的律法", "core": "道德律法反映神圣洁的旨意。基督成全律法，并没有让爱神爱人的义务消失；信徒脱离律法作为称义条件与定罪权势，仍以律法为感恩生活的准绳。礼仪律在基督里成全；以色列司法制度不直接成为每国法典，其一般公义仍有教益。", "scripture": "出20先有出埃及拯救再有十诫；太5:17—20谈成全；罗7:7—13说明罪利用律法，律法本身仍圣洁。", "background": "改革宗区分律法用途与圣经历史中的施行，防止律法主义与反律法主义两极。", "application": "每条诫命既问我不可做什么，也问应积极保护什么善；读律例时分辨救赎史阶段。", "pitfall": "不能把旧约每条民事刑罚搬进现代，也不能把恩典解释为伦理空白。", "continental": "海德堡92—115；比利时25。", "memory": "照罪、约束、引导；恩典后感恩。"}, {"n": 20, "title": "基督徒自由与良心", "core": "基督释放人脱离罪责、咒诅、奴役性恐惧，并赐坦然亲近父。唯独神是良心的主；人的命令不得冒充神的救恩要求。但自由的目标是敬拜与相爱，不是破坏合法权柄或纵容伤害。", "scripture": "加5:1、13把自由与凭爱服事连在一起；罗14要求强弱者都向主负责，不互相轻看或审判。", "background": "国家宗教、教会命令与个人良心在十七世纪密切纠缠，本章需与民政、教会纪律同时阅读。", "application": "区别圣经明确命令、智慧建议与个人喜好；在可争议事项上尊重良心并寻求彼此益处。", "pitfall": "原始1646版20.4与后来的长老会修订有差异；不可把现代宗教自由制度直接投射回大会。", "continental": "比利时32；海德堡91；欧陆政治条文也经历修订。", "memory": "自由离罪，良心向神，爱中服事。"}, {"n": 21, "title": "敬拜与安息日", "core": "神规定如何亲近他，敬拜必须经基督、按圣经、在圣灵与真理中进行。改革宗敬拜规范原则限制教会擅立敬拜要素；实际时间、场地等处境安排须按圣经一般原则与智慧。主日聚集把创造安息与复活新造连在一起。", "scripture": "约4:19—26把地点争议转向弥赛亚开启的敬拜；徒20:7显示七日第一日聚集；来4把安息指向更深的应许。", "background": "面对强制礼仪与迷信仪式，清教徒关心谁有权规定敬拜；苏格兰与欧陆礼仪实践也非完全一致。", "application": "预备主日、参与讲道祷告圣礼，以怜悯与必要工作服务邻舍，并让整周朝向安息的主。", "pitfall": "威敏的安息日表述比海德堡103更详；不可隐去差异，也不可凭差异否定共同根基。", "continental": "海德堡96—103；比利时7、32—35。", "memory": "神设敬拜，基督开路，主日归主。"}, {"n": 22, "title": "合法誓言与许愿", "core": "誓言是郑重求神为真实作见证；许愿是向神承担合宜责任。都必须真实、审慎、可履行、合乎神的话。奉神名不能把罪合法化，也不能让人的承诺高于神的命令。", "scripture": "申6:13处于专一敬拜主的盟约呼召中；太5:33—37揭露借誓言逃避真话；来6:16—18以誓言说明神应许可靠。", "background": "宗教与政治忠诚的誓约曾塑造三国战争；改革宗与拒绝一切誓言的立场有分歧。", "application": "签约与公开承诺前辨明内容；已许的恶事应悔改而非继续完成。", "pitfall": "本章不许可轻率起誓，也不许可用宗教誓言操控婚姻、钱财与个人决定。", "continental": "海德堡101—102；比利时36相关。", "memory": "真、善、慎、可行。"}, {"n": 23, "title": "民政长官", "core": "公共权柄由神设立，为抑恶扬善、维护公义与和平。基督徒应为执政者祷告并履行公共责任，人的命令若抵触神则以神为先。原始大会在基督教国家框架中赋予长官宗教职责；后来的美国长老会修订强调不同教派的保护与教会独立。", "scripture": "罗13在罗马帝国处境中说明公权柄的职分；彼前2:13—17同时要求尊敬与敬畏神；徒5:29提供顺服的界限。", "background": "英格兰内战、大会由议会召集、苏格兰盟约诉求，都是理解本章的必要背景。", "application": "守法、纳税、祷告并追求邻舍公义；评价政策时不把某政党等同神国。", "pitfall": "不可把OPC现行23.3当成1646原文；也不可把历史国家教会模式说成今日所有改革宗共识。", "continental": "比利时36有历史及修订版本；与威敏须注明版本逐项比较。", "memory": "权柄受托，公义为职，神权最高。"}, {"n": 24, "title": "婚姻与离婚", "core": "婚姻是男女忠诚、互助与家庭生活的神圣盟约，尊重身体、亲属界限与公开承诺。罪能破坏婚约；告白讨论奸淫与无法补救的恶意离弃，而不把离婚变成轻率选择。教会与民事程序需查事实、保公义、保护弱者。", "scripture": "创2:18—25把相助与联合连在一起；太19:3—9回应试探性离婚争论；林前7讨论真实婚姻、离弃与和平。", "background": "宗教改革将婚姻从某些圣礼体系中区分出来，同时拒绝把它降为纯粹私人合意。", "application": "婚前诚实、婚内守约、危机时求助；危险处境先保护人身安全并依法处理。", "pitfall": "不可要求受暴者留在即时危险中来证明顺服；关于虐待与恶意离弃的适用应由可靠牧养与法律事实审慎判断。", "continental": "海德堡108—109；比利时一般伦理，未有同等篇幅专章。", "memory": "立约相助，忠诚保护，公义处理破裂。"}, {"n": 25, "title": "教会", "core": "教会属于基督：从神最终所知看是历世历代选民的整体；从历史可见处看是认信者及其儿女的盟约群体。地方教会有纯正程度之别，不是每个自称教会的团体都忠于福音。基督是教会唯一元首。", "scripture": "弗2:11—22把犹太人与外邦人在基督里建成神居所；弗4:1—16把合一与真理、恩赐及成熟连接。", "background": "改革宗面临罗马权威、国家控制与分离主义等压力，需说明教会在哪里、靠什么被认出。", "application": "以圣道、圣礼、纪律观察教会，稳定参与一个真实群体，承担服事与彼此责任。", "pitfall": "有形与无形不是两个教会；它们区分人的公开认信与神完全知道的实际归属。", "continental": "比利时27—29；海德堡54。", "memory": "基督一体，可见相聚，真理辨认。"}, {"n": 26, "title": "圣徒相通", "core": "与基督联合使信徒彼此相属，共享恩赐、敬拜与实际援助。相通不是人进入神的本质，也不是取消私人所有权；财物仍受托管理，爱心却使人不能对弟兄姊妹的真实需要无动于衷。", "scripture": "徒2:42—47描画教训、团契、擘饼与分享；林前12把不同肢体的尊荣与痛苦连在一起；林后8—9以恩典推动捐助。", "background": "教会在贫困、战争与迁徙中需要跨地域扶持；欧陆难民教会尤其见证共同信仰的实际代价。", "application": "定期关怀、探访、分享能力与资源；建立透明帮助机制而非让受助者受羞辱。", "pitfall": "团契不是只有社交亲密，也不赋予领袖无限支配成员财产与隐私的权力。", "continental": "海德堡55；比利时28。", "memory": "与主相连，与人相顾。"}, {"n": 27, "title": "圣礼", "core": "圣礼是神设立的盟约记号与印证，把应许以可见方式摆在教会面前。记号与所指关系真实而不混同；功效出于圣灵与基督应许，不出于物质魔力或施行者人格。新约由基督设立洗礼与圣餐两项。", "scripture": "罗4:11用印证说明亚伯拉罕的割礼；林前10:1—13显示外在领受不自动保证忠信；太28与林前11显示设立根据。", "background": "宗教改革既反对圣礼自动生效，也反对把圣礼缩成只表达人的纪念或决心。", "application": "领受时同时听见应许、运用信心、记得自己属于基督的身体。", "pitfall": "不是第三条与圣道竞争的救恩道路；无信的不敬虔领受不能据仪式自安。", "continental": "比利时33；海德堡65—68。", "memory": "应许可见，记号印证，圣灵施恩。"}, {"n": 28, "title": "洗礼", "core": "水奉三一神之名施行，指向进入可见教会、罪得洁净与归属基督。信主者及其盟约儿女应受洗；婴儿洗礼根植约的连续性而非声称婴儿已能作成人式认信。功效不绑在施行瞬间，洗礼不能机械等同重生。", "scripture": "太28:18—20把洗礼连于门徒训练；徒2:38—39把应许指向听众、儿女与远方被召者；罗6以洗礼语言表明与基督同死同活。", "background": "改革宗与重洗派围绕盟约群体、儿女位置和施洗对象分歧；这是应明确承认的教会差异。", "application": "受洗后持续接受教导并以信心回应应许；父母承担家庭教养，教会承担陪伴。", "pitfall": "婴儿受洗不等于每位受洗者必然得救；成人受洗也不免除持续悔改。", "continental": "海德堡69—74；比利时34。", "memory": "水洗记号，基督洁净，盟约养育。"}, {"n": 29, "title": "主的晚餐", "core": "圣餐记念并宣告基督一次完成的牺牲；信徒因信、借圣灵真实领受基督及其益处。饼酒仍是饼酒，基督身体不被圈在元素里；属灵临在不是虚幻临在，而是圣灵使信徒在天上的主里得滋养。", "scripture": "林前10:16—17把杯饼与同一身体连接；林前11:17—34责备羞辱穷人的聚餐，要求分辨主身体并彼此等候。", "background": "回应重复献祭、物质变化与纯心理纪念等立场；欧陆与威敏共享属灵真实领受。", "application": "预备时省察、悔改、和好；软弱却愿投靠基督的人应获牧养安慰。", "pitfall": "合宜领受不是先成为无罪者；顽梗与无知的问题不能靠私人自许掩盖。", "continental": "海德堡75—82；比利时35。", "memory": "一次献祭，常常记念，因信受养。"}, {"n": 30, "title": "教会惩戒", "core": "教会钥匙是基督托付的牧养职分，借劝戒、暂停圣餐与必要时革除来挽回犯罪者、保护群体、除去绊脚石并尊荣主名。它与国家刑罚不同，须合乎经文、事实与公平程序。", "scripture": "太18:15—20先从挽回弟兄开始并逐步扩大；林前5处理公开顽梗的罪；林后2:5—11显示悔改者应被赦免安慰。", "background": "改革宗把纪律视为有形教会健康的重要表现，反对无纪律与专制纪律。", "application": "以恢复为目标，听双方证据、保护受害者，并在悔改后有智慧地恢复相交。", "pitfall": "赦免不自动恢复公职或取消民事责任；纪律不能成为压制合理投诉的工具。", "continental": "海德堡83—85；比利时29、32。", "memory": "挽回人，护群羊，尊主名。"}, {"n": 31, "title": "会议与大会", "core": "教会共同议决有助于处理教义争议、秩序及申诉；会议必须服在圣经之下，可能犯错，不能创造新信仰。跨堂会监督避免个人领袖绝对化，同时不把大会变成普遍无误的权威。", "scripture": "徒15处理外邦人是否须受割礼时，听见见证、考察经文、共同传达判断；加2仍要求领袖受福音真理检验。", "background": "英格兰、苏格兰与欧陆教会的制度发展不同；威敏原始版与美国修订版关于谁召集会议也不同。", "application": "重视合宜申诉、长老群体与跨教会问责；会议决议应说明圣经理由。", "pitfall": "长老会不等于行政多数能定义真理；任何会议仍需以圣经检验。", "continental": "比利时30—32；欧陆教会秩序通常另有堂会、区会、总会规则。", "memory": "共同议决，圣经裁判，可错须改。"}, {"n": 32, "title": "死后与复活", "core": "死亡使身体归尘，人的灵魂不停止存在；信徒与基督同在，等候身体复活。救恩最终不是逃离身体，而是整个人被更新；义与不义者都复活，结局有别。", "scripture": "腓1:21—24表达离世与基督同在的盼望；林前15以基督复活保证属他者复活，并由此呼吁坚固劳苦。", "background": "反对炼狱作为救恩中间补偿机制，也反对灵魂睡眠与只保灵魂的片面终末观。", "application": "哀伤可以真实，盼望也真实；尊重身体与葬礼，扶持临终者并记得复活应许。", "pitfall": "死后与主同在不是最终复活的全部；复活身体不是把旧生命原封延长。", "continental": "海德堡57—58；比利时37。", "memory": "灵魂与主，身体待赎，全人复活。"}, {"n": 33, "title": "最后审判", "core": "基督将公开审判全人类，使神公义与恩典完全显明。信徒的接纳唯独基于基督，行为作为信心真实与主公义判断的公开证据。审判既警醒自恃者，也安慰被压迫者：没有隐蔽的恶能永远逃避主。", "scripture": "太25:31—46显示王对最小者的关怀与真实门徒生命有关；启20—22把审判连于新天新地；林后5:10呼吁向主忠心。", "background": "战乱与逼迫中的教会需要知道历史不是暴力者的最终胜利；终末论须服务敬虔而非日期猜测。", "application": "今天悔改、施怜悯、行公义、传福音，把最终伸冤交给基督。", "pitfall": "不可从灾难或政治新闻计算日期；行为证据不等于人的功劳补足基督。", "continental": "海德堡52；比利时37。", "memory": "主必再来，公义显明，恩典完成。"}], "sc": [{"n": 1, "title": "人生终向", "commentary": "人的受造目的把认识神、荣耀神与在神里面的喜乐连为一体；成就、家庭与事业应受这个终向整合，而不能取代神。", "section": "人生与启示"}, {"n": 2, "title": "认识终向的准绳", "commentary": "旧新约圣经引导信仰与生活；人的经验、传统和理性须接受其检验。先听神如何启示自己，再决定怎样亲近他。", "section": "人生与启示"}, {"n": 3, "title": "圣经两大教导", "commentary": "相信什么与如何生活互为联系：关于神的真理产生合宜回应，顺服则回应已经领受的恩典。不要把教义和生活割裂。", "section": "人生与启示"}, {"n": 4, "title": "神是谁", "commentary": "神超越受造界，完全、永恒且不变；列举属性为敬拜提供语言，并不把神切割成不同零件。智慧、能力与良善从不互相竞争。", "section": "当信的真理"}, {"n": 5, "title": "神独一", "commentary": "敬拜不能分散于许多终极忠诚。承认独一真神意味着金钱、国家、家庭甚至宗教领袖都不能要求属于神的绝对顺服。", "section": "当信的真理"}, {"n": 6, "title": "三位一体", "commentary": "父子圣灵同具完整神性，以位格区别；救恩自父、藉子、在灵里临到我们。三不是三个本体，一不是一位轮换身份。", "section": "当信的真理"}, {"n": 7, "title": "永恒旨意", "commentary": "历史不在神计划之外；神按智慧与圣洁定旨，使恩典最终归于他的荣耀。这不是让人窥探隐秘未来，而是学习信靠。", "section": "当信的真理"}, {"n": 8, "title": "旨意的施行", "commentary": "创造使万有存在，护理使历史向神所定的终局运行。神的计划不是停留在观念中，而进入真实世界与人的生活。", "section": "当信的真理"}, {"n": 9, "title": "创造万物", "commentary": "世界不是神的材料变形，也不是无目的偶然的终极产物；神以自己的权能使万有存在，并宣告原初创造美善。", "section": "当信的真理"}, {"n": 10, "title": "创造人", "commentary": "男女同按神形象被造，受托有知识、公义、圣洁并管理万物。尊严是神所赐，不由能力、年龄、收入或族群决定。", "section": "当信的真理"}, {"n": 11, "title": "护理工作", "commentary": "保存与治理包括受造物及其行动；日常途径也是神的工作场域。信靠护理激励负责任行动，而非懒惰等待奇迹。", "section": "当信的真理"}, {"n": 12, "title": "起初的生命之约", "commentary": "亚当在神的恩惠环境中承担完整顺服的责任，禁令使善恶主权显明属于神。盟约关系不是人自行设定条件的交易。", "section": "当信的真理"}, {"n": 13, "title": "人的堕落", "commentary": "始祖原有的自由被用来背离神。罪不是神强迫无辜者做恶；人真实选择，因此承担道德责任。", "section": "当信的真理"}, {"n": 14, "title": "罪的性质", "commentary": "罪包括未达到神要求的缺失，也包括主动越界；思想与动机同属道德生命。只说自己没有明显伤人，仍不足以证明无罪。", "section": "当信的真理"}, {"n": 15, "title": "首次背约", "commentary": "吃禁果是具体历史行为，其本质是拒绝神的话、自取善恶裁定权。果子的物质并不是邪恶的源头。", "section": "当信的真理"}, {"n": 16, "title": "亚当的代表性", "commentary": "亚当作为盟约代表牵涉后裔，正如基督作为新元首带来救恩；罗马书5章让我们从代表关系而非孤立个人主义理解历史。", "section": "当信的真理"}, {"n": 17, "title": "堕落后的境况", "commentary": "罪与苦同时出现，但不能因此把某位受苦者的每场痛苦直接归咎于他的某项罪。全人类共同处于破裂秩序。", "section": "当信的真理"}, {"n": 18, "title": "罪责与败坏", "commentary": "罪的处境包括亚当罪责、原义失落、全人败坏与由此生出的具体罪行。不是身体独自坏，也不是换个环境便能自救。", "section": "当信的真理"}, {"n": 19, "title": "失落的痛苦", "commentary": "最深的痛苦是失去与神相交；今生破碎与死亡指向更严肃的审判。福音因此超过自我改善和短期安慰。", "section": "当信的真理"}, {"n": 20, "title": "恩典之约", "commentary": "神没有任凭所有人灭亡，而主动在救赎主里施恩。恩典之约不是神降低圣洁要求，而由基督成全救恩所需的一切。", "section": "当信的真理"}, {"n": 21, "title": "唯一救赎主", "commentary": "永恒的神子成为真人，是一位具有两性的中保。只有这位救主既能代表人，又具有担当救赎与赐生命的神圣能力。", "section": "当信的真理"}, {"n": 22, "title": "道成肉身", "commentary": "圣灵使基督由马利亚取得真实身体与理性灵魂，并无罪。救主不是披着人体的神，也不是一个后来被收养成神的人。", "section": "当信的真理"}, {"n": 23, "title": "中保三职", "commentary": "先知、祭司、君王分别回应人的无知、罪责与悖逆；这是一位基督整全救恩的三个面向，不是三种可选择的耶稣。", "section": "当信的真理"}, {"n": 24, "title": "先知职", "commentary": "基督借圣道与圣灵显明神救赎的旨意；我们所需的不只是资讯，而是能使人认识神并顺服真理的启示。", "section": "当信的真理"}, {"n": 25, "title": "祭司职", "commentary": "基督一次献上自己满足公义并使人与神和好，又持续为属他的人代求。圣餐不重复献祭，信徒也不需要第二位中保。", "section": "当信的真理"}, {"n": 26, "title": "君王职", "commentary": "基督征服我们的悖逆、治理保护教会，并最终胜过仇敌。王权首先让我们归服他，不能只拿来保证个人成功。", "section": "当信的真理"}, {"n": 27, "title": "基督降卑", "commentary": "降卑涵盖出生、处于律法之下、受苦、十架、埋葬与暂居死权。荣耀之主不是远观苦难，而实际进入人的困境。", "section": "当信的真理"}, {"n": 28, "title": "基督升高", "commentary": "复活、升天、坐父右边与将来审判展现救赎已完成并正被施行；基督的升高不表示他不再具真实人性。", "section": "当信的真理"}, {"n": 29, "title": "领受救赎", "commentary": "基督成就的益处需要由圣灵实际施予；历史上发生的救赎工作与个人蒙恩不可混同，也不可拆开。", "section": "当信的真理"}, {"n": 30, "title": "圣灵如何施行", "commentary": "圣灵生出信心，使人借信与基督联合。信心不是人在恩典之外先献上的资本，而是恩典使人真实回应的工具。", "section": "当信的真理"}, {"n": 31, "title": "有效呼召", "commentary": "圣灵使人认识罪与苦、光照认识基督、更新意志而投靠他。真理不只是被听到，更成为甘心接受的好消息。", "section": "当信的真理"}, {"n": 32, "title": "蒙召的益处", "commentary": "称义、儿女身份与成圣同从与基督联合而来；神接纳人，也把人接进家并更新生命，不能只挑其中一项。", "section": "当信的真理"}, {"n": 33, "title": "称义", "commentary": "这是神宣告赦免并接纳的作为，以基督的义为根据，以信心为领受工具。内在改变很重要，却不成为称义的功德根基。", "section": "当信的真理"}, {"n": 34, "title": "儿子名分", "commentary": "神把信徒接入自己的家，赋予儿女权利。学习称神为父，也学习把不同背景的信徒当作弟兄姊妹。", "section": "当信的真理"}, {"n": 35, "title": "成圣", "commentary": "圣灵更新整个人，使人越来越向罪死、向义活。成圣有真实进展，也有仍存的争战；不能以未完全作为停止悔改的理由。", "section": "当信的真理"}, {"n": 36, "title": "今生伴随的益处", "commentary": "神的慈爱确据、良心平安、圣灵喜乐、恩典增长与坚忍都服务于与神同行；不是每位信徒每天感受同样强烈。", "section": "当信的真理"}, {"n": 37, "title": "死时的益处", "commentary": "信徒灵魂得完全圣洁并与主同在，身体仍与基督联合，安歇等候复活。死亡不能拆毁基督与属他之人的关系。", "section": "当信的真理"}, {"n": 38, "title": "复活的益处", "commentary": "基督使信徒全人得荣，在审判中被公开接纳，永远享受神。最终盼望包括身体与新造，不只灵魂脱离世界。", "section": "当信的真理"}, {"n": 39, "title": "人的责任", "commentary": "神要求顺服他所启示的旨意；这不是救恩价格，而是受造者本有责任，也是蒙救赎者感恩的道路。", "section": "十诫与伦理"}, {"n": 40, "title": "初赐的顺服准则", "commentary": "神起初使人知道道德要求；堕落后人的良知仍有见证，却需要神的话纠正，不能把直觉当作最终标准。", "section": "十诫与伦理"}, {"n": 41, "title": "十诫概括", "commentary": "十诫浓缩道德律法；解读时既看禁止也看积极责任，并放回神先拯救、后引导的盟约次序。", "section": "十诫与伦理"}, {"n": 42, "title": "爱神爱人", "commentary": "全心爱神与爱邻舍概括十诫；爱不是绕开具体命令的感觉，而是让每条命令显明其目的与方向。", "section": "十诫与伦理"}, {"n": 43, "title": "十诫序言", "commentary": "出埃及的神先宣告他是谁、做了什么，再命令人。基督徒伦理同样从救赎身份出发，而非靠守诫赢得拯救。", "section": "十诫与伦理"}, {"n": 44, "title": "序言的意义", "commentary": "神的主权、救赎和盟约关系共同要求顺服。回忆恩典能拆毁抱怨，使命令被看为救赎主引导的道路。", "section": "十诫与伦理"}, {"n": 45, "title": "第一诫焦点", "commentary": "神要求独一忠诚；日常偶像可能不是雕像，而是把安全、成功或某个人提升为不可失去的终极依靠。", "section": "十诫与伦理"}, {"n": 46, "title": "第一诫积极责任", "commentary": "认识并承认真神，专一敬拜荣耀他。神学知识的目标不是积累优越感，而是敬畏、信靠、爱与顺服。", "section": "十诫与伦理"}, {"n": 47, "title": "第一诫禁止", "commentary": "无神、假神与不把真神当神都违反此诫。名义信仰与实际人生主权可能分离，需要真实省察。", "section": "十诫与伦理"}, {"n": 48, "title": "在神面前", "commentary": "神完全知道人的忠诚与隐藏偶像；无处可藏不只带来警戒，也给受误解的忠信者安慰。", "section": "十诫与伦理"}, {"n": 49, "title": "第二诫焦点", "commentary": "敬拜方式同敬拜对象一样受神规范。热诚不能自动使自创宗教动作成为合宜敬拜。", "section": "十诫与伦理"}, {"n": 50, "title": "第二诫积极责任", "commentary": "保持神所设立的敬拜与条例，按圣经参与讲道、祷告、圣礼。外在秩序须服务真实敬虔。", "section": "十诫与伦理"}, {"n": 51, "title": "第二诫禁止", "commentary": "不可用偶像或人的发明取代神所启示的亲近方式。艺术、教学图像与敬拜用途要区别，不应草率混同所有视觉表达。", "section": "十诫与伦理"}, {"n": 52, "title": "第二诫理由", "commentary": "神的主权与盟约热爱使敬拜不可随意；代际影响是真实的，但不允许把父母罪责机械算给悔改的子女。", "section": "十诫与伦理"}, {"n": 53, "title": "第三诫焦点", "commentary": "神的名连于他的身份、话语与作为，不能当作方便的口头工具；宗教语言越熟悉，越需警觉轻慢。", "section": "十诫与伦理"}, {"n": 54, "title": "第三诫积极责任", "commentary": "以敬畏使用神的名、称号、属性、话语与条例，使言语及生活共同见证他。", "section": "十诫与伦理"}, {"n": 55, "title": "第三诫禁止", "commentary": "妄称、假誓、轻薄使用及借神之名遮蔽恶事都属于亵慢。宣称神告诉我并不能免去证据和问责。", "section": "十诫与伦理"}, {"n": 56, "title": "第三诫理由", "commentary": "人也许逃过社会惩罚，神却不误判。宗教职位不保护亵慢者，反而使其责任更重。", "section": "十诫与伦理"}, {"n": 57, "title": "第四诫焦点", "commentary": "时间也属于神；七日节律让受造者以敬拜与安息承认自己不是世界的维持者。", "section": "十诫与伦理"}, {"n": 58, "title": "第四诫积极责任", "commentary": "分别神所定的时间归他，尤其整日的圣安息；安息不是冷漠不动，而是转向神并实践必要与怜悯。", "section": "十诫与伦理"}, {"n": 59, "title": "主日的日序", "commentary": "小要理把创造周第七日与基督复活后七日第一日连起来，理解为基督徒主日；应承认不同教会对此的解释差异。", "section": "十诫与伦理"}, {"n": 60, "title": "分别圣日的方法", "commentary": "从平日事务转向共同和个人敬拜，同时保留必要与怜悯工作。预备与合理休息能使家人同享恩惠。", "section": "十诫与伦理"}, {"n": 61, "title": "第四诫禁止", "commentary": "疏忽、草率敬拜，以及用不必要的日常劳作或娱乐吞没圣日，都显明心未把主放在中心。", "section": "十诫与伦理"}, {"n": 62, "title": "第四诫理由", "commentary": "神赐六日处理事务，自己立下安息榜样并分别圣日。恩赐的节律呼吁信靠，而非以忙碌证明自我价值。", "section": "十诫与伦理"}, {"n": 63, "title": "第五诫焦点", "commentary": "家庭与社会关系中的尊荣保护秩序；这同时约束掌权者如何使用权柄，不能只向弱者索取顺服。", "section": "十诫与伦理"}, {"n": 64, "title": "第五诫积极责任", "commentary": "各人按所处关系尊重与尽责；父母、领袖与长者也应以关怀、公义和榜样保护所托付的人。", "section": "十诫与伦理"}, {"n": 65, "title": "第五诫禁止", "commentary": "轻看关系责任、滥权或不尽责任都受此诫责备。反对虐待和合理申诉不自动等于不孝或悖逆。", "section": "十诫与伦理"}, {"n": 66, "title": "第五诫应许", "commentary": "生命与福祉的应许揭示神喜悦的秩序，不是保证每位孝顺者必活到某年龄，也不让早逝者背负道德污名。", "section": "十诫与伦理"}, {"n": 67, "title": "第六诫焦点", "commentary": "人的生命属于神，因此禁止谋杀并呼吁保护生命。尊严不随病弱、残障、年老或贫困而降低。", "section": "十诫与伦理"}, {"n": 68, "title": "第六诫积极责任", "commentary": "采取合宜途径保护自己与他人的生命，包括饮食休息、照护、和平与援助。关怀身体也是属灵责任。", "section": "十诫与伦理"}, {"n": 69, "title": "第六诫禁止", "commentary": "不义杀害、自毁以及助长危险的恶意和冷漠，都背离保护生命的目的；具体法律与伦理案例须审慎区分。", "section": "十诫与伦理"}, {"n": 70, "title": "第七诫焦点", "commentary": "神保护婚约忠诚、身体尊严与性的圣洁；人不是供他人消费的对象。", "section": "十诫与伦理"}, {"n": 71, "title": "第七诫积极责任", "commentary": "在思想、言语、行为中守洁并保护彼此贞洁；忠诚、合宜界限与真实关怀比外表规训更深。", "section": "十诫与伦理"}, {"n": 72, "title": "第七诫禁止", "commentary": "不洁思想、挑逗言语及性行为的越界都受约束；受害者遭遇侵犯不等于受害者犯了奸淫。", "section": "十诫与伦理"}, {"n": 73, "title": "第八诫焦点", "commentary": "神保护邻舍合宜拥有与使用财物的权利；偷盗包括公开夺取与隐蔽不公。", "section": "十诫与伦理"}, {"n": 74, "title": "第八诫积极责任", "commentary": "诚实劳动、节制消费、守约付款，促进自己和邻舍的正当生活条件，而非只问如何不违法。", "section": "十诫与伦理"}, {"n": 75, "title": "第八诫禁止", "commentary": "欺诈、侵占、损坏财产与阻碍邻舍正当获益都受此诫检验；经济成功并不自动证明手段公义。", "section": "十诫与伦理"}, {"n": 76, "title": "第九诫焦点", "commentary": "真话与名誉关系到邻舍能否公正生活；虚假见证伤害的不只事实，也包括人的社会处境。", "section": "十诫与伦理"}, {"n": 77, "title": "第九诫积极责任", "commentary": "诚实维护自己与邻舍的好名声，尤其在裁判和冲突中。维护名誉不等于隐瞒已证实的伤害行为。", "section": "十诫与伦理"}, {"n": 78, "title": "第九诫禁止", "commentary": "造谣、扭曲、轻率转发、恶意暗示与不实沉默都可能伤害真理；先核实再传播。", "section": "十诫与伦理"}, {"n": 79, "title": "第十诫焦点", "commentary": "神的要求进入欲望层面；罪的根源不能只靠限制外在动作解决，心也需要恩典更新。", "section": "十诫与伦理"}, {"n": 80, "title": "第十诫积极责任", "commentary": "学习满足、对邻舍成功欢喜，并以公义慈爱看待自己所得。知足不等于接受剥削或停止改善处境。", "section": "十诫与伦理"}, {"n": 81, "title": "第十诫禁止", "commentary": "嫉妒、贪恋与对神安排的怨恨侵蚀相爱；应区分正常需要、合宜愿望与想侵占他人的欲望。", "section": "十诫与伦理"}, {"n": 82, "title": "无人完全守律法", "commentary": "堕落后没有普通人能在今生完全顺服；这一现实催促人到基督面前，而不是宣布伦理努力无意义。", "section": "十诫与伦理"}, {"n": 83, "title": "罪有轻重", "commentary": "每罪都真实冒犯神，但性质、情境、知识与责任不同会加重罪；不能以大家都犯罪抹平严重伤害。", "section": "十诫与伦理"}, {"n": 84, "title": "罪应受的结局", "commentary": "罪配得神公义的忿怒与咒诅；认识审判的严肃，使赦免显为恩典而非神理所当然的义务。", "section": "十诫与伦理"}, {"n": 85, "title": "逃避审判之路", "commentary": "神呼召人信靠基督、悔改并勤用施恩途径。途径不能赚救恩，却是神正常赐人与坚固生命的方式。", "section": "信心与施恩途径"}, {"n": 86, "title": "信靠基督", "commentary": "得救信心把自己交托给福音中的基督，单单倚靠他拯救；不是只同意耶稣曾存在或认同道德教训。", "section": "信心与施恩途径"}, {"n": 87, "title": "悔改归神", "commentary": "认识罪的严重与基督怜悯，使人忧伤恨恶罪并实际转回神。悔改不支付赦免的价格。", "section": "信心与施恩途径"}, {"n": 88, "title": "外在施恩途径", "commentary": "圣道、圣礼、祷告是基督通常传递救恩益处的方法；平常、公开、持续的教会生活因此极有重量。", "section": "信心与施恩途径"}, {"n": 89, "title": "圣道的功效", "commentary": "圣灵用读经，尤其宣讲，显出罪、启明基督并建立圣洁与安慰；技巧不能替代真理，真理也不免除清楚表达。", "section": "信心与施恩途径"}, {"n": 90, "title": "领受圣道的方法", "commentary": "勤预备、祷告、留心、信受、记存并实践。听道的目标不止评价讲员，而是让神的话改变生活。", "section": "信心与施恩途径"}, {"n": 91, "title": "圣礼如何有效", "commentary": "圣礼功效不来自仪式或施行者本身，而来自基督祝福与圣灵工作，并要求真实的信心领受。", "section": "信心与施恩途径"}, {"n": 92, "title": "圣礼的本质", "commentary": "可见记号指向并印证基督的恩典；它不只表达人的记念，也宣告神的应许。", "section": "信心与施恩途径"}, {"n": 93, "title": "两项圣礼", "commentary": "新约由基督设立洗礼与圣餐；教会可有其他有益仪式，却不能把它们提升为同等的救恩圣礼。", "section": "信心与施恩途径"}, {"n": 94, "title": "洗礼意义", "commentary": "奉三一神名的水礼标明归入基督与盟约群体，指向洁净与新生命；记号与重生不可机械画等号。", "section": "信心与施恩途径"}, {"n": 95, "title": "施洗对象", "commentary": "未入教会者须认信后受洗，信徒儿女也在盟约群体中领受记号；这是改革宗约观，与浸信会立场应诚实区别。", "section": "信心与施恩途径"}, {"n": 96, "title": "圣餐意义", "commentary": "基督设立饼杯，使信徒记念他的死，借信心得属灵滋养。基督已一次献祭，圣餐并不再次使他受死。", "section": "信心与施恩途径"}, {"n": 97, "title": "合宜领受圣餐", "commentary": "省察认识、信心、悔改、爱与新顺服；目的不是拒绝软弱而愿悔改的人，而是防止无知与顽梗的亵慢。", "section": "信心与施恩途径"}, {"n": 98, "title": "祷告本质", "commentary": "借基督向神呈上合乎其旨意的心愿，同时认罪和感谢；祷告是儿女关系的表达，不是操控结果的技术。", "section": "祷告与主祷文"}, {"n": 99, "title": "祷告准则", "commentary": "整本圣经教人祷告，主祷文给出特别模式；既可直接使用，也可沿其次序展开自己的呼求。", "section": "祷告与主祷文"}, {"n": 100, "title": "主祷文称呼", "commentary": "天父的慈爱给人坦然，天上的威严唤起敬畏；我们的提醒我们与众圣徒同为一家，不只有我的需要。", "section": "祷告与主祷文"}, {"n": 101, "title": "第一祈求", "commentary": "求神使自己的名被尊为圣，并使自己成为尊荣他的器皿；不是给神增加原本缺少的圣洁。", "section": "祷告与主祷文"}, {"n": 102, "title": "第二祈求", "commentary": "求神国扩展、黑暗被破坏、教会被建立并盼基督再来；神国不可简单等同某一国家或政治计划。", "section": "祷告与主祷文"}, {"n": 103, "title": "第三祈求", "commentary": "求地上顺服神如天上那样甘心完全；既求环境改变，也求自己的意志被神的话塑造。", "section": "祷告与主祷文"}, {"n": 104, "title": "第四祈求", "commentary": "承认身体、工作与食物都依赖父，求足够并感恩使用；我们的饮食也把邻舍的饥饿带进祷告。", "section": "祷告与主祷文"}, {"n": 105, "title": "第五祈求", "commentary": "以基督恩典求赦免，并求恩典使自己愿意饶恕；饶恕邻舍不是购买神赦免的功劳。", "section": "祷告与主祷文"}, {"n": 106, "title": "第六祈求", "commentary": "求父保守我们远离试探、在临到的试炼中扶持并救脱恶者；祷告者也应采取实际逃避罪的行动。", "section": "祷告与主祷文"}, {"n": 107, "title": "主祷文结语", "commentary": "把国度、权柄与荣耀归神，凭他的能力和信实求成全。阿们表达真实愿望与信靠，不是让请求自动生效的咒语。", "section": "祷告与主祷文"}], "lc": [{"n": 1, "title": "人生最高目的", "commentary": "神既是创造者，也是人的终极福乐；荣耀他与享受他不可拆开。大要理用“最高”把一切次要目的归入敬拜的秩序。工作与家庭有真实价值，却不能承受只有神能承受的终极期待。", "section": "神与启示"}, {"n": 2, "title": "认识神的根据", "commentary": "人的内在意识与受造界见证神，圣道与圣灵使这认识足以引人得救。一般启示不等于一条绕过基督的救恩路径；看见创造应唤起感恩，也显出人压抑真理的责任。", "section": "神与启示"}, {"n": 3, "title": "什么是神的话", "commentary": "旧新约圣经是信仰与顺服的准则；启示的权威不来自教会投票。将教会历史、信条与经验放在圣经之下，并不取消这些辅助的价值，而是给它们正确位置。", "section": "神与启示"}, {"n": 4, "title": "圣经如何显明神圣权威", "commentary": "圣经的尊严、统一、救恩目的与功效是认出其来源的见证，圣灵借道在心里作确证。这里不是以私人感动代替经文，而是说明罪人如何被带到神的话面前信服。", "section": "神与启示"}, {"n": 5, "title": "圣经教导的两方面", "commentary": "认识神与回应神构成全书骨架。大要理前半讲当信的真理，后半讲当尽的责任；伦理建立在神是谁及他所施的救恩之上。", "section": "神与启示"}, {"n": 6, "title": "圣经使人认识神什么", "commentary": "神的本性、位格、旨意及其执行构成接下来的次序。不要只搜集抽象属性，须看这些真理怎样在创造、护理与救赎中使人敬畏并安稳。", "section": "神与启示"}, {"n": 7, "title": "神的本性", "commentary": "神无限、永恒、不变而完全圣洁。神的属性不是彼此限制的零件：公义不是爱的缺口，慈爱也不是圣洁的退让；十架尤其显明这些完全的一致。", "section": "神与启示"}, {"n": 8, "title": "只有一位真神", "commentary": "独一神不是诸神中最强的一位，而是唯一自有的创造主。多神崇拜与把财富、国家、成就当作终极依靠，在不同层面都违背这独一归属。", "section": "神与启示"}, {"n": 9, "title": "独一神的三个位格", "commentary": "父、子、圣灵同享不可分割的神性；位格有分别，本质不是三份。救恩使人借圣子、在圣灵里亲近圣父；不是从三位中挑一个更愿意帮助我们的神。", "section": "神与启示"}, {"n": 10, "title": "三位格的特性", "commentary": "父不受生，子永恒受生，灵永恒发出；这些是永恒位格关系，不是受造时间里的出生顺序。不能由“子”推论圣子较晚出现或本质低于父。", "section": "神与启示"}, {"n": 11, "title": "子与灵同为真神", "commentary": "圣经把神的名字、属性、作为与敬拜归于子与灵。把圣灵仅当作能力、把基督当作最高受造者，都破坏新约救恩与敬拜的根基。", "section": "神与启示"}, {"n": 12, "title": "永恒旨意", "commentary": "神以智慧与圣洁定意万事；这不使他成为罪的作者，也不取消受造者的选择与责任。信徒从定旨得到谦卑与安慰，不从中寻找消极不行动的借口。", "section": "神与启示"}, {"n": 13, "title": "天使与人的拣选", "commentary": "神在基督里拣选蒙恩之人，不因预见他们有功德；其余的人因自己的罪受审判。教导应引向敬拜与传福音，不能用猜测隐秘旨意折磨忧伤的人。", "section": "神与启示"}, {"n": 14, "title": "旨意如何实现", "commentary": "创造与护理是神定旨在历史中的执行。神不只设定一个起点便退出世界；他使用受造途径完成目的，因此祷告、劳动与传福音都有真实意义。", "section": "神与启示"}, {"n": 15, "title": "创造的工作", "commentary": "万有因神的话从无而有，并被宣告美善。受造物不具有自足神性，人也不能把材料世界视为本质邪恶；这为身体、劳动和秩序奠定根基。", "section": "创造、护理与堕落"}, {"n": 16, "title": "天使的受造", "commentary": "天使是有能力、智慧并有道德责任的灵性受造者，绝非神性的分身。圣经记载他们服事神，不容人向天使求救或让好奇的天使学抢占基督的位置。", "section": "创造、护理与堕落"}, {"n": 17, "title": "人的受造", "commentary": "男女按神形象受造，拥有认识、公义与圣洁，并承担治理使命。尊严来自创造者，不来自能力、年龄或社会效用；堕落使人败坏，却不许可轻看任何人的生命。", "section": "创造、护理与堕落"}, {"n": 18, "title": "神护理万有", "commentary": "神保存并治理一切受造物与行动，既掌管整体，也顾及细节。承认护理不等于把灾难简单归咎于受害者的某项罪；约伯记提醒人谦卑面对隐藏之事。", "section": "创造、护理与堕落"}, {"n": 19, "title": "神对天使的护理", "commentary": "有些天使被保守，有些背叛后受限制与审判；邪恶势力不是与神势均力敌的第二个永恒本源。属灵争战应使人投靠基督，而不是迷信恐惧。", "section": "创造、护理与堕落"}, {"n": 20, "title": "人原初的圣约处境", "commentary": "神安置人于园中，赐使命、婚姻、安息与试验。生命与顺服的关系显示人的责任；“行为之约”是对这些经文关系的归纳，并非创世记出现的原词。", "section": "创造、护理与堕落"}, {"n": 21, "title": "人是否持守原初状态", "commentary": "始祖真实违命，从原有正直中堕落。诱惑有外在来源，人却不能因此免除责任；救恩的问题始于人与神的背约关系，而不只是资讯不足。", "section": "创造、护理与堕落"}, {"n": 22, "title": "全人类在亚当里堕落", "commentary": "亚当具有代表地位，罪责与败坏涉及由通常生育而来的人类。与基督的代表性对读罗马书五章，才能明白原罪不只是模仿一个坏榜样。", "section": "创造、护理与堕落"}, {"n": 23, "title": "堕落后的状态", "commentary": "罪与愁苦彼此关联：人不仅遭遇不幸，也对神有罪责。福音同时处理人与神的地位、内在败坏与最终死亡，不能缩减为一种心理安慰。", "section": "创造、护理与堕落"}, {"n": 24, "title": "罪是什么", "commentary": "凡不符合神律法的状态与行为都属于罪。过犯不止是公开犯法；动机、欲望与当行而不行同样须受光照。以神的圣洁为尺度，才能避免自义。", "section": "创造、护理与堕落"}, {"n": 25, "title": "堕落状态中的罪性", "commentary": "亚当的罪责、原初公义的丧失与全人的败坏组成原罪的描述，并结出实际过犯。全然败坏指范围遍及全人，不指每个人每时都恶到最大程度。", "section": "创造、护理与堕落"}, {"n": 26, "title": "原罪如何传递", "commentary": "人类共同的败坏随通常生育延续，不是家庭教育失误才开始的。基督由圣灵感孕而无罪；不可把本问误解为身体、生育或婚姻本身污秽。", "section": "创造、护理与堕落"}, {"n": 27, "title": "堕落带来的愁苦", "commentary": "人与神隔绝，落在咒诅、罪辖制与死亡之下。圣经对苦难的诊断比“努力不够”更深，因此牧养不能只提供生活技巧而省略和好与救赎。", "section": "创造、护理与堕落"}, {"n": 28, "title": "今世罪的刑罚", "commentary": "内心昏暗、刚硬与外在生活的破碎显出审判的现实。但本问描述普遍堕落处境，不授权人将某次疾病或灾难机械认作某人特定罪行的报应。", "section": "创造、护理与堕落"}, {"n": 29, "title": "来世罪的刑罚", "commentary": "神的最终审判具有永恒分量；失去神恩惠与承受忿怒不是无关紧要的象征。教导审判应以诚恳呼召悔改为目的，不以猎奇描绘满足恐惧。", "section": "创造、护理与堕落"}, {"n": 30, "title": "神是否任人灭亡", "commentary": "恩典之约源于神主动的怜悯；人无法自救，神却预备救主。认识罪的深度不应使人逃离基督，而应显出救恩完全出于白白恩典。", "section": "圣约与中保"}, {"n": 31, "title": "恩典之约与谁设立", "commentary": "大要理从基督作为末后亚当、并在他里面的选民来表述圣约的救恩根基。须同时对读可见教会与信徒儿女的施行层面，不能取消外在圣约责任。", "section": "圣约与中保"}, {"n": 32, "title": "恩典在圣约中怎样显明", "commentary": "神提供中保并赐圣灵，使人能够信靠与顺服。信心是领受恩典的途径，不是人先交出的入场功德；顺服是被救赎者真实而必需的回应。", "section": "圣约与中保"}, {"n": 33, "title": "圣约是否总以同一方式施行", "commentary": "同一恩典之约有旧新约不同施行。连续性保障旧约信徒同靠基督，推进性说明基督来临后祭祀与影儿不再原样持续。", "section": "圣约与中保"}, {"n": 34, "title": "旧约的恩典施行", "commentary": "应许、预言、献祭、割礼与逾越节等指向尚未来到的中保。旧约信徒并非靠牛羊血独立得救，而是借这些途径信靠神应许的救赎。", "section": "圣约与中保"}, {"n": 35, "title": "新约的恩典施行", "commentary": "基督已经显现，圣道、洗礼与圣餐更清楚向万民施行应许。外在形式更简明，成全的实质更清晰；简明不等于不再需要有形教会与礼仪。", "section": "圣约与中保"}, {"n": 36, "title": "恩典之约的中保", "commentary": "永恒圣子成为真人，在一位格中有完整神人二性。中保不是夹在神与人之间的半神；唯有这位救主能代表我们并带我们到父面前。", "section": "圣约与中保"}, {"n": 37, "title": "圣子怎样成为人", "commentary": "基督取真实身体与理性灵魂，由圣灵感孕、童女所生且无罪。他并非只穿上肉体外壳；完整人性保证他真实经历人的软弱，却没有罪。", "section": "圣约与中保"}, {"n": 38, "title": "中保为何必须是神", "commentary": "只有真神能托住人性担当审判，使顺服与献祭具有足够价值，并胜过死亡。救赎的能力不来自人性被扩大，而来自这位中保真正是神。", "section": "圣约与中保"}, {"n": 39, "title": "中保为何必须是人", "commentary": "代表人须与人同有血肉，在人所失败的地方顺服并受死。他与我们的联合不是抽象同情；他以真实的人性完成救赎。", "section": "圣约与中保"}, {"n": 40, "title": "为何神人二性须在一位格中", "commentary": "救赎不是两个人合作分工，而是同一位子按两性行动；这样他的受苦与顺服确实是神子的救赎作为。不可将神性说成受造可死，也不可分裂基督。", "section": "圣约与中保"}, {"n": 41, "title": "为什么称为耶稣", "commentary": "这个名字指向他拯救自己的百姓脱离罪。救恩不只是从困境中出来，而是从罪责、罪权与罪的结局中被释放；名字把使命放在中心。", "section": "圣约与中保"}, {"n": 42, "title": "为什么称为基督", "commentary": "受膏者由圣灵装备履行先知、祭司、君王三职。三职不是三个互相替代的比喻，而是从无知、罪债与悖逆三个层面说明我们需要他。", "section": "圣约与中保"}, {"n": 43, "title": "基督的先知职分", "commentary": "他借圣道与圣灵显明父及救恩旨意。今日认识神不能绕过基督另寻更高启示；听他也意味着接受整本圣经的见证。", "section": "圣约与中保"}, {"n": 44, "title": "基督的祭司职分", "commentary": "一次献上自己满足公义，并长远为属他的人代求。献祭不需要在圣餐中重演；代求也不是不断补足十字架不足的功效。", "section": "圣约与中保"}, {"n": 45, "title": "基督的君王职分", "commentary": "他召聚、治理、保护教会，约束并终必击败仇敌。其国度不等于某个人间政治计划；在他权下生活，首先是悔改、顺服与坚忍。", "section": "圣约与中保"}, {"n": 46, "title": "基督的降卑", "commentary": "从道成肉身到受死埋葬，他在仆人处境中履行顺服。神性本身没有减少，尊贵的子却真实承担低微与苦楚；降卑表达自愿的爱。", "section": "圣约与中保"}, {"n": 47, "title": "在成孕与出生中降卑", "commentary": "创造万有的子生于卑微处境，成为律法之下的人。圣诞的核心不是浪漫气氛，而是救主进入我们的历史与责任之中。", "section": "圣约与中保"}, {"n": 48, "title": "在一生中降卑", "commentary": "基督面对试探、贫乏与逼迫，仍完全遵行父旨意。顺服的一生与十字架不可分开；他不仅替我们承担刑罚，也成全我们未能履行的义。", "section": "圣约与中保"}, {"n": 49, "title": "在死亡中降卑", "commentary": "十字架兼有身体痛楚、羞辱与担当罪审判的深度。父与子没有本体分裂；基督按中保使命在真实苦难中完成赎罪。", "section": "圣约与中保"}, {"n": 50, "title": "死后如何继续降卑", "commentary": "埋葬并处于死的状态与权势之下直到第三日，是本问解释降卑的重点。与海德堡四十四问侧重十架苦楚的用法有别；不表示死后继续补赎。", "section": "圣约与中保"}, {"n": 51, "title": "基督的升高", "commentary": "复活、升天、坐右边与再来构成升高次序。救主不是只留下榜样便从舞台退出；他如今真实掌权，将使已完成的救赎走向公开实现。", "section": "圣约与中保"}, {"n": 52, "title": "复活中的升高", "commentary": "他以同一身体复活，却进入荣耀生命；复活证明死权败退并保证属他者复活。救恩的希望因此具有身体和历史维度，绝非灵魂自我安慰。", "section": "圣约与中保"}, {"n": 53, "title": "升天中的升高", "commentary": "复活的主进入天上，为教会预备地方并赐恩。他的人性仍是真实人性，不因升天遍在于一切饼酒或物件之中。", "section": "圣约与中保"}, {"n": 54, "title": "坐在父右边", "commentary": "“右边”表达尊荣、权柄与治理，不是描画神的身体方位。基督以元首身份赐恩、聚集教会，使仇敌不能阻断救恩目的。", "section": "圣约与中保"}, {"n": 55, "title": "基督如何代求", "commentary": "他以已完成的顺服与献祭，在父面前为属他者施行中保职事。无需想象他劝服一位不愿爱人的父；父差遣子的爱正是代求的根源。", "section": "圣约与中保"}, {"n": 56, "title": "再来中的升高", "commentary": "他将以荣耀公开审判，显明属他的子民并胜过邪恶。盼望再来不支持算日子，而促使教会忠心、警醒与向世界作见证。", "section": "圣约与中保"}, {"n": 57, "title": "中保取得什么益处", "commentary": "和好与恩典、以及将来的荣耀，出于基督的救赎。不要将各项恩惠当作与基督分离的奖品；领受者首先属于救主本人。", "section": "救恩、教会与终局"}, {"n": 58, "title": "如何分享基督的益处", "commentary": "圣灵将救赎应用在人身上，使人借信与基督联合。客观完成与主观施行有分别而不可分割；单知道救赎故事不等于已在信心中领受它。", "section": "救恩、教会与终局"}, {"n": 59, "title": "谁分享基督的救赎", "commentary": "神所拣选、在历史中蒙召相信的人，得着基督成全的救恩。旧约与新约的蒙恩者同靠这一位中保，不存在彼此平行的得救制度。", "section": "救恩、教会与终局"}, {"n": 60, "title": "未闻福音与自然之光", "commentary": "本问否认人靠自然宗教或道德诚恳即可得救；救恩只在基督里。这应推动宣教而非自义；对于无能力听懂者的议题须一并读威告十章三节，不擅自推断个人结局。", "section": "救恩、教会与终局"}, {"n": 61, "title": "听道与在教会中是否都得救", "commentary": "外在接触福音与内在得救有分别。受教与参加教会是真实恩惠，却不能代替信靠基督；这也不意味着可轻视神设立的教会途径。", "section": "救恩、教会与终局"}, {"n": 62, "title": "什么是可见教会", "commentary": "在世界中认信基督的人及其儿女构成可见教会的圣约群体。这是历史中可辨认的共同体，并非说其中每个人都已重生。", "section": "救恩、教会与终局"}, {"n": 63, "title": "可见教会的特权", "commentary": "神特别眷顾并在其中赐圣道、圣礼与牧养。特权带来责任，不能成为自满的理由；与教会相交应使人更认真听信福音。", "section": "救恩、教会与终局"}, {"n": 64, "title": "什么是无形教会", "commentary": "历世历代被神拣选、最终与基督联合的整体。无形不是没有实际聚会的个人主义宗教，而是强调神完全知道其救赎群体的真实范围。", "section": "救恩、教会与终局"}, {"n": 65, "title": "无形教会分享的特别益处", "commentary": "与基督联合，使人分享今生的恩典与来世的荣耀。所有益处以同一位中保为中心；救恩的各阶段不是互不相干的独立项目。", "section": "救恩、教会与终局"}, {"n": 66, "title": "与基督联合", "commentary": "圣灵使蒙恩者与基督有真实而属灵的联结。联合不是本质混合，也不是人与神同等；如肢体与元首的关系，生命与益处都从他而来。", "section": "救恩、教会与终局"}, {"n": 67, "title": "有效呼召", "commentary": "神借圣道与圣灵光照心智、更新意志，使罪人甘心回应基督。有效不等于强迫不愿意的人进入天国，而是改变不愿意的心。", "section": "救恩、教会与终局"}, {"n": 68, "title": "谁蒙有效呼召", "commentary": "外在邀请可以临到多人，内在使人得生命的呼召是神救恩工作的施行。不能因自己不知谁蒙拣选，就缩小向所有人传福音的呼召。", "section": "救恩、教会与终局"}, {"n": 69, "title": "在恩典中与基督相通", "commentary": "称义、得儿子名分、成圣等恩惠属于与基督相通的生活。先认识这些礼物共同来自他，再分别各恩惠的性质，可避免彼此混淆。", "section": "救恩、教会与终局"}, {"n": 70, "title": "称义是什么", "commentary": "神按基督的义赦罪并接纳罪人为义，不以人的内在更新为宣告根据。它是司法性的接纳，并非说人从此行为已毫无瑕疵。", "section": "救恩、教会与终局"}, {"n": 71, "title": "称义为何完全出于恩典", "commentary": "基督真实满足公义，而救主本身与领受他的信心都不是罪人的功劳。白白恩典并不表示神忽略公义，而是罪人的代价由中保承担。", "section": "救恩、教会与终局"}, {"n": 72, "title": "使人称义的信心", "commentary": "信心认识福音的可信，并亲自领受、倚靠其中的基督。知识、同意与信赖不可简单割裂；只承认教义正确却拒绝投靠他，不是本问所说的信心。", "section": "救恩、教会与终局"}, {"n": 73, "title": "信心怎样称义", "commentary": "信心的作用在于领受基督，不在于它是一项值得奖赏的好行为。不要把“靠信心”偷偷变成“靠我信得够强”；软弱的信心所倚靠的救主仍然完全。", "section": "救恩、教会与终局"}, {"n": 74, "title": "得儿子名分", "commentary": "神为基督的缘故接纳信徒进入他的家，赐身份、亲近与承受产业的权利。这不把受造人变成神的本体之子，却真实改变祷告与生活关系。", "section": "救恩、教会与终局"}, {"n": 75, "title": "成圣是什么", "commentary": "圣灵更新全人，使人越来越向罪死、向义活。它与称义同时属于救恩却不是同一种动作；增长依靠恩典，也包含具体操练与争战。", "section": "救恩、教会与终局"}, {"n": 76, "title": "得生命的悔改", "commentary": "罪人看见罪与神的怜悯，忧伤恨罪并转向神。悔改不是只后悔后果，也不是必须先修好自己才可求恩；它朝向真实的新顺服。", "section": "救恩、教会与终局"}, {"n": 77, "title": "称义与成圣的分别", "commentary": "称义解决罪责与接纳的地位，成圣处理罪权与生命更新。前者完整宣告，后者渐进更新；混淆两者会使人不是靠行为求接纳，就是漠视圣洁。", "section": "救恩、教会与终局"}, {"n": 78, "title": "成圣为何不完全", "commentary": "残余败坏仍在，与圣灵所赐新生命争战。承认残罪不是降低标准；它使信徒每日悔改，并拒绝声称今生已经达到完全无罪。", "section": "救恩、教会与终局"}, {"n": 79, "title": "真信徒能否最终失落", "commentary": "保守的根据在神不变的旨意、基督代求与圣灵，而不在人的意志稳定性。暂时跌倒极其严重，神也借警告、管教与悔改保守他们。", "section": "救恩、教会与终局"}, {"n": 80, "title": "能否有可靠的得救确据", "commentary": "确据根植神应许、恩典在生命中的果子及圣灵见证，而非无根据的乐观。察验要引向基督，不能使人陷入永无止境的自我解剖。", "section": "救恩、教会与终局"}, {"n": 81, "title": "真信徒是否总有充分确据", "commentary": "信心可能因软弱、试探与犯罪而缺乏充分确信；缺少确信不自动证明没有真信心。与海德堡二十一问对读时，区分信靠基督与充分反省自身得救状态。", "section": "救恩、教会与终局"}, {"n": 82, "title": "与基督分享荣耀的范围", "commentary": "荣耀从今生的初尝，延伸到死后与末日的完全。这个次序避免把今生经历当成最终圆满，也避免把盼望推到与现实全无关系的远处。", "section": "救恩、教会与终局"}, {"n": 83, "title": "今生怎样初尝荣耀", "commentary": "平安、喜乐、与神相交及对将来的盼望，是荣耀的初熟果子。经历可有高低，不能以是否持续兴奋来衡量救恩真伪。", "section": "救恩、教会与终局"}, {"n": 84, "title": "人人是否都要死亡", "commentary": "死亡是罪所带来的结局，末日仍存活者则经历改变。对死亡的教导应结合基督胜过死权，既不否认现实恐惧，也不让恐惧成为最后结论。", "section": "救恩、教会与终局"}, {"n": 85, "title": "蒙赦免者为何仍会死", "commentary": "信徒之死不再是偿还罪债的刑罚，而在基督里成为进入与主同在的经过。赦免没有使人即时脱离所有堕落处境，却改变死亡的最终意义。", "section": "救恩、教会与终局"}, {"n": 86, "title": "死后立即与基督相通", "commentary": "信徒灵魂与基督同在，身体安息等候复活。中间状态不是炼狱，也不是最终新创造的全部；基督要拯救整个人。", "section": "救恩、教会与终局"}, {"n": 87, "title": "身体复活", "commentary": "义与不义者都将复活，身体与灵魂重新结合，结局有别。身体不是随用随弃的壳；基督复活使基督徒能尊重身体并盼望更新。", "section": "救恩、教会与终局"}, {"n": 88, "title": "复活之后是什么", "commentary": "最后审判显明神对全人类的公义判断。历史中的不义不会永远被遗忘；与此同时，审判的主正是为信徒舍己的救主。", "section": "救恩、教会与终局"}, {"n": 89, "title": "恶人在审判中的结局", "commentary": "罪被揭露，公义定罪，人与神恩惠隔绝并受刑罚。不要以此培育对人的轻蔑；今日仍是呼召悔改与传扬福音的时候。", "section": "救恩、教会与终局"}, {"n": 90, "title": "义人在审判中的结局", "commentary": "他们因基督被公开承认，在全人更新中与主永远同在。行为显明信心的果实，却不是购买永生的代价；终局是恩典的完成。", "section": "救恩、教会与终局"}, {"n": 91, "title": "神要求人的本分", "commentary": "对神启示的旨意作出顺服，是受造者应有的回应。救恩恢复顺服，不取消顺服；但应先区别履行责任与以行为赚取称义。", "section": "律法与全人伦理"}, {"n": 92, "title": "原初顺服的准则", "commentary": "道德律在人受造时已写在心里；十诫不是凭空新增一种与人性无关的任意要求。罪使认识受损，书面启示帮助人更清楚认识责任。", "section": "律法与全人伦理"}, {"n": 93, "title": "道德律是什么", "commentary": "神对全人完全、持续的圣洁要求，包括思想与行为。律法照出人的不足，也指示真实的爱；它不能被缩为最低限度不犯法。", "section": "律法与全人伦理"}, {"n": 94, "title": "堕落后律法仍有用途吗", "commentary": "虽不能借守律法使罪人称义，律法仍显明神与人的责任。问题不是律法坏了，而是罪人不能靠它恢复与神和好。", "section": "律法与全人伦理"}, {"n": 95, "title": "律法对所有人的用途", "commentary": "显出神圣洁、人应尽的本分与罪，使人认识需要救主。它也约束恶行；这不保证每个人都会从道德知识走到得救信心。", "section": "律法与全人伦理"}, {"n": 96, "title": "律法对未重生者的用途", "commentary": "使罪显明、唤醒良心并引人认识自身危险，也使拒不悔改者无可推诿。用律法传道必须同时指出福音，不把人留在绝望中。", "section": "律法与全人伦理"}, {"n": 97, "title": "律法对重生者的用途", "commentary": "信徒脱离律法作为定罪之约，却仍借律法认识基督、感恩与顺服。律法不再是赚生命的梯子，而是蒙救赎者学习爱的指引。", "section": "律法与全人伦理"}, {"n": 98, "title": "道德律的概述", "commentary": "十诫概括道德要求，须以整本圣经展开其意义。摘要不等于内容仅有十条外在禁令；登山宝训尤其显明它涉及内心。", "section": "律法与全人伦理"}, {"n": 99, "title": "解释十诫的规则", "commentary": "律法涉及全人；禁止一种罪也要求相反美德；当注意同类行为、动机、原因和机会，并在本分范围帮助他人遵行。解释规则防止只看字面最低要求，也防止无限扩张领袖权力。", "section": "律法与全人伦理"}, {"n": 100, "title": "读十诫注意哪些部分", "commentary": "序言、各诫命本身与所附理由互相说明。先听神是谁、做过什么，再听他的要求；蒙救赎身份为顺服提供根基。", "section": "律法与全人伦理"}, {"n": 101, "title": "十诫序言", "commentary": "神先表明他与百姓的关系及拯救，再提出诫命。出埃及的次序教人：顺服是蒙救赎后的感恩，不是挣脱奴役的购买条件。", "section": "律法与全人伦理"}, {"n": 102, "title": "前四诫的总纲", "commentary": "全人爱神概括对神的责任。爱不是模糊感觉，它在专一敬拜、尊荣神名与分别时间中取得具体形状。", "section": "律法与全人伦理"}, {"n": 103, "title": "第一诫的核心", "commentary": "只归属于独一真神，不将别的对象放在他的地位。现代偶像也可能是好事被绝对化，例如家庭、工作或自我形象。", "section": "律法与全人伦理"}, {"n": 104, "title": "第一诫要求什么", "commentary": "认识、信靠、敬畏、爱慕、盼望并顺服神。正面要求比“没有拜偶像”更丰富；一颗专属神的心会重新安排优先次序。", "section": "律法与全人伦理"}, {"n": 105, "title": "第一诫禁止什么", "commentary": "无神、不信、迷信、骄傲与对受造物的终极依赖都触犯本诫。自我审查应问：失去什么就觉得生命再无意义？那可能暴露竞争神位置的依靠。", "section": "律法与全人伦理"}, {"n": 106, "title": "在神面前是什么意思", "commentary": "没有一处心思或行为躲开神的察看，偶像也冒犯与人立约的主。神的同在既使伪装无用，也使真诚悔改者无须演给人看。", "section": "律法与全人伦理"}, {"n": 107, "title": "第二诫的核心", "commentary": "神规定如何敬拜他，人不可按自己的想象塑造神并以此敬拜。它与第一诫互补：不仅对象须正确，敬拜方式也须听神。", "section": "律法与全人伦理"}, {"n": 108, "title": "第二诫要求什么", "commentary": "领受、保存并使用神设立的圣道、祷告、圣礼与教会秩序。改革宗敬拜不是取消形式，而是让形式服从神的设立。", "section": "律法与全人伦理"}, {"n": 109, "title": "第二诫禁止什么", "commentary": "制造神的形象来敬拜、擅自增删神设立的敬拜，违背本诫。威敏对三一任何位格的图像具有严格措辞；须如实交代，不以一般艺术欣赏替代这项历史判断。", "section": "律法与全人伦理"}, {"n": 110, "title": "第二诫所附理由", "commentary": "神的主权、对圣约忠诚的要求与跨世代责任使敬拜严肃。关于儿女的警告不能理解为无辜孩子自动承受父母个人罪的最终定罪。", "section": "律法与全人伦理"}, {"n": 111, "title": "第三诫的核心", "commentary": "不可轻慢神的名；名字承载他所启示的身份与尊荣。信仰语言若成为操控别人、营销自己或掩护谎言的工具，同样违背本诫。", "section": "律法与全人伦理"}, {"n": 112, "title": "第三诫要求什么", "commentary": "尊重神的名称、属性、圣道、圣礼与作为，并以生活配合宣认。恭敬不是只降低音量，而是以真实、感恩与信靠使用神所赐的言语。", "section": "律法与全人伦理"}, {"n": 113, "title": "第三诫禁止什么", "commentary": "亵渎、假誓、妄用经文与借神之名为邪恶辩护均属禁止。不要把个人意见包装成“神告诉我”，借此免受查验与问责。", "section": "律法与全人伦理"}, {"n": 114, "title": "第三诫的警告理由", "commentary": "人的法庭可能忽视言语中的罪，神却必按公义判断。这不是禁止合理提问或哀歌，而是拒绝用神名服务虚假与轻慢。", "section": "律法与全人伦理"}, {"n": 115, "title": "第四诫的核心", "commentary": "神把时间分别出来，召人按他所定的节奏安息与敬拜。威敏将新约第一日表述为基督徒安息日；须与欧陆表述作细致比较。", "section": "律法与全人伦理"}, {"n": 116, "title": "第四诫要求什么", "commentary": "分别神所设立的时间，预备敬拜并安排日常事务。主日不是一周工作的残余空档，而是整周生活朝向神的节奏中心。", "section": "律法与全人伦理"}, {"n": 117, "title": "怎样守主日为圣", "commentary": "威敏要求全日从世俗事务与娱乐中安息，专于公共及个人敬拜，并容许必要与怜悯之工。应如实呈现其严格范围，而非改写为只参加一小时聚会。", "section": "律法与全人伦理"}, {"n": 118, "title": "为何特别吩咐管理者", "commentary": "家庭与其他有权安排事务者，不能只要求自己休息却使受托者无法安息。权柄须为他人的敬拜与身体需要创造条件。", "section": "律法与全人伦理"}, {"n": 119, "title": "第四诫禁止什么", "commentary": "忽略、草率或自义地守日，以及不合本分的事务与娱乐，破坏分别为圣。守日也不能成为冷酷拒绝救急与怜悯的理由。", "section": "律法与全人伦理"}, {"n": 120, "title": "第四诫所附理由", "commentary": "神的主权、六日工作的安排、自己的榜样与赐福，支撑安息节奏。不是人用休息迫使神赐福，而是领受造物主为人设立的秩序。", "section": "律法与全人伦理"}, {"n": 121, "title": "为什么说当记念", "commentary": "人容易忘记、事务需要预备，故记念是主动安排而非临时决定。预先整理工作与照顾责任，有助于让主日成为喜乐而非混乱。", "section": "律法与全人伦理"}, {"n": 122, "title": "后六诫的总纲", "commentary": "爱邻舍如同自己，涉及生命、关系、身体、财物、名誉与内心。真正爱人必须按照神定义的善，而非只追求对方立即满意。", "section": "律法与全人伦理"}, {"n": 123, "title": "第五诫的核心", "commentary": "尊重父母，学习在神设立的关系中彼此尽责。它不是赋予任何人不受限制的支配权；所有顺服都在神的更高权威之下。", "section": "律法与全人伦理"}, {"n": 124, "title": "父母一词包括谁", "commentary": "本问把原则延伸到年龄、恩赐与合宜职分关系中的尊长。延伸并不把每个长辈都变成全领域的权威，责任须按实际关系界定。", "section": "律法与全人伦理"}, {"n": 125, "title": "为何称为父母", "commentary": "这些称呼强调爱护、教养与关切，而非只强调等级。权柄若不能体现为对受托者的益处负责，就背离这幅家庭性的图画。", "section": "律法与全人伦理"}, {"n": 126, "title": "第五诫的总体范围", "commentary": "不同地位者与平辈都须各尽本分。大要理在此展开关系伦理，说明诫命不只是弱者服从，也同时审判掌权者的罪。", "section": "律法与全人伦理"}, {"n": 127, "title": "对尊长当有的尊荣", "commentary": "尊重、合宜顺服、感恩与扶助，是在主里履行关系责任。顺服不包括参与犯罪；提出真实申诉也不自动构成不敬。", "section": "律法与全人伦理"}, {"n": 128, "title": "卑位者的罪", "commentary": "蔑视、无故悖逆、咒骂与忘恩破坏关系；但不能把受害者揭发虐待归入这些罪。应按事实与合宜权力边界判断。", "section": "律法与全人伦理"}, {"n": 129, "title": "尊长对卑位者的本分", "commentary": "教导、供应、保护、公平治理，并以榜样建立对方。权位首先加重责任，不能用对自己的尊重来抵销对受托者的亏欠。", "section": "律法与全人伦理"}, {"n": 130, "title": "尊长的罪", "commentary": "苛刻、偏私、放任、滥权、使人犯罪或忽视保护，皆受本诫责备。教会与家庭权威不能成为逃避事实调查与合法责任的屏障。", "section": "律法与全人伦理"}, {"n": 131, "title": "平辈的本分", "commentary": "承认彼此尊严、欣赏恩赐并促进对方益处。平等并不要求恩赐相同；它使差异成为互助的条件而非比较价值的借口。", "section": "律法与全人伦理"}, {"n": 132, "title": "平辈的罪", "commentary": "嫉妒、轻视、争夺尊荣与因别人的损失而快意，都违背相爱。群体应建立坦诚肯定与公正分担，减少靠羞辱维持地位的风气。", "section": "律法与全人伦理"}, {"n": 133, "title": "第五诫的应许", "commentary": "长寿与昌盛表达神对有秩序生命的赐福，须放在整本圣经与护理中理解。不是每位孝顺者都获保证活到特定年龄，也不能责怪早逝者不孝。", "section": "律法与全人伦理"}, {"n": 134, "title": "第六诫的核心", "commentary": "人生命属于神，禁止非法夺取生命。经文所涉及公义战争与公共审判等须另按严格标准讨论，不能把个人报复纳入正当例外。", "section": "律法与全人伦理"}, {"n": 135, "title": "第六诫要求什么", "commentary": "保护自己与邻舍的生命、健康与安全，培养温柔、和好和实际照顾。救助危险中的人，比只宣称自己没有杀人更充分体现诫命。", "section": "律法与全人伦理"}, {"n": 136, "title": "第六诫禁止什么", "commentary": "仇恨、残酷、危险疏忽与非法伤害违反生命责任。不是只有造成死亡才算犯罪；言语羞辱、霸凌与拒绝可尽的救助，也须受省察。", "section": "律法与全人伦理"}, {"n": 137, "title": "第七诫的核心", "commentary": "性与婚姻在神设立的忠诚秩序中得其位置。禁奸淫保护配偶、儿女与群体的信任，不只是限制个人冲动。", "section": "律法与全人伦理"}, {"n": 138, "title": "第七诫要求什么", "commentary": "思想、言语与行为上的贞洁，守约忠诚、节制与合宜界限。对未婚与已婚者都有积极要求；不能把婚姻当作治疗一切欲望问题的自动机制。", "section": "律法与全人伦理"}, {"n": 139, "title": "第七诫禁止什么", "commentary": "奸淫、淫乱、色情与促成不洁的安排受禁止，也包括不义破坏婚约。面对创伤与侵害，要分清受害与施害，不把受侵害者的遭遇当作其道德污点。", "section": "律法与全人伦理"}, {"n": 140, "title": "第八诫的核心", "commentary": "尊重邻舍财物及神托付的资源。禁止偷盗同时要求正当取得、管理并分享；经济伦理不能仅凭是否钻过法律漏洞来判断。", "section": "律法与全人伦理"}, {"n": 141, "title": "第八诫要求什么", "commentary": "诚实交易、履约、勤劳、审慎管理与扶助缺乏者。保护邻舍的经济益处包括付公平工价、归还借物与不利用对方资讯劣势欺诈。", "section": "律法与全人伦理"}, {"n": 142, "title": "第八诫禁止什么", "commentary": "盗窃、诈骗、勒索、剥削、不义垄断及不负责任的挥霍皆违背托付。贪财与懒惰可能从相反方向伤害同一个爱邻舍责任。", "section": "律法与全人伦理"}, {"n": 143, "title": "第九诫的核心", "commentary": "不作假见证，保护事实与邻舍的名誉。真实见证尤其关系司法、公义与受害者；和平不能靠掩盖真相来维持。", "section": "律法与全人伦理"}, {"n": 144, "title": "第九诫要求什么", "commentary": "诚实、审慎查证、公正听取与合宜维护名誉。保护名誉不等于替犯罪者遮盖事实；应以真实与适当程序兼顾每个人的权利。", "section": "律法与全人伦理"}, {"n": 145, "title": "第九诫禁止什么", "commentary": "诽谤、谣言、断章取义、恶意猜测及应作见证却沉默，都可能违背本诫。资讯真实也须看传播目的、语境与自己是否有责任公开。", "section": "律法与全人伦理"}, {"n": 146, "title": "第十诫的核心", "commentary": "不可贪恋，显明神的律法穿透外在行为进入内心。即使尚未抢夺，嫉妒与妄图占有也暴露心没有满足于神的安排。", "section": "律法与全人伦理"}, {"n": 147, "title": "第十诫要求什么", "commentary": "以神的供应为满足，为邻舍所得的善喜乐并愿意促进它。知足不取消改善生活与追求公义，却拒绝以占有他人的份为幸福基础。", "section": "律法与全人伦理"}, {"n": 148, "title": "第十诫禁止什么", "commentary": "对自身处境抱怨、嫉妒邻舍与失序欲望，都是内心的悖逆。比较越频繁越容易将恩赐变成竞赛；感恩与慷慨帮助重整欲望。", "section": "律法与全人伦理"}, {"n": 149, "title": "今生能否完全守律法", "commentary": "堕落的人不能靠自己、也不能在今生达到毫无罪的完全顺服；每日都需赦免与更新。承认不足不是纵罪，而是使追求圣洁始终倚靠基督。", "section": "律法与全人伦理"}, {"n": 150, "title": "所有罪是否同样严重", "commentary": "每项罪都当受审判，但并非每项罪在性质与处境上同样严重。区分严重程度有助公义处置，不能用“人人都是罪人”抹去不同伤害。", "section": "律法与全人伦理"}, {"n": 151, "title": "哪些情况加重罪", "commentary": "身分责任、明知故犯、对象、方式、后果与时机等会加重罪。拥有教导与管理权的人尤其需要问责；特权不是较少责任的理由。", "section": "律法与全人伦理"}, {"n": 152, "title": "每项罪当受什么", "commentary": "罪违背神圣洁，配受他的忿怒与咒诅；任何小罪都不能靠自己轻轻抹去。福音显出赦免的宝贵，不许可把代价转嫁给无辜的人。", "section": "律法与全人伦理"}, {"n": 153, "title": "如何逃避罪的咒诅", "commentary": "悔改、信靠基督并勤用施恩途径，是神呼召罪人的回应。途径不是另一种购买救恩的工作清单，而是基督将救恩施行于人的方式。", "section": "施恩途径"}, {"n": 154, "title": "外在施恩途径", "commentary": "圣道、圣礼与祷告是通常途径。普通并不等于贫乏；不应以追逐特殊经历取代神已经清楚设立的牧养生活。", "section": "施恩途径"}, {"n": 155, "title": "圣道怎样使人得救", "commentary": "圣灵借圣道使人知罪、归信、成圣并坚固。功效不出于讲者技巧本身，也不取消认真解释与听从经文的责任。", "section": "施恩途径"}, {"n": 156, "title": "谁应读圣经", "commentary": "圣经属于全体神子民，不限圣职或精英；因此翻译成各地语言具有属灵必要。个人读经与教会共同教导相互帮助，不是彼此替代。", "section": "施恩途径"}, {"n": 157, "title": "怎样读圣经", "commentary": "存敬畏、信心与祷告，认真理解并应用。先辨认上下文、文体与论证，再把经文连于基督；不要用随机抽签取代理解。", "section": "施恩途径"}, {"n": 158, "title": "谁应传讲圣道", "commentary": "公开讲道是基督在教会设立并经合宜呼召、装备和认定的职分。不是每位擅长表达者都因此自动取得讲台权柄。", "section": "施恩途径"}, {"n": 159, "title": "应怎样传讲", "commentary": "忠于全备真理，清楚、有智慧、热切并顾及听众。讲道目的不是炫耀知识或操控情绪，而是使人认识、信靠并顺服基督。", "section": "施恩途径"}, {"n": 160, "title": "应怎样听道", "commentary": "预备、祷告、专心，以圣经查验并在生活中回应。听众不应盲从讲员，也不能以查验为名永远拒绝受教与悔改。", "section": "施恩途径"}, {"n": 161, "title": "圣礼怎样成为有效途径", "commentary": "圣灵与基督的应许使圣礼有效，不依赖施行者的个人圣洁或物质自动能力。认真领受而不迷信，正是改革宗圣礼观的张力。", "section": "施恩途径"}, {"n": 162, "title": "什么是圣礼", "commentary": "基督设立可见记号，表明、印证并在圣灵工作中将其益处施予信徒。记号向信心作见证，而非在圣道之外另设一位救主。", "section": "施恩途径"}, {"n": 163, "title": "圣礼的两部分", "commentary": "外在记号与内在所指有真实关系，却不可混同。水、饼、酒不变成恩典物质；记号也不只是空洞的心理提示。", "section": "施恩途径"}, {"n": 164, "title": "新约有几项圣礼", "commentary": "洗礼与圣餐由基督设立。教会可有其他合宜礼仪，却不能因此赋予它们与这两项同样的圣礼地位。", "section": "施恩途径"}, {"n": 165, "title": "洗礼的意义", "commentary": "奉三一名施水，印证归入基督、洁净与圣约归属。外在施洗与内在重生并非机械同一时刻；受洗后仍需相信并持续受教。", "section": "施恩途径"}, {"n": 166, "title": "应给谁施洗", "commentary": "未入教会者在认信后受洗，认信者的儿女也在圣约施行中领受洗礼。婴孩洗礼并不声称每个受洗儿童必已重生，也不取消日后的信心责任。", "section": "施恩途径"}, {"n": 167, "title": "怎样终身善用洗礼", "commentary": "记念神的应许、为不相称的生活悔改，并在试探中倚靠与基督同死同活的恩典。洗礼不是过去一次的纪念品，而是呼召持续活出归属。", "section": "施恩途径"}, {"n": 168, "title": "圣餐的意义", "commentary": "借饼杯记念并宣告基督的死，使信徒因信受属灵滋养。一次完成的献祭无需重演；重复领餐表达持续倚靠，而非救赎不够。", "section": "施恩途径"}, {"n": 169, "title": "饼酒如何施行", "commentary": "按基督设立，以圣道、感谢、分发与领受施行饼杯。施行方式服务福音意义，不应任意改为个人展示或脱离教会的魔法仪式。", "section": "施恩途径"}, {"n": 170, "title": "怎样领受基督身体与血", "commentary": "借信心、凭圣灵与天上的基督相交，是真实属灵领受，而非口吃基督的肉。元素不变质，属灵却不等于不真实。", "section": "施恩途径"}, {"n": 171, "title": "领餐前怎样预备", "commentary": "省察对基督的认识、信心、悔改、爱心与新顺服，并寻求和好。省察是走向救主，不是要求先达到毫无疑惑与瑕疵的资格。", "section": "施恩途径"}, {"n": 172, "title": "疑惑者可否领餐", "commentary": "为缺乏信心忧伤、诚心愿属基督的人，应受安慰并得帮助来领受。大要理没有把软弱等同顽梗；圣餐正是为滋养真实却软弱的信心。", "section": "施恩途径"}, {"n": 173, "title": "何种认信者应暂被拦阻", "commentary": "公开无知或顽梗、不适当领受者须受教会牧养与纪律。领餐既不是领袖的私人奖赏，也不是任何人不受教会监督的个人权利。", "section": "施恩途径"}, {"n": 174, "title": "领餐时应作什么", "commentary": "专注基督、凭信领受、感恩并以爱与身体相交。不要只观察自己的感觉强弱；应许的可信出于救主，而非这一刻的情绪。", "section": "施恩途径"}, {"n": 175, "title": "领餐后应作什么", "commentary": "省察所得益处，感恩并活出新的顺服；若缺少感觉，要谦卑查验并继续仰望。领餐的回应延伸到与弟兄姊妹和好及日常生活。", "section": "施恩途径"}, {"n": 176, "title": "洗礼与圣餐的共同点", "commentary": "同出于基督设立，同以外在记号表明和印证恩典，并须凭信领受。它们相互配合，不能与圣道或圣灵工作割裂。", "section": "施恩途径"}, {"n": 177, "title": "洗礼与圣餐的不同", "commentary": "洗礼为归入教会的起始记号，一次施行并包括圣约儿女；圣餐反复领受，要求有分辨与认信能力。共同恩典不取消不同用途与领受资格。", "section": "施恩途径"}, {"n": 178, "title": "什么是祷告", "commentary": "借基督、靠圣灵，将合神旨意的心愿献上，同时认罪与感谢。祷告是受恩者向神回应，不是使神服从人的话语技巧。", "section": "祷告与主祷文"}, {"n": 179, "title": "是否只可向神祷告", "commentary": "只有神知心、掌权并配受这种敬拜；圣徒与天使不是另设的祷告对象。可请活着的信徒代祷，与向受造者献上宗教祈求有本质分别。", "section": "祷告与主祷文"}, {"n": 180, "title": "奉基督之名祷告是什么意思", "commentary": "依靠他的中保权柄、功劳与代求亲近父，并按他的旨意求。末尾加一句名字本身并非保证任何愿望实现的公式。", "section": "祷告与主祷文"}, {"n": 181, "title": "为什么必须奉基督之名", "commentary": "罪阻隔人亲近神，只有中保开辟道路。基督不是让父变慈爱的工具，而是父主动之爱所赐的救主；因此信徒得以坦然。", "section": "祷告与主祷文"}, {"n": 182, "title": "圣灵怎样帮助祷告", "commentary": "他光照、激发合宜心愿并扶助软弱，不只提供雄辩辞藻。不会表达时仍可仰望神；圣灵的帮助不等于取消理解与责任。", "section": "祷告与主祷文"}, {"n": 183, "title": "应为谁祷告", "commentary": "为教会、掌权者、他人、自己乃至仇敌代求；祷告范围超过私人圈子。本问不支持为死者改变最终结局的祈求，也不授权凭猜测将人排除于代祷之外。", "section": "祷告与主祷文"}, {"n": 184, "title": "应为什么事祷告", "commentary": "求神荣耀、教会与人的益处，以及合宜需要；不求犯罪或与已启示旨意相反之事。欲望需要在祷告中被塑造，而非一概获得神圣背书。", "section": "祷告与主祷文"}, {"n": 185, "title": "应怎样祷告", "commentary": "存敬畏、谦卑、信靠、热切、忍耐并顺服神旨意。诚实哀叹与敬畏并不冲突；圣经诗篇允许受苦者把真实痛楚带到神面前。", "section": "祷告与主祷文"}, {"n": 186, "title": "祷告的准则", "commentary": "整本圣经引导祷告，主祷文是特别模式。以经文塑造所求，有助走出只围绕成功与顺利的狭窄祷告。", "section": "祷告与主祷文"}, {"n": 187, "title": "怎样使用主祷文", "commentary": "它既是祷告范式，也可照原话向神祈求。使用固定祷文与发自内心并不矛盾；真正问题在于心是否明白并倚靠神。", "section": "祷告与主祷文"}, {"n": 188, "title": "主祷文的结构", "commentary": "称呼、六项祈求与结语构成从归向父到归荣耀于父的秩序。前三求以神的名、国、旨意为中心，后三求带入人的需要。", "section": "祷告与主祷文"}, {"n": 189, "title": "在天上的父教导什么", "commentary": "父的慈爱与天上的威严同时给人坦然和敬畏；“我们”把祷告者置于圣徒共同体中。私人需要不应使人忘记邻舍与普世教会。", "section": "祷告与主祷文"}, {"n": 190, "title": "愿人尊神名为圣", "commentary": "求神使自己和万人认识、尊荣他，并除去亵渎与错误认识。不是神缺乏圣洁，而是我们需要被改变，世界需要显明他的荣美。", "section": "祷告与主祷文"}, {"n": 191, "title": "愿神的国降临", "commentary": "求罪与撒但势力被制伏，福音传扬，教会得建立，并盼荣耀国度来临。不要将神国完全认同某国家、政党或个人权力计划。", "section": "祷告与主祷文"}, {"n": 192, "title": "愿神旨意行在地上", "commentary": "求认识并甘心遵行神启示的旨意，且在护理中学会信靠。天使的顺服成为图画；祷告不只要求外在环境改变，也求心被更新。", "section": "祷告与主祷文"}, {"n": 193, "title": "求日用饮食", "commentary": "承认受造生命与物质需要都依赖父，求合宜供应并蒙福使用。“我们”也催促分享与照顾饥饿者；本问不保证财富无尽增长。", "section": "祷告与主祷文"}, {"n": 194, "title": "求赦免罪债", "commentary": "因基督求神赦免，并求恩典使自己愿意饶恕。饶恕他人不是购买赦罪的功德，却显明蒙赦免的生命；它也不自动取消公义程序与必要界限。", "section": "祷告与主祷文"}, {"n": 195, "title": "求脱离试探与凶恶", "commentary": "求神保守、限制试探、扶助争战并使人回转。祷告者也须逃避已知诱因、寻求帮助；信靠不等于故意置身危险再要求神保护。", "section": "祷告与主祷文"}, {"n": 196, "title": "主祷文的结语", "commentary": "国度、权柄、荣耀属于神，因此我们能带着信靠求他成全；阿们表示真实愿望与信赖。结语在马太福音抄本传统中有差异，威敏依其使用的经文传统解释，不应隐去文本历史。", "section": "祷告与主祷文"}]};
window.READING_DATA=[{"title": "使徒信经", "url": "https://ccifellowship.org/books/book-of-praise/creeds/apostles-creed", "text": "我信神，全能的父，创造天地的主。\n\n我信我主耶稣基督，神的独生子；因圣灵感孕，从童贞女马利亚所生；在本丢·彼拉多手下受难，被钉在十字架上，受死，被埋葬，降在阴间；第三天从死里复活；他升天，坐在全能父神的右边；将来必从那里降临，审判活人死人。\n\n我信圣灵。\n\n我相信圣而公之教会，我相信圣徒相通；\n\n我相信罪得赦免；\n\n我相信身体复活；\n\n我相信永生。阿们！", "status": "CCI 网页可读取正文 · 2026-10-22", "note": "以用户所提供手册为交叉参考，按指定 CCI 网页可读取正文核对。保留该页面的文字、标点与编号，段落按网页文本排列；不是拉丁文或希腊文校勘本。"}, {"title": "尼西亚信经", "url": "https://ccifellowship.org/books/book-of-praise/creeds/nicene-creed", "text": "我们信独一的神，全能的父，创造天地及其中可见不可见之万物的主。\n\n我们信独一主耶稣基督，神的独生子，在万世以前为父所生；出于神且是神，出于光且是光，出于真神且是真神；受生却非被造，与父同质；万物都是藉着他造的。\n为了拯救我们，他从天上降世为人，即藉着从圣灵感孕的童女马利亚道成肉身。 他为了我们，在本丢·彼拉多手下被钉十字架；受难、被埋葬；照着圣经所说，他在第三天复活，并升天、坐在父的右边；将来必在荣耀中再来，审判活人死人；他的国没有穷尽。\n\n我们信圣灵，赐生命的主，他从父和子而出，与父和子同受敬拜和尊崇；他曾藉众先知说话。\n\n我们相信世上只有一个圣而公之使徒性教会；\n\n我们承认印证了罪得赦免的独一洗礼；\n\n我们盼望从死里复活，以及完全被更新的世界的到来。阿们！", "status": "CCI 网页可读取正文 · 2026-10-22", "note": "以用户所提供手册为交叉参考，按指定 CCI 网页可读取正文核对。保留该页面的文字、标点与编号，段落按网页文本排列；不是拉丁文或希腊文校勘本。"}, {"title": "亚他那修信经", "url": "https://ccifellowship.org/books/book-of-praise/creeds/athanasian-creed", "text": "1) 所有渴慕得救的人都必须持守大公信仰胜过其他一切。2) 人若不信此信仰中的任何一条，都必永远沉沦。\n\n3) 大公信仰是，我们敬拜一体三位又三位一体的神，4) 其位格不紊，其本质不分，5) 因为父是一位，子是一位，圣灵又是一位；6) 但父、子、圣灵同是一位神，三个位格同荣耀，其威严也同永恒。\n7) 父如何，子就如何，圣灵也如何。8) 父非受造，子非受造，圣灵也非受造。9) 父无限，子无限，圣灵也无限。10) 父永恒，子永恒，圣灵也永恒。11) 父、子、圣灵非三位永恒者，乃一位永恒者；12) 非三位非受造者，乃一位非受造者；非三位无限者，乃一位无限者。13) 同样，父全能，子全能，圣灵也全能；14) 父、子、圣灵非三位全能者，乃一位全能者。\n\n15) 因此，父是神，子是神，圣灵也是神；16) 但父、子、圣灵非三位神，乃一位神。17) 因此，父是主，子是主，圣灵也是主；18) 但父、子、圣灵非三位主，乃一位主。19) 正如按照基督教真理我们必须承认每一位都既是神又是主一样，20) 按照大公信仰，我们不可说他们是三位神、三位主。\n21) 父是自有的，既非受造，也非受生。22) 子独出于父，非受造，乃是受生。23) 圣灵从父和子而出，非受造，也非受生。24) 因此，只有一位父，非三位父；只有一位子，非三位子；只有一位圣灵，非三位圣灵。25) 父、子、圣灵无先后、无尊卑，26) 同永恒，是平等的三个位格。27) 因此如前所述，在凡事上，一体三位又三位一体的神须同受敬拜。28) 渴慕得救的人必须如此思想三位一体的神。\n\n29) 同时，要得永远的救赎，就须信道成肉身的主耶稣基督。30) 纯正的信仰就是我们相信并宣告我们的主耶稣基督，神的独生子，既是神又是人。\n\n31) 他是神，与父同质，受生于未有世界以先；他又是人，与其母同质，生于这世界。32) 他既是完全的神，又是具有人的灵魂和肉体的完全的人；33) 以其神性，他与父同等，以其人性，他低于父。\n\n34) 尽管既是神又是人，基督仍是一位，而非两位。35) 他是一位，并非因他的神性变为人性，乃是在神性中取了人性；36) 他是一位，并非因两质相混，乃是因神人二性合于一个位格。\n\n37) 正如人是灵与肉的合一体一样，基督是神与人的合一体。\n38) 基督为救我们而受难，降在阴间，又从死里复活，39) 升天，坐在父的右边，将来必从那里降临，审判活人死人；40) 他降临时，所有死人都必身体复活，供认所行的一切事；41) 行善者必得永生，作恶者必入永火。\n\n42) 这是大公信仰。人若非坚定不移地相信，就不能得救。阿们!", "status": "CCI 网页可读取正文 · 2026-10-22", "note": "以用户所提供手册为交叉参考，按指定 CCI 网页可读取正文核对。保留该页面的文字、标点与编号，段落按网页文本排列；不是拉丁文或希腊文校勘本。"}, {"title": "比利时信条", "url": "https://ccifellowship.org/books/book-of-praise/confessions/the-belgic-confession", "text": "三项联合信条\n\n比利时信条\n\n中国改革宗教会三项联合信条中的第一个是《比利时信条》（ 又名《真基督教信条》）。它得此名是因为它源于当时的荷兰南部，即现在的比利时。它的主要作者是德布利（Guido de Brès ），他是荷兰改革宗教会的牧师，于1567年为主殉道。十六世纪，荷兰的教会受到罗马天主教政府极为残酷的逼迫。为了抗议这种残酷的逼迫，也为了向逼迫者表明改革宗信徒不是人们所指控的“叛乱者”，而是照着圣经宣告真基督教信仰的守法公民 ，德布利于1561年写下了这一信条。第二年，《比利时信条》的一份抄本被送到了腓利二世的手中，同时还附上了一份信徒的请愿书，声明他们愿意在一切合法的事上顺服政府；但是，如果要他们否认此信条中所宣告的真理，他们宁愿“背受鞭笞，舌被刀割，身受火刑”。\n\n尽管德布利“使信徒免受逼迫”的初衷没有实现，他本人也成了成千上万名殉道者之一，但他写下的信条却保存了下来，并继续流传于世。德布利写此信条在一定程度上得益于由约翰•加尔文主笔、比《比利时信条》早两年发表的法国改革宗教会的一个信条。尽管如此，《比利时信条》并不是加尔文所写信条的修正版，而是有其自身特点的独立信条。此信条一经发表，就立刻得到荷兰许多教会的欢迎。十六世纪最后三十年间所召开的几次总会大会对该信条进行了审议，最终，它被总会正式采纳。经过仔细修订（主要在文字方面而不是内容方面）， 1618-1619举行的多特大会正式将这一信条纳为改革宗教会三大联合信条之一，改革宗教会的所有圣职人员在就职前都要签署文书表示认同这一信条。此后，改革宗教会一致认定，《比利时信条》是改革宗教会最好的信仰告白之一。\n\n真基督教信条对有关神的教义和有关人得永恒救赎的教义的概述\n\n第一条只有一位神\n\n我们都心里相信、口里承认（ 1）只有一位神。他是纯粹（2）的灵（ 3）；他是永恒（4）的，是不可测（ 5）、不可见（ 6）、不改变（ 7）、无限（ 8）的，是全能（9）、全智（10）、公义（ 11）、良善（ 12）的，是盈溢一切美善的泉源（ 13）。\n\n（1）罗10:10 （2）申6:4;林前8:4,6;提前2:5 （3）约4:24 （4）诗90:2 （5）罗11:33 （6）西1:15;提前6:16 （7）雅1:17 （8）王上8:27;耶23:24 （9）创17:1;太19:26;启1:8 （10）罗16:27 （11）罗3:25,26; 罗9:14;启16:5,7 （12）太19:17 （13）雅1:17\n\n第二条神启示自己的方法\n\n我们通过两种途径认识神：第一，藉着神对宇宙的创造、维护和管理。宇宙是呈现在我们眼前的一部绝佳之作 (1)，其间的一切受造物，无论大小，都如书中的字句，引导我们察觉神不可见的特性，就是使徒保罗在罗马书第1章第20节所说的“神的永能和神性”。这一切足以使人知罪，且无可推诿。第二，藉着他的圣言，神将他自己更清楚、更完全地启示给我们 (2)，只要那是我们今生所需要知道的，是他得荣耀、 我们得救所必不可少的。\n\n（1）诗19:1-4 （2）诗19:7,8;林前1:18-21\n\n第三条论圣经\n\n我们承认神的话语不是出于人意， 而是如使徒彼得所说的，人被圣灵感动说出神的话来（彼后 1:21）。此后，出于对我们特别的眷顾和对我们的救赎 ,神吩咐他的仆人、先知与使徒将他所启示的道记录成文 (1)，又亲自写下两块法版(2)。因此，我们称这些书卷为圣经 (3)。\n\n（1）出34:27;诗102:18;启1:11,19 （2）出31:18 （3）提后3:16\n\n第四条圣经正典\n\n我们相信圣经包括旧约与新约两部分，它们同是正典，这是绝对不可否认的。这些书卷在神的教会中被编列为：\n\n旧约圣经包括：摩西五经，即创世记、出埃及记、利未记、民数记和申命记；约书亚记、士师记、路得记、撒母耳记上下、列王纪上下、历代志上下、以斯拉记、尼希米记、以斯帖记 ；约伯记、诗篇、箴言、传道书、雅歌 ； 以赛亚书、耶利米书、耶利米哀歌、以西结书、但以理书、何西阿书、约珥书、阿摩司书、俄巴底亚书、约拿书、弥迦书、那鸿书、哈巴谷书、西番雅书、哈该书、撒迦利亚书和玛拉基书。\n\n新约圣经包括：四福音书，即马太福音、马可福音、路加福音及约翰福音；使徒行传；使徒保罗的十三卷书信，即罗马书、哥林多前后书、加拉太书、以弗所书、腓立比书、歌罗西书、帖撒罗尼迦前后书、提摩太前后书、提多书、腓利门书；希伯来书；另外还有七卷书信，即雅各书、彼得前后书、约翰一书、约翰二书、约翰三书、犹大书；还有使徒约翰的启示录。\n\n第五条圣经的权威性\n\n我们接受（ 1）这些书卷，且只接受它们为圣经正典，用以规范、证实我们的信仰，作我们信仰的根基（ 2）。我们完全相信且毫不怀疑其中所写的一切。与其说这是因为教会接受并赞同它们，倒不如说这更是因为圣灵在我们心中作见证，证明它们都来自神（ 3）；这些经卷本身也证明它们是从神而来的，因为即使是瞎眼的人也能察觉，其中所预言的事正在应验（ 4）。\n\n（1）帖前2:13 （2）提后3:16,17 （3）林前12:3;约壹 4:6;约壹 5:7 （4）申18:21,22;王上22:28;耶28:9;结33:33\n\n第六条论圣经正典与次经之间的区别\n\n我们要将圣经正典与次经加以区分。次经包括：爱斯德拉斯第三书和第四书、特比特书、犹特书、所罗门智慧书、便西拉智训、巴录书、以斯帖书余卷、三圣子之歌、苏撒那的历史、比勒与大龙、玛拿西祈祷书与马加比前后书。教会可以读次经，若次经书卷与圣经正典相符，教会可以从中听取教训；但是，次经远没有正典书卷那种见证和坚固我们基督教信仰的大能和权威，更不可被用来贬低圣经正典的权威。\n\n第七条论圣经的充分性\n\n我们相信， 圣经中包含了神全部的旨意 ；我们也相信它对人得救所必须信的一切真理作了充分的教导 （1）。圣经详细记述了神要我们以怎样的方式敬拜他。因此，任何人教导有悖于圣经的道理都是不合法的 （2），即便是使徒，或 （如使徒保罗所说） 天上来的使者也不例外 （参见加1:8）。因为神所吩咐的 ，不可加添，也不可删减（3）（申12:32）。很明显，圣经中的道理在各方面都是最完全的 （4）。\n\n我们不可认为出自人手的任何著作与圣经具有同等价值，无论其作者有多么圣洁；也不可认为人的风俗、民意、古迹、时代和人的传承、教会会议所作的决议或法令法规等效于神的真理，因为神的真理高于一切 （5），而人都是虚假的，比虚空还要虚空（参见诗 62:9）。因此，我们要完全拒绝与圣经的无谬真理不相符的事物 （6），正如使徒们教导我们的那样： “总要试验那些灵是出于神的不是。”（约壹 4:1）同时，“若有人到你们那里，不是传这教训，不要接他到家里，也不要问他的安。”（约贰1:10） （1）提后 3:16,17;彼前 1:10-12 （2）林前15:2;提前1:3 （3）申4:2;箴30:6;徒26:22;林前4:6;启22:18,19 （4）诗19:7;约15:15;徒18:28;徒20:27;罗15:4 （5）可7:7-9;徒4:19;西2:8;约壹2:19 （6）申4:5,6;赛8:20;林前3:11;弗4:4-6;帖后2:2;提后3:14,15\n\n第八条论神的“三位”和“一体”\n\n根据此真理并神的道 ，我们信独一的神，他只有一个本质（1），而有三个位格 ，即圣父、圣子和圣灵（ 2）；根据各个位格难以言传的属性，他们的确是永远截然不同的。圣父是可见不可见之万物的根源与起始 （3）；圣子是圣父的道、智慧与神本体的真像 （4）；圣灵是从父与子而出的永恒的大能大力 （5）。虽然如此，神并不因位格的不同而分为三位，因为圣经教导我们，圣父、圣子、圣灵虽属性各异，各有不同的位格，但却是同一位神。\n\n因此，很显然，圣父非圣子，圣子亦非圣父；同样，圣灵既非圣父，亦非圣子。然而，如此不同的三个位格既不分开，也不相混 ：三个位格中只有圣子取了我们的血肉之躯；圣父从未离开过圣子 （6）或圣灵。具有同一本质的这三个位格都是永恒的，他们没有先后之分，在真理、能力、良善与恩慈上是三而一的。\n\n（1）林前8:4-6 （2）太3:16,17;太28:19 （3）弗3:14,15 （4）箴8:22-31;约1:14;约5:17-26;林前1:24;西1:15-20;来1:3; 启19:13 （5）约15:26 （6）弥5:2;约1:1,2\n\n第九条三位一体论的圣经依据\n\n我们对三位一体的一切认识都源于圣经的诸多见证（1），也源于三个位格各自所做的工作，尤其是他们在我们身上所做成的工作。圣经旧约多处记载了引导我们相信神三位一体的见证。我们毋需列出所有经文，只要精选一些就足以说明问题。\n\n在创世记中，神说：“我们要照着我们的形像，按着我们的样式造人……神照着自己的形象造人，乃是照着他的形像造男造女。”（创 1:26,27）还有，“那人已经与我们相似”（创 3:22）。从神说的“我们要照着我们的形像造人”这句话看，神不止一个位格；当他说“神……造人”时，他表明只有一位神。的确，他没有说明有几个位格，但在旧约中还有些模糊的这个问题，在新约中就非常清晰了。因为主在约但河受洗时，圣父的声音传来，说：“这是我的爱子” （太3:17）；同时，圣子在水中时，圣灵仿佛鸽子降下，落在他身上 （2）。另外，基督吩咐使徒要给所有信徒施洗时说：你们要奉父、子、圣灵的名，为万人施洗，使他们作我的门徒（参太 28:19）。在路加福音中，天使加百列对主的母亲马利亚说：“圣灵要临到你身上，至高者的能力要荫庇你，因此所要生的圣者必称为神的儿子”（路 1:35）；同样，保罗问安时也说：“愿主耶稣的恩惠、神的慈爱、圣灵的感动，常与你们众人同在。”（林后 13:14）这几处经文都充分教导我们，在神的独一本质中有三个不同的位格。\n\n虽然此教义远远超出人能理解的范畴，但是在今生，我们基于神的话而相信它，盼望将来在天上能完全理解此教义，并享受其福益。 此外，我们必须清楚地看到三个位格对我们的不同职分和工作。圣父藉其大能，被称为我们的创造主；圣子藉其宝血，被称为我们的救赎主；圣灵住在我们心中，帮助我们成圣。从使徒时代直到今天，三位一体的教义一直为真教会所持守， 它有效地抵制了犹太教、伊斯兰教对教会的影响，以及被早期教会的教父们定为异端的假基督徒与异端份子，如马吉安、摩尼、帕克西亚、撒伯流、萨摩斯岛的保罗及亚流等人对教会的侵蚀。 因此，在这一教义上，我们甘愿接受《使徒信经》、《尼西亚信经》和《亚他拿修信经》，以及其他与它们不相悖，且受到教父们一致认可的信经。\n\n（1）约14:16;约15:26;徒2:32,33; 罗8:9;加4:6;多3:4-6;彼前 1:2; 约壹4:13,14; 约壹5:1-12;犹20,21;启1:4,5 （2）太 3:16\n\n第十条论耶稣基督是永活真神\n\n我们相信，根据基督的神性，耶稣基督乃是神的独生子（1），从永恒而生，非受造亦非被造 ——否则他即为受造者——乃与圣父同本质、同永恒，他是神荣耀所发的光辉，是神本体的真像（来 1:3），在凡事上都与圣父同等（2）。他不是从取了我们人性那一刻起才成为神的儿子，而是在永恒中就是神的儿子 （3），正如以下经文相互参照时所教导的：摩西说，神创造天地 （4）；使徒约翰说，万物都是藉着道造的，约翰称这道为神 （5）；希伯来书说，神藉着他儿子创造诸世界 （6）；同样，使徒保罗说万物都是神藉着基督造的 （7）。由此，我们必然得出这样的结论：那被称为神、道、神的儿子和耶稣基督的，在万物藉着他被造时的确已经存在；因此耶稣可以说：我实实在在地告诉你们，还没有亚伯拉罕，就有了我（约 8:58）；他祷告说，父啊，现在求你使我同你享荣耀，就是未有世界以先，我同你所有的荣耀（约 17:5）。可见，他是真实的、永恒的、全能的神，是我们所呼求的中保、代祷者和辩护者，是我们所敬拜、所事奉的神。\n\n（1）太17:5;约1:14,18; 约3:16;约14:1-14;约20:17,31; 罗1:4;加4:4; 来1:2;约壹5:5,9-12 （2）约5:18,23; 约10:30;约14:9;约20:28;罗9:5;腓2:6;西1:15; 多2:13;来1:3;启5:13 （3）约8:58;约17:5;来13:8 （4）创1:1 （5）约1:1-3 （6）来1:2 （7）林前8:6;西1:16\n\n第十一条论圣灵是永活真神\n\n我们相信并宣告圣灵从永恒中由父与子而出。他既非受造、被造，亦非受生，乃是只从父与子而出 （1）。在次序上，圣灵是三位一体的第三位；他与圣父、圣子有同一本质， 有同样的威严和荣耀。正如圣经所教导的那样（2），他是永活的真神。\n\n（1）约14:15-26;约15:26;罗8:9 （2）创1:2;太28:19;徒5:3,4;林前2:10;林前3:16;林前6:11; 约壹 5:7\n\n第十二条论创造\n\n我们相信，圣父在合宜的时间，藉着道，即他的独生子，从无有中创造了天地万物 (1)；我们相信他给了每一个受造物本质、外形和结构，也给了他们具体的任务和职能，以服侍创造主。我们相信，他还继续以他永恒的护理与无限的能力支持并管理着万物，为要让人得益处，以使人能服侍神。\n\n他也将天使造得甚好，可作他的使者，也可为他的选民效力(2)。有些天使从被造时所置的高位上堕落到了永远的灭亡中 (3)；其余的天使则因神的恩典而坚定不变 , 继续居于本位。魔鬼及邪灵极度败坏，成为神与众善的仇敌(4)。他们竭尽全力，像杀人犯一样伺机而动，企图败坏教会和其中的信徒，并用各种诡计毁坏一切 (5)。因其自身的邪恶，他们被定了罪，当受永远的刑罚，天天等候那可怕的苦刑 (6)。\n\n所以, 我们恨恶并弃绝撒督该人的错谬 ——他们否认诸灵与天使的存在 (7)；我们也弃绝摩尼教派的错谬 ——他们说魔鬼不是被造的 , 而是自有的，并认为邪恶是魔鬼的本性，而非出于败坏。\n\n（1）创1:1;创2:3;赛40:26;耶 32:17;西1:15,16; 提前4:3;来11:3; 启4:11 （2）诗103:20,21; 太4:11;来1:14 （3）约 8:44;彼后2:4;犹6 （4）创3:1-5;彼前5:8 （5）弗6:12;启12:4,13-17;启20:7-9 （6）太8:29;太25:41;启20:10 （7）徒23:8\n\n第十三条论神的眷顾\n\n我们相信，这位良善的神，在完成创造之工后，没有放任受造物，也没有让他们自己碰运气（ 1），而是按照他神圣的旨意管理着他们，以至于这世上没有什么事不是在他的旨意下发生的（ 2）。虽然如此，神并不是罪恶的创造者，也不该因世上的罪而受到控告（ 3）。因为他的全能和善良极其伟大，且不可测度，所以魔鬼与恶人虽行不义，神仍以最完美、最恰当的方式命定、施行他的大工（4）。由于他的作为超乎人能理解的范畴，我们不出于好奇去追问我们所不能理解的事，而用最谦卑和敬畏的心仰慕神公义的判断，因那是向我们隐藏的（ 5）；我们以作基督的门徒为满足，只学习神在圣经中教导我们的事，不越过这个界限 (6）。\n\n神的眷顾这一教义给了我们不可言喻的安慰，因为我们从此教义中得知，任何事临到我们皆非出于偶然，都有我们仁慈天父的管理在其中 。他以慈父的爱关怀、看顾我们，以他的权能保守一切受造之物。若不是天父的旨意，没有一根头发会掉下来 ——因我们的头发都被数过 ——也没有一只麻雀会落在地上（太 10:29-30）。我们相信这一切，因为我们知道，他掌管魔鬼和我们一切的仇敌，若没有他的许可，若不是出于他的意愿（ 7），他们就不能够伤到我们。\n\n所以，我们反对伊比鸠鲁派的观点，说神什么都不管，他让万物自己碰运气。这是错谬，是当受咒诅的。\n\n（1）约 5:17;来1:3 （2）诗115:3;箴16:1,9,33;箴21:1;弗1:11,12;雅4:13-15 （3）雅1:13;约壹2:16 （4）伯1:21;赛10:5;赛45:7;摩3:6;徒2:23;徒4:27,28 （5）王上22:19-23;罗1:28;帖后2:11 （6）申29:29;林前 4:6 （7）创45:8;创50:20;撒下16:10;罗8:28,38,39\n\n第十四条论人的被造与堕落以及人不能行真善事我们相信神用地上的尘土造人（ 1），且是照他自己的形像和样式造的， 使人有良善、公义和圣洁（ 2）。那时，人在凡事上都能合乎神的旨意。 然而，人有了这尊贵的地位却既不看重也不感恩， 反而听从魔鬼的话，甘受罪的辖制，以至于死和受咒诅（ 3）。人干犯了从神领受的生命的律；因着罪，他背离了神，即生命的主，也全面败坏了自己的本性。因着这一切，他的身体和灵魂都当受死（4）。\n\n自从人变得邪恶、乖僻、全然败坏之后，他就失去了所有从神领受的美好恩赐 (5)，所留下的只有些许痕迹，但足以叫人无法推诿神的存在 (6)。我们里面的光已经变为黑暗(7)，正如圣经教导我们说：“光照在黑暗中，黑暗却不接受光” （约1:5）；在这节经文中，使徒约翰称人类为黑暗。\n\n因此，关于人的自由意志，我们弃绝一切与圣经相悖的教导，因为人已经成为“罪的奴仆”（约 8:34），“若不是从天上所赐的，人就不能得什么”（约 3:27）。基督既说：“若不是差我来的父吸引人，就没有能到我这里来的”（约 6:44），谁还能夸口说自己能行善呢？人若明白“体贴肉体的，就是与神为仇”（罗 8:7），谁还能为自己的意志沾沾自喜呢？ “属血气的人不领会神圣灵的事”（林前 2:14），谁的知识还值得一提呢？简言之，当一个人意识到“并不是我们自己能承担什么事，我们所能承担的，乃是出于神”（林后 3:5），谁还敢说这是他自己的作为呢？ 因此，使徒保罗所说的话，“你们立志行事，都是神在你们心里运行，为要成就他的美意”（腓2:13），今天仍然千真万确 ，因为若不是出于基督， 没有人的悟性或意愿能与神的相符 。基督也教导说：“离了我，你们就不能作什么 。”（约15:5）\n\n（1）创2:7;创3:19;传12:7 （2）创1:26,27; 弗4:24;西3:10 （3）创3:16-19;罗5:12 （4）创2:17;弗2:1;弗4:18 （5）诗94:11;罗3:10;罗8:6 （6）罗1:20,21 （7）弗5:8\n\n第十五条论原罪\n\n我们相信由于亚当的悖逆，原罪已传遍全人类（ 1）。它使人性全然败坏（ 2），它还具有遗传性，因而所有人都受其污染，甚至母腹中的婴孩（ 3）也不例外。它是所有罪的根源。因此，在神的眼中，它极为邪恶和可憎，足以使全人类被定罪（ 4）。正如水从源头涌流不绝，从原罪而出的罪也不断产生，即使洗礼也不能将它终止或根除。（5）尽管如此，神没有将原罪归给他的儿女，使他们被定罪，反而以他的恩典和怜悯赦免了他们的罪（ 6）。这不是说信徒可以高枕无忧地活在罪中，而是说对这种败坏的认知会使信徒时常叹息，并急切盼望脱离这取死的身体。\n\n在这一点上，我们弃绝伯拉纠派的错谬，他们认为罪只是从模仿而来的。\n\n（1）罗5:12-14,19 （2）罗3:10 （3）伯14:4;诗51:5;约3:6 （4）弗2:3 （5）罗7:18,19 （6）弗2:4,5 第十六条论神的拣选\n\n我们相信，当始祖亚当的所有后裔都因他犯罪而堕落、灭亡时（ 1），神彰显了他的恩慈与公义。神的恩慈体现在神不看人的行为（ 2），而是以自己纯全的美善，按他永恒不变的旨意（ 3），拯救他在我们的主耶稣基督里（ 4）所拣选（ 5）的人脱离永远的死亡；神的公义体现在他任凭其余的人留在他们自取的堕落和毁灭中（ 6）。\n\n（1）罗3:12 （2）玛1:2,3;罗 9:11-13;提后 1:9;多3:4,5 （3）约6:37,44; 约10:29;约17:2,9,12; 约18:9 （4）约15:16,19; 罗8:29;弗1:4,5 （5）撒上12:22;诗65:4;徒13:48;罗9:16;罗11:5;多1:1 （6）罗9:19-22;彼前2:8\n\n第十七条论对堕落之人的拯救\n\n我们相信，当看到人自取身体和灵性的死亡，使自己深陷完全的愁苦中时，我们仁慈的神以他妙不可言的非凡智慧和良善来寻找战兢地躲避他面的人（ 1）。他以赐下独生子这一应许安慰人， 这独生子 “为女子所生”（加4:4），要伤蛇的头（ 2），使人得福（ 3）。\n\n（1）创3:9 （2）创3:15 （3）创22:18;赛7:14;约1:14;约5:46;约7:42;徒13:32,33; 罗1:2,3; 加3:16;提后2:8;来7:14\n\n第十八条论耶稣基督的道成肉身\n\n因此，我们承认，神成就了借众先知的口赐给列祖的应许（1），即在预定的时间 （2），差他独生的、永恒中的儿子，“取了奴仆的形像，成为人的样式 ”（腓2:7）来到世上。 这位独生子取了真正的人性及其诸般的软弱（3），只是没有罪（4），因为他是藉着圣灵的大能，而不是藉着人的作为 （5），在蒙恩的童女马利亚腹中成孕的。为了成为真正的人，他不仅取了人的身体，还取了人的灵魂。那是因为人的灵魂和身体一同失丧了；为使它们都得救，他就必须二者都取。\n\n异端重洗派否认基督从他母亲那里得了肉身。与之正相反，我们承认基督同有儿女的血肉之体（来 2:14）。他是大卫的后裔（徒 2:30）；按人性说，他是大卫后裔生的（罗 1:3），在童贞女马利亚腹中成孕（路 1:42），为女子所生（加 4:4），是大卫的苗裔（耶 33:15），从耶西发出的一条（赛 11:1），从犹大支派而出（来7:14）；按肉体说，是从犹太人出来的（罗 9:5），是亚伯拉罕的后裔 （6）。既为亚伯拉罕的后裔，他就要在凡事上与他的弟兄相似，只是没有罪（来 2:16，17；来4:15）。\n\n因此，他实在是我们的以马内利，即神与我们同在（太1:23）。\n\n（1）创26:4;撒下7:12-16;诗132:11;路1:55;徒13:23. （2）加4:4 （3）提前2:5;提前3:16;来2:14 （4）林后5:21;来7:26;彼前2:22 （5）太1:18;路1:35 （6）加3:16\n\n第十九条论基督位格中的神人二性我们相信，因其特殊的受孕方式，神子这一位格和他的人性是不可分割的 （1）。因此，天地间不存在两位神子，神子也不具有两个位格，乃是神人二性合于同一个位格中；这二性各有其独特的属性：他的神性非被造，无生之始，无命之终（来 7:3），充满天地 （2）；他的人性并未失去其特性，有生之始，仍属受造，是有限的，具有真肉体的一切属性 （3）。藉着复活，他虽将不朽赋予了他的肉体，但他人性的一切真实性 （4）并未发生改变 ，因为我们的救恩与复活也要靠他肉身的真实性来成全（5）。\n\n但是，他的神人二性在同一位格中联合得如此紧密，以至他的死都未能使之分开。因此，他死时交付到父神手里的，是从他肉身分离出来的真正的人的灵魂 （6）。 与此同时，他的神性始终与他的人性联合在一起，即使他躺在坟墓里时也不例外 （7）。他的神性始终在他里面，正如在孩童时期，他的神性虽暂时没有显明出来，但也一直在他里面一样。\n\n正因如此，我们宣告基督是真神，也是真人。他是真神，为要藉着他的大能胜过死亡；他也是真人，所以才能以他软弱的肉体为我们受死。\n\n（1）约1:14;约10:30;罗9:5;腓2:6, 7 （2）太28:20 （3）提前2:5 （4）太26:11;路24:39;约20:25;徒1:3,11;徒3:21;来2:9 （5）林前 15:21;腓3:21 （6）太27:50 （7）罗1:4\n\n第二十条论神在基督里的公义与怜悯\n\n我们相信，完全慈爱与公义的神差遣他的儿子取了我们在其中行悖逆的人性 （1），为要在人性中成就救赎，并以极端的受苦受死 （2）方式担当罪的刑罚。因此，当神将我们的罪孽加在其爱子身上 （3）时，他就在他儿子身上彰显了公义，同时也将他的良善与怜悯倾倒在我们这些有罪的、当受咒诅的人身上。出于完全的爱，他舍了自己的独生子，让他代替我们死；为使我们得称为义 （4），他又叫他复活，好叫我们藉着他得永生。\n\n（1）罗8:3. （2）来2:14. （3）罗3:25-26;罗8:32. （4）罗4:25.\n\n第二十一条论我们大祭司基督的救赎\n\n我们相信，耶稣基督按耶和华所起的誓，照着麦基洗德的等次被立为永远的大祭司 （1）。正如众先知所预言的那样（2），他代替我们，在父面前献上自己；藉着他的补赎，平息了神的忿怒 （3），他甘愿被挂在木头十架上，流宝血洗去我们的罪 （4）。因为经上说：“他为我们的过犯受害，为我们的罪孽压伤。因他受的刑罚，我们得平安；因他受的鞭伤，我们得医治 （5）……他像羊羔被牵到宰杀之地……被列在罪犯之中。” （赛53:5，7，12）（6）他被本丢彼拉多定为罪人，虽然彼拉多早先声明查不出他有什么罪来 （7）。他没有抢夺，却要去偿还（诗69:4）。他死，是以义的代替不义的 （8）（彼前3:18）；他身体和灵魂受苦 （9），是因我们的罪而受可怕的刑罚。他汗珠如大血点，滴在地上（路 22:44）。最后，他大声喊着说：“我的神，我的神，你为什么离弃我？”(太27:46) 基督忍受这一切，为的是我们罪得赦免。\n\n因此，我们当用保罗的话说 ：“我们不知道别的，只知道耶稣基督并他钉十字架 。”（林前 2:2）我们“也将万事当作有损的，因我以认识我主基督耶稣为至宝”（腓3:8）。因他所受的鞭伤，我们得了安慰，不必谋求或臆造其他途径与神和好。基督一次献己为祭已经让信徒永远得了完全（来 10:14）（10）。这正是神的使者称他为耶稣，即救赎主的原因 ——他要将自己的百姓从罪恶里救出来（太1:21）（11)。\n\n（1）诗110:4;来7:15-17 （2）罗4:25;罗5:8-9;罗8:32;加3:13;西2:14;来2:9,17;来 9:11-15 （3）徒2:23;腓2:8;提前1:15;来9:22;前1:18-19;约壹1:7;启7:14 （4）路24:25-27;罗3:21;林前15:3 （5）彼前2:24 （6）可15:28 （7）约18:38 （8）罗5:6 （9）诗22:15 （10）来7:26-28;来9:24-28 （11）路1:31;徒4:12\n\n第二十二条论因信基督而称义\n\n我们相信，为了让我们得着关乎这伟大奥秘的真知识，圣灵在我们心中生发真信心 （1）。这信心使我们接受耶稣基督并他一切的功德，认他作我们的救主，唯独寻求他的帮助（2）。凡藉着信心得着耶稣基督的，也就在他里面得到了完全的救恩 （3）。因此，所谓基督的救恩不够完全，除他以外还需要别的才能得救的这种断言是严重的亵渎，因为这样的结论等于说基督只是半个救主。\n\n所以，我们当用保罗的话说：“人称义是因着信，不在乎遵行律法。”（罗 3:28）（4）然而，严格地说，这不是指信心本身使我们称义 （5），因为信心只是一个工具，藉着它，我们得以承受基督为我们的义。基督将自己一切的功德，以及他已为我们做的、替我们做成的一切圣工都归给了我们 （6）。这样，耶稣基督成为了我们的义，而信心这一工具将我们与基督连在一起，使我们在与基督的相交中得着他一切的恩惠。当我们得着基督的恩惠时，我们的罪就足以得到赦免了。\n\n（1）约16:14;林前2:12;弗1:17-18 （2）约14:6;徒4:12;加2:21 （3）诗32:1;太1:21;路1:77;徒13:38,39; 罗8:1 （4）罗3:19-4:8;罗10:4-11;加2:16;腓3:9;多3:5 （5）林前4:7 （6）耶23:6;太20:28;罗8:33;林前1:30-31;林后5:21;约壹4:10\n\n第二十三条论我们在神面前得称为义\n\n我们相信，我们蒙福在于，因耶稣基督的缘故我们的罪得了赦免，就在神面前得称为义 （1），正如大卫与保罗所教导我们的：那在行为以外蒙神算为义的人是有福的（罗4:6；诗32:1）。保罗还说我们是“蒙神的恩典，因基督耶稣的救赎，就白白地称义” (罗3:24)（2）。\n\n因此，我们总要坚信自己靠基督称义，以之为信仰根基（3），在他面前谦卑，承认自己确是罪人。我们不以自己或自己的行为夸口 （4），而是完全倚赖 、单单信靠被钉十架的基督所成就的顺服 （5）。当我们信他时，他的顺服就归给了我们 （6）。\n\n这足以遮盖我们的一切罪孽，使我们有信心靠近神，心中不再害怕、恐惧和战兢，也不再像我们的始祖亚当那样战兢躲藏，用无花果树的叶子遮盖身体 （7）。我们若倚靠自己或其他受造物来到神面前，哪怕对其只有微乎其微的倚靠，灾祸都会临到我们，将我们除灭（8）。因此，我们每个人都当像大卫一样祈祷：“求你不要审问仆人，因为在你面前，凡活着的人没有一个是义的 。”（诗143:2）\n\n（1）约壹2:1 （2）林后5:18,19;弗2:8;提前2:6 （3）诗115:1;启7:10-12 （4）林前4:4;雅2:10 （5）徒4:12;来10:20 （6）罗4:23-25 （7）创3:7;番3:11;来 4:16;约壹4:17-19 （8）路16:15; 腓3:4-9\n\n第二十四条论我们的成圣与善行\n\n我们相信，通过听道和圣灵做工 （1）而成就的真信心使我们重生，成为新造的人 （2），过上新生活，又救我们脱离罪的捆绑 （3）。因此，若说使人称义的信心让人不渴慕过良善、圣洁的生活 （4），那是无稽之谈。相反，若没有此信心，人就不可能出于爱神而行善 （5），他所行的不过是出于爱自己，或惧怕刑罚。因此，这圣洁的信心不可能不在人里面殷勤做工，因为我们所说的不是空洞的信心，而是圣经中称为“使人生发仁爱的信心”（加5:6）。这信心促使人按神在圣经中的吩咐去行善。 因为这些善行发自信心之善根，又因神的恩典使之成为圣洁，所以在神眼中是好的，是蒙悦纳的。然而，这些善行并不是我们称义的资本，因为在我们还未行任何善事之前，我们就因信基督而得称为义了 （6）。若不是这样，善事就不能被称为善事，就像只有好树才可能结好果子一样（7）。\n\n因此，我们行善不是为赚取功德以至称义，因我们毫无功德可言 ；我们行善是因我们受了神的恩惠，而非神受了我们的恩惠 （8）。 既然“我们立志行事，都是神在我们心里运行，为要成就他的美意”（腓 2:13），就让我们记住圣经中的话，“这样 ，你们作完了一切所吩咐的，只当说：我们是无用的仆人，所做的本是我们应分做的”（路17:10）。同时，我们不否认神照善行施奖赏 （9），但是他如此行完全是出于他的恩典。\n\n此外，我们虽行善，但不能靠善行得救，因为不被肉体玷污、不当受刑罚的事我们一件也行不出来 （10）。即使我们能行善， 我们也不能靠自己的善行得救，因为我们在一条律法上跌倒，就足以遭神的弃绝 （11）。这样，我们就总会在疑惑中飘忽不定；如果不仰赖我们救主受苦和受死所成就的功德，我们可怜的良心就会不停地受折磨（12） 。\n\n（1）徒16:14;罗10:17;林前12:3 （2）结 36:26,27; 约1:12,13; 约3:5;弗2:4-6;多3:5;彼前1:23 （3）约5:24;约8:36;罗6:4-6;约壹3:9 （4）加5:22;多2:12 （5）约15:5;罗14:23;提前1:5;来11:4,6 （6）罗4:5 （7）太7:17 （8）林前1:30-31;林前4:7;弗2:10 （9）罗2:6,7;林前3:14;约贰8;启2:23 （10）罗7:21 （11）雅2:10 （12）哈 2:4;太11:28;罗10:11\n\n第二十五条论基督成全了律法\n\n我们相信，随着基督的降世，礼仪律及其象征已被停用；我们也相信，所有的预表都已实现 （1）。因此，它们不应继续为基督徒所用。然而，为了我们的益处，其真理与精髓仍留在耶稣基督里，它们所预表的都在他身上得了成全（2）。\n\n同时，我们仍使用律法与先知们的见证 ，其一是为了在福音的真道上坚固自己 ，其二是为了本着一切的诚实，遵照神的旨意安排自己的生活，以此荣耀他的名 （3）。\n\n（1）太27:51;罗10:4;来9:9-10 （2）太5:17;加3:24;西2:17 （3）罗13:8-10;罗15:4;彼后1:19;彼后3:2\n\n第二十六条论基督的代求\n\n我们相信，除了藉着唯一的中保 （1）和代求者，就是公义的耶稣基督 （2）以外，没有其他途径可以让人来到神面前。他为此降世为人，集神人二性于一身， 使我们不致与神隔绝 ，而是藉着他得以亲近威严的神 （3）。同时，父神所命定的神与人之间的这位中保，必不威严得令我们惧怕，以致按我们的想像另寻中保。天上地下，没有像耶稣基督那样爱我们的 （4）。他本有神的样式，反倒虚己，取了奴仆的形像，成为人的样式（腓 2:6-7），凡事与他的弟兄相同（来 2:17）。我们若另寻中保，有谁能比他更爱我们呢？当我们还作他仇敌的时候，他就为我们舍命（罗 5:8,10）；我们若要寻找一位权能者，有谁能胜过他呢？他坐在天父的右边 （5），并有天上地下所有的权柄（太 28:18）；此外，又有谁的代求比神独生爱子的更蒙神垂听呢 （6）？\n\n因此，让使徒作中保，是使他们做自己未曾做过，也不曾被要求做的事，这纯粹是出于不信。这样的习俗不是尊荣圣徒，而是羞辱他们。事实上，从使徒留下的文字材料中可以看出，他们始终按着本份拒绝这样被人尊崇（7）。在这方面，我们不应有自己不配向神祷告的想法，因为我们祷告本不是因自己配这样做，而是单单因耶稣基督的功德 （8），因为藉着信，他的义成了我们的义 （9）。\n\n为了除去我们这种愚拙的惧怕，更确切地说是不信，希伯来书作者有理有据地告诉我们，耶稣基督“凡事与他的弟兄相同，为要在神的事上成为慈悲忠信的大祭司，为百姓的罪献上挽回祭。他自己既然被试探而受苦，就能搭救被试探的人”（来 2:17-18）。为了鼓励我们亲近耶稣基督，他又说：“我们既有一位已经升入高天尊荣的大祭司，就是神的儿子耶稣，便当持定所承认的道。因我们的大祭司并非不能体恤我们的软弱，他也曾凡事受过试探，与我们一样；只是他没有犯罪。所以我们只管坦然无惧地来到施恩的宝座前，为要得怜恤，蒙恩惠，作随时的帮助。”（来4:14-16）（10）信中还说：“弟兄们，我们既因耶稣的血得以坦然进入至圣所……就当存着诚心和充足的信心来到神面前 。”（来10:19,22 ）同样，“既是永远长存的，他祭司的职任就长久不更换。凡靠着他进到神面前的人，他都能拯救到底，因为他是长远活着，替他们祈求”（来 7:24-25）（11）。我们还需要什么呢？基督自己说：“我就是道路、真理、生命，若不藉着我，没有人能到父那里去 。”（约14:6）神既喜悦赐他的儿子作我们的中保，我们为何还要寻找另一位呢？让我们不要离弃他而另寻中保，更何况我们不可能找到，因为当神赐下中保时，他清楚地知道我们都是罪人。\n\n总之，按着基督在主祷文里的吩咐和其他经文的教导，我们要奉基督我们唯一中保的名 （12），呼求天上的父（13）。我们应该确信，若奉基督的名向父求什么，就必能得着（约 16:23）（14）。\n\n（1）提前2:5 （2）约壹2:1 （3）弗3:12 （4）太11:28;约15:13;弗3:19;约壹4:10 （5）来1:3;来8:1 （6）太3:17;约11:42;弗1:6 （7）徒10:26;徒14:15 （8）耶17:5,7;徒4:12 （9）林前1:30 （10）约10:9;弗2:18;来9:24 （11）罗8:34 （12）来13:15 （13）太6:9-13;路11:2-4 （14）约14:13\n\n第二十七条论圣而公之基督教会\n\n我们相信圣而公之基督教会，或称普世教会或大公教会（1）。她是圣洁的会众、真信徒的聚集 （2）。这些信徒都因基督的宝血得了洁净，又藉着圣灵成为圣洁，并从圣灵受了印记 （3）；都指望在耶稣基督里得着完全的救恩（4）。\n\n圣而公之教会从世界的起初就存在，今天仍然存在，并将一直存到世界的末了，因为基督这位永远的王不可能没有臣民 （5）。虽然在某段时间大公教会可能人数稀少，在人看来似乎濒临灭绝 （6），但神一直保守她免受世界怒潮的吞噬 （7）。在亚哈王统治时期，耶和华正是在这样的情况下为自己存留了不曾向巴力屈膝的七千余民（8）。\n\n此外，大公教会并不局限于特定的地区，或特定的群体，而是遍布于全世界 （9）。虽然如此 ，但靠着信心的大能，众信徒在心灵和意志上，在同一位圣灵里合而为一（10）。\n\n（1）创22:18;赛49:6;弗2:17-19 （2）诗111:1;约10:14,16;弗4:3-6;来12:22,23 （3）弗1:13;弗4:30 （4）珥2:32;徒2:21 （5）撒下7:16;诗89:36;诗110:4;太28:18,20; 路1:32 （6）赛1:9;彼前3:20;启11:7 （7）诗46:5;太16:18 （8）王上19:18;罗11:4 （9）太23:8;约4:21-23;罗10:12-13 （10）诗119:63;徒4:32;弗4:4\n\n第二十八条论加入教会的责任\n\n我们相信，既然此圣教会是得救之人的聚集，在她之外没有救恩 （1），那么所有人，无论他是何种身份 ，处于什么地位，都不应将自己排除于教会之外而孤立地生活。 相反，所有的信徒都有责任加入教会，与之联合 （2），维护教会的合一。他们应当顺服教会的教导与管教 （3），背负基督的轭 （4）；教会众肢体 （5）应当按着神给各人的恩赐彼此服侍，互相造就 （6）。\n\n为了更有效地遵守这一点，所有信徒都有责任按着神的话语，从那些不属于教会的人中间分别出来 （7），并加入神所设立的教会 （8），即使统治者的政令反对，甚至面临身体受罚或死亡时也当如此（9）。\n\n因此，凡离开基督教会，或不加入教会的，就是在违反神的典章。\n\n（1）太16:18,19;徒2:47;加4:26;弗5:25-27;来2:11-12;来12:23 （2）代下30:8;约17:21;西3:15 （3）来13:17 （4）太11:28-30 （5）林前12:7,27; 弗4:16 （6）弗4:12 （7）民16:23-26;赛52:11-12;徒2:40;罗16:17;启18:4 （8）诗122:1;赛2:3;来10:25 （9）徒4:19-20\n\n第二十九条论真假教会的标志\n\n我们相信，我们应当根据神的话语，认真、仔细地分辨什么是真教会，因为当今世界，所有教派都称自己为真教会（1）。我们这里所说的不是那些假冒为善之人，他们虽身在教会，与信徒掺杂在一起，但其实不属于教会（2)；我们所说的是真信徒的聚集和相交，他们一定与一切自称为教会却不属于真教会的各宗派有区别。\n\n真教会的标志如下：她宣讲纯正的福音 （3）；她按照基督当初设立圣礼的样式施行圣礼 （4）；她为纠正错误、刑罚罪恶而执行教会纪律 （5）。简言之，她按照神纯全的话语管理教会 （6），弃绝一切与之相违背的错谬（7），并且承认耶稣基督为教会唯一的头 （8）。凭借这些标志，真教会一定能被人认出来 ；任何人都没有权利离开真教会。\n\n真信徒可以被辨认出来，因为他们带有真信徒的标志：信唯一的救主耶稣基督 （9）；逃离罪恶，饥渴慕义（10），不偏左右地爱真神、爱自己的邻舍 （11）；把肉体和邪情私欲同钉十字架 （12）。虽然里面仍有极大的软弱，但是，靠着圣灵的大能，他们一生的年日都在与自己的软弱争战 （13），他们常常仰仗主耶稣基督的宝血、受苦、受死与顺服，因为藉着信基督，他们的诸罪都得了赦免（14）。\n\n假教会将自己及自定的规章凌驾于神有权柄的话语之上，不愿服在基督的轭下 （15），也不按基督的吩咐执行圣礼，而是随己意添加和删减神的话。这种教会依靠人过于依靠基督，逼迫按神的话语过圣洁生活的人，也逼迫那些对犯罪、起贪心、拜偶像的教会加以斥责的人（16）。\n\n这两种教会很容易辨认和区分。\n\n（1）启2:9 （2）罗9:6 （3）加1:8;提前3:15 （4）徒19:3-5;林前11:20-29 （5）太18:15-17;林前5:4,5,13;帖后3:6,14;多3:10 （6）约8:47;约17:20;徒17:11;弗2:20;西1:23;提前6:3 （7）帖前5:21;提前6:20;启2:6 （8）约10:14;弗5:23;西1:18 （9）约1:12;约壹4:2 （10）罗6:2;腓3:12 （11）约壹4:19-21 （12）加5:24 （13）罗7:15;加5:17 （14）罗7:24,25; 约壹1:7-9 （15）徒4:17,18; 提后4:3,4;约贰9 （16）约16:2\n\n第三十条论教会的管理\n\n我们相信，此真教会必须按主在圣经中教导我们的属灵原则来管理 （1）：教会须有牧师传讲神的道，并执行圣礼（2）；还须有长老 （3）和执事（4），他们要与牧师一同组成教会议会 （5）。藉此，教会圣职人员努力维护教会信仰的纯正性；确保真教义得以传扬，这样，作恶的人得以按合神心意的方式受管教、受约束；同时，贫穷的和受苦的得以按需得到帮助与安慰 （6）。当教会按使徒保罗教导提摩太的原则 （7），拣选有信德的男人参与教会管理时，凡事才能规规矩矩地按次序进行 （8）。\n\n（1）徒20:28;弗4:11,12; 提前3:15;来13:20-21 （2）路1:2;路10:16;约20:23;罗10:14;林前4:1;林后5:19-20;提后4:2 （3）徒14:23;多1:5 （4）提前3:8-10 （5）腓1:1;提前4:14 （6）徒6:1-4;多1:7-9 （7）提前3 （8）林前4:2\n\n第三十一条论教会圣职\n\n我们相信，牧师、长老与执事都当按圣经的吩咐，藉着祷告，经教会合法有序的选举而产生 （1）。因此，各人必须注意，不可用不符合程序的方法获取教会圣职。他须等候神的呼召；如此他才有确实的见证，并确知所蒙的呼召是出于神 （2）。牧师无论身居何处，都有同样的权力和权柄，因为他们都是世上唯一的主教、教会唯一的元首（3）耶稣基督的仆人 （4）。为使这一圣洁的条例不受侵犯或亵慢，我们宣告，每个人都必须格外尊重牧师和教会中的长老，为他们所做的工而敬重他们 （5），尽可能与他们和平相处，不要抱怨，也不要与他们有口角之争。\n\n（1）徒1:23,24; 徒6:2,3 （2）徒13:2;林前12:28;提前4:14;提前5:22;来5:4 （3）林后5:20;彼前5:1-4 （4）太23:8,10;弗1:22,弗5:23 （5）帖前 5:12,13;提前5:17;来13:17\n\n第三十二条论教会规章和教会纪律\n\n我们相信，虽然教会的治理者制定出一套规章来维护教会秩序是好的，是有益处的，但同时，他们必须时刻谨防所制定的规章偏离我们唯一的主， 即基督的吩咐 （1）。因此，我们弃绝一切出于人，又束缚和控制人的良心、影响人敬拜神的想法和规条 （2）。我们只接受有益于保持和促进和谐统一，并使会众都顺服神的规定 （3）。归根结底，执行教会纪律、开除教籍都应符合神的话语 （4）。\n\n（1）提前3:15 （2）赛29:13;太15:9;加5:1 （3）林前14:33 （4）太16:19;太18:15-18;罗16:17;林前5;提前1:20\n\n第三十三条论圣礼\n\n我们相信，慈爱的神因顾念我们的愚笨和软弱，为我们设立了圣礼，用以印证他所赐的应许，也为他赐下美好的旨意和恩典作保证 ,藉此建立并坚固我们的信心 （1）。 他在圣言 （2）之外辅以圣礼，为要借着我们的感官，将他用话语向我们宣告的和他在我们心中做成的一切更好地展现给我们，以此证实他赐给我们的救恩。因此，圣礼是内在不可见之事的外在标记与印证。藉着圣礼，神通过圣灵在我们心中做工 （3）。因此，这些标记并非虚空或毫无意义，以至于欺哄我们，因为它们代表的是耶稣基督，离了他，它们就失去了意义 （4）。此外，对于基督为我们设立的圣礼数目，我们感到满足。他设立了两个圣礼 ：洗礼和耶稣基督的圣餐 （5）。\n\n（1）创17:9-14;出12;罗4:11 （2）太28:19;弗5:26 （3）罗2:28,29; 西2:11-12 （4）太28:19 （5）太26:26-28;林前11:23-26\n\n第三十四条论圣洗礼\n\n我们相信并承认，耶稣基督成全了律法（罗 10:4），藉着他所流的宝血， 他终止了人为了赎罪已经做出的、 可能去做的和将要做的一切流血行为 ；他废除了与血有关的割礼，并设立圣洗礼取代了它 （1）；藉着洗礼，我们归入神的教会，从不信之人和假信仰中被分别出来，身上带着他的印记和标记，完全将自己交托与他 （2）。这是神向我们见证他永远是我们的神、我们恩慈的父。\n\n出于这个原因，神吩咐说一切属他的人都要用清水受洗归入“圣父、圣子、圣灵的名”（太 28:19）。藉此他表明，正如水浇在或洒在身上就洗去污垢一样，藉着圣灵，基督的血同样浇在我们心里 （3），洗去我们的罪，使我们的灵魂得洁净 （4）；圣灵使我们重生， 将我们从可怒之子变为神的儿女 （5）。这一切不是洗礼之水所带来的功效（6），而是靠着神的儿子流宝血成就的（7）。他所流的宝血是我们的红海 （8），我们必须穿行红海才能逃脱法老，即撒但的辖制，进入属灵的迦南美地。\n\n因此，牧师为我们施行的是圣洗礼，是人眼所能见的，而神赐我们的是这圣礼所要表明的，即人眼不能见的恩赐和恩典。他洗净我们污秽的、不义的灵魂 （9），赐我们新心，并使之充满主的安慰；又保证做我们的慈父，给我们披戴新人，脱去旧人和一切旧人的行为 （10）。\n\n因此，我们相信，凡渴求永生的人都当受洗。人一生只需受洗一次 （11），不应重复受洗，因为我们不能重生两次。此外，洗礼不是仅在我们受洗的那一刻于我们有益，而是使我们终生受益。正因如此，我们弃绝重洗派的错谬，他们不满足于一生只受一次洗，也强烈反对信徒的婴孩受洗。我们相信， 根据神赐给我们儿女的应许（ 12），信徒的婴孩应当受洗，领受圣约的印记， 正如过去以色列的婴孩基于同样的应许受割礼一样。基督流血洗除信徒儿女的罪丝毫不亚于洗除成人的罪 （13）。因此，他们应当受基督为他们成就的洗礼这一圣约印记 ，因为神在律法中吩咐说，孩子出生后不久，母亲就应当为他献上一只羊羔（14）。这预表着耶稣基督受苦、受死所成就的洗礼。由于洗礼对我们儿女的重要意义等同于割礼对当年以色列百姓的意义，因而保罗称洗礼为“基督的割礼”（西2:11）。\n\n（1）西 2:11 （2）出12:48;彼前2:9 （3）太3:11;林前12:13 （4）徒22:16;来9:14; 约壹1:7;启1:5 （5）多3:5 （6）彼前3:21 （7）罗6:3;彼前1:2;彼前2:24 （8）林前10:1-4 （9）林前6:11;弗5:26 （10）罗6:4;加3:27 （11）太28:19;弗4:5 （12）创17:10-12;太19:14;徒2:39 （13）林前7:14 （14）利12:6\n\n第三十五条论圣餐\n\n我们相信并承认，我们的救主耶稣基督设立了圣餐（1），为要喂养那些已被圣灵重生并被归入神的家，即教会的人。\n\n重生的人有双重生命 （2）：其一是今世肉身的生命，那是与生俱来的，人人都有的；其二是属灵的、属天的生命，那是他们重生时被赋予的，是与基督的肢体相交时，从听福音真道而得来的 （3），这种生命并非人人都有，是神单单赐给他选民的。\n\n正如为了喂养人人都有的、 今世肉身的生命，神赐下地上看得见、摸得着的粮食给所有人一样，为了喂养信徒特有的属灵、属天的生命，神赐给所有信徒从天上降下的生命的粮食（约 6:51），即耶稣基督 （4）。当信徒吃他的时候，即凭信心领受耶稣基督 （5）的时候，他们的属灵生命就得到基督的喂养 （6）。\n\n为了向我们显明这属灵的、属天的粮食，基督设立了圣餐。他以属地的、可见的饼代表他的身体，以酒代表他所流的血 （7）。他向我们表明，正如我们伸手领取，又用嘴吃喝的圣餐必使我们的肉身生命得喂养一样，当我们凭信心（8），即我们灵魂的手和口，从心里领受唯一救主基督的真身体与宝血时，我们的属灵生命无疑也会得到喂养。\n\n毋庸置疑，耶稣基督吩咐我们领他的圣餐并不是徒然的。在圣餐中，他藉着这些圣洁的标记将向我们显明的一切放在我们心里。虽然我们不明白这种做工的方式，正如我们不明白圣灵隐秘的工作 （9），但是，我们吃的是基督的真肉身，喝的是他的真宝血这一说法并没有错。然而，我们不是用嘴吃喝，而是凭信心用心灵吃喝。耶稣基督虽然一直坐在天上父神的右边 （10），但他始终通过信心这一纽带与我们交通。在这属灵的筵席上，基督使我们分领他自己，并在他一切的恩惠上有份；他也给我们恩典，让我们得享他以及他受苦受死所得来的功德 （11）。藉着吃他的身体，基督使我们贫瘠的灵魂得滋养、得强健、得安慰；藉着喝他的血，他使我们的灵魂被更新、得舒畅。\n\n虽然圣餐本身与它所表明的不能分开，但是，并非所有人都能领受后者 （12）。恶人领圣餐是吃喝自己的罪，却领受不到圣餐所包含的真理。因此，犹大与行邪术的西门虽然都领了圣餐，但他们没有领受到圣餐所表明的基督（13）。基督只与信徒相通 （14）。 最后，神的子民聚会 （15），以谦卑、敬畏的心领受圣餐，以感恩的心记念我们救主基督的死，并宣告自己的基督信仰 （16）。因此，人不可没有先省察自己 ，就来到主的桌前，以免吃这饼、喝这杯时吃喝了自己的罪（林前11:28-29）。简言之，领圣餐激励我们更加热爱神、热爱我们的邻舍。因此，我们将掺杂在圣礼中的人为的添加和当受神咒诅的臆造弃为糟粕。我们宣告，我们以基督和使徒们所教导的圣餐礼为满足，并且只按他们所传述的来讲论圣餐的事。\n\n（1）太26:26-28;可14:22-24;路22:19-20;林前11:23-26 （2）约3:5,6 （3）约5:25 （4）约6:48-51 （5）约6:63;约10:10 （6）约6:40,47 （7）约6:55;林前10:16 （8）弗3:17 （9）约3:8 （10）可16:19;徒3:21 （11）罗8:32;林前10:3-4 （12）林前2:14 （13）路22:21,22; 徒8:13,21 （14）约3:36 （15）徒2:42;徒20:7 （16）徒 2:46;林前11:26\n\n第三十六条论民事管理\n\n我们相信，由于人的败坏，我们恩慈的神设立了君王（国家领导人 ）、诸侯与治民官长 （1）。他希望世人受法律、法规的约束 （2），目的是使人不能任意妄为，一切都按秩序而行 （3）。为了这个目的，神也赐权柄给政府，刑罚作恶的，保护行善的（罗 13:4）。他们抑恶扬善的责任不限于维护公共秩序，也用于保护教会及其传道工作（4），预备基督国度的到来，使福音广传，也使人人都能按圣经的吩咐尊荣神、侍奉神。\n\n此外，每个人，无论他是什么身份、地位，处于何种境遇，都当顺服执政掌权的，向他们纳税，尊敬他们， 并在不违反圣经 （5）的一切事上 （6）顺服他们。我们应该为他们代祷，求神在凡事上带领他们，也求神使我们可以敬虔、端正，平安无事地度日（提前 2:1，2） 。\n\n因此，我们强烈谴责重洗派和其他造反者，以及所有反对执政掌权者和治民官长，暗中破坏公义 （7），推行凡物公用，破坏神为人设定之道德规范的人。\n\n下文已于 1905年在荷兰召开的改革宗教会总会会议(Gereformeerde Kerken in Nederland) 上被删除：一切偶像崇拜和虚假敬拜要被除去，敌基督的国要被消灭。\n\n（1）箴8:15;但2:21;约19:11;罗13:1 （2）出18:20 （3）申1:16;申16:19;士21:25;诗82;耶21:12;耶22:3;彼前2:13,14 （4）诗2;罗13:4;提前2:1-4 （5）太17:27;太22:21;罗13:7;多3:1;彼前2:17 （6）徒4:19;徒5:29 （7）彼后2:10;犹8\n\n第三十七条论末日审判\n\n最后，我们相信，正如圣经所说的，当主所定的那日子、那时辰来到 （1）时——那日子、那时辰无人知道，当被选的人数添满 （2）时，我们的主耶稣基督将在大荣耀和威严中 （3），有形有体地 （4）从天降临，正如他升天时那样（徒 1:11）。他将宣告自己是审判活人死人的主（5），并用火焚烧这个旧世界，使之洁净 （6）。到那时，所有人，从创世之初到世界末了的一切男女老幼，都要应天使长的声音和神号筒声的召唤(帖前4:16)，面见这位大审判官 （7）。\n\n那些已经死了的人都要复活 （8），他们的灵魂要与自己以前的身体联合；那些仍活着的要在眨眼之间从必朽坏的变为不朽坏的 (9）。然后，案卷将被展开，已死的人照着他们在世上所行的受审判（启 20:12），按善恶受报（林后5:10）（10）。人所说的闲话，即使世人认为只是戏言，在审判的日子，也必要句句供出来（太 12:36）；人的秘密和伪善都要被公诸于众。因此，这审判对恶人和作恶的而言是可怕的 （11），而对蒙选称义的人而言，却是极大的喜乐和安慰，因为他们将完全得救赎，并要得劳苦作工的果子 （12）。他们的无辜要显明在众人面前；他们要看见神严厉报复那些在世上逼迫他们、 压迫他们、虐待他们的恶人 (13）。\n\n恶人将因其良心作证而被定罪。他们将永远不死，只是要在为魔鬼及其使者所预备的永火中 （14）（太25:41）受痛苦的煎熬 （15）；而持守真道的选民将得荣耀的冠冕。神子要在父神（太 10:32）和他拣选的天使面前承认他们的名(16)。神要擦去他们一切的眼泪（启 21:4）(17)。他们所信的，虽然目前被许多审判官和治民长官定为异端邪说，但到那时，却要被神子承认为真信仰。神要给他们人心未曾想到的 (18)荣耀作丰厚的赏赐。因此，我们极其盼望那日的到来，好在我们的主耶稣基督里充分享受神所应许的一切。“阿们！主耶稣啊，我愿你来！”（启22:20） （1）太24:36;太25:13;帖前5:1,2 （2）来11:39-40;启6:11 （3）太24:30;太25:31 （4）启1:7 （5）太25:31-46;提后4:1;彼前4:5 （6）彼后3:10-13 （7）申7:9-11;启20:12-13 （8）但12:2;约5:28-29 （9）林前15:51,52 ;腓3:20-21 （10）来9:27;启22:12 （11）太11:22;太23:33;罗2:5,6;来10:27;彼后2:9;犹15;启14:7 （12）路14:14;帖后1:3-10;约壹4:17 （13）启15:4;启18:20 （14）太13:41-42;可9:48;路16:22-28;启21:8 （15）启20:10 （16）启3:5 （17）赛25:8;启7:17 （18）但12:3;太5:12;太13:43;林前2:9;启21:9-22:5", "status": "附件阅读版 · 网站逐字核验未完成", "note": "用户提供的《敬拜赞美手册》（2015）印刷页 11–47，清理换行、页码与排版空白；内容含原书经文注释。不是已完成逐字校验的 CCI 网站转录。"}, {"title": "海德堡要理问答", "url": "https://ccifellowship.org/books/book-of-praise/confessions/heidelberg-catechism", "text": "海德堡要理问答\n\n中国改革宗教会的三项联合信条中的第二个信条是《海德堡要理问答》 （简称《要理问答》，下同） 。它写于德国的海德堡，是应德国领地上最有影响力的君主选帝侯腓特烈三世（ 1559-1576）的要求写成的。这位敬虔的君主指派海德堡大学二十八岁的神学教授乌尔西努（Zacharius Ursinus）和他的宫廷牧师 ——二十六岁的俄利维亚努（ Caspar O levianus ）编写一本教义问答的册子，用于教导年轻人，也为牧师和教师提供教义指南。后来，这本小册子被命名为《海德堡要理问答》。在准备过程中，腓特烈得到了海德堡大学全体神学教师的建议和帮助。《要理问答》在海德堡总会会议上被采纳，并在德国出版，腓特烈三世于 1563年1月19日特意为它作序。同年在海德堡，它的拉丁文版正式出版；德文版也出了第二、第三版，每次再版时都作了一些增补。《要理问答》出版后不久就被分成了 52个主日，以便牧者在每个星期日讲解一个主日的内容，一年讲解一遍。\n\n在荷兰，一个名叫达斯努斯（ Petrus Dathenus ）的人将《要理问答》翻译成了荷兰语，并把该译本加进了1566年出版的荷兰文《日内瓦诗集》（ the Genevan Psalter）中。它一经出版就广受荷兰教会的喜爱。同年，加百列牧师（ Peter Gabriel ）带头在他牧养的阿姆斯特丹教会用每个主日下午的敬拜时间讲解《要理问答》。十六世纪的改革宗教会全国总会会议正式将《要理问答》收纳为改革宗教会三项联合信条之一，并要求圣职人员在就职前签署认同书，牧师则要向会众讲解《要理问答》。1618-1619年的多特大会上还特别强调了这些要求。 《要理问答》已经被翻译成很多种语言，它是改教时期出现的几个要理问答中最有影响力、受到最广泛认可的一个。\n\n主日1\n\n1．问：或生或死，你唯一的安慰是什么？ 答：或生或死 （1），我的身体和灵魂都不属于我自己（2），而属于我信实的救主耶稣基督 （3）。他用自己的宝血完全偿还了我一切的罪债 （4），并且救我脱离魔鬼一切的权势 （5）。他如此地保守我 （6），若没有天父的允许，我连一根头发也不能掉落 （7）。的确，他叫万事互相效力，使我得救 （8）。故此，他也藉着圣灵确保我得到永生 （9），并且使我从今以后甘心乐意地为他而活（10）。\n\n（1）罗14:7-9 （2）林前6:19-20 （3）林前3:23; 多2:14 （4）彼前1:18-19; 约壹1:7,2:2 （5）约8:34-36; 来2:14-15; 约壹3:8 （6）约6:39-40,10:27-30; 帖后3:3; 彼前1:5 （7）太10:29-31; 路21:16-18 （8）罗8:28 （9）罗8:15-16; 林后1:21-22,5:5; 弗1:13-14 （10）罗8:14\n\n2．问：为了在这样的安慰中快乐地生或死，你必须知道哪些事呢？ 答：我必须知道三件事：第一、我的罪恶和愁苦有多么深重（1）。第二、我怎样才能得救，并脱离这一切的罪恶和愁苦（2）。第三、我当如何为这样的拯救而感谢神（3）。\n\n（1）罗3:9-10; 约壹1:10 （2）约17:3; 徒4:12,10:43 （3）太5:16; 罗6:13; 弗5:8-10; 彼前2:9-10\n\n第一部论人的罪和愁苦\n\n主日2\n\n3．问：你从何处得知你的罪恶和愁苦呢？ 答：从神的律法 （1）。\n\n（1）罗3:20,7:7-25\n\n4．问：神的律法对我们有什么要求呢？ 答：基督就此在马太福音第 22章中概括地教导我们：“你要尽心、尽性、尽意，爱主你的神 （1）。这是诫命中的第一，且是最大的。其次也相仿，就是要爱人如己（2）。这两条诫命是律法和先知一切道理的总纲。”\n\n（1）申6:5 （2）利19:18\n\n5．问：你能完全遵守这些诫命吗？ 答：不能 （1），因为我的本性是倾向于憎恨神和我的邻舍的（2）。\n\n（1）罗3:10,23; 约壹1:8,10 （2）创6:5,8:21; 耶17:9; 罗7:23,8:7; 弗2:3; 多3:3 主日3\n\n6．问：神原本就把人造得如此邪恶和悖逆吗？ 答：不是。恰恰相反，神将人造得甚好 （1），且是按照他自己形像造的 （2），换言之， 人有公义和真实的圣洁（3）；目的是要人能正确地认识他的创造者神 （4），衷心地爱他，与他同住在永远的福乐中，并赞美和荣耀他（5）。\n\n（1）创1:31 （2）创1:26-27 （3）弗4:24 （4）西3:10 （5）诗8\n\n7．问：那么，败坏的人性从何而来呢？ 答：从我们的始祖亚当和夏娃在伊甸园中的悖逆和堕落而来（1），人性因此变得极其败坏（2），以致我们都在罪中成孕而生 （3）。\n\n（1）创3 （2）罗5:12,18-19 （3）诗51:5\n\n8．问：我们是否如此败坏，以致完全没有能力行任何的善，反倒倾向于诸般的恶呢？ 答：是的 （1）。除非神的灵使我们重生 （2）。\n\n（1）创6:5,8:21; 伯14:4; 赛53:6 （2）约3:3-5\n\n主日4 9．问：神在律法中要求人做他们所做不到的事，这岂不是不公平吗？ 答：并非如此！因为神造的人本来有能力遵行律法 （1），但人因受了魔鬼的引诱 （2），自甘悖逆 （3），强夺了神赐给他们以及他们所有后裔遵行律法的能力 （4）。\n\n（1）创1:31 （2）创3:13; 约8:44; 提前2:13-14 （3）创3:6 （4）罗5:12,18-19\n\n10．问：神会任凭这种悖逆和反叛不受惩罚吗 ? 答：当然不会。神极其恨恶我们的原罪和实际的罪，所以神要在今生和永恒中，以公义的审判来刑罚这些罪 （1），正如神所宣告的 （2）：“凡不常照律法书上所记一切之事去行的，就被咒诅。”（加 3:10）\n\n（1）出34:7; 诗5:4-6,7:11; 鸿1:2; 罗1:18,5:12; 弗 5:6; 来9:27 （2）申27:26\n\n11．问：但是，神不也是慈爱的吗？ 答：神确实是慈爱的 （1），但同时他也是公义的 （2）。按着他的公义，凡干犯他至高威严的罪都必须受到最严厉的刑罚，就是身体和灵魂都要受永刑 （3）。\n\n（1）出20:6,34:6-7; 诗103:8-9 （2）出20:5,34:7; 申7:9-11; 诗5:4-6; 来10:30-31 （3）太25:45-46\n\n第二部论我们的得救\n\n主日5\n\n12．问：既然按照神公义的审判，我们都当受到今生及永世的刑罚，那么我们怎样才能逃脱这刑罚，并再次蒙神恩宠呢？ 答：神要求他的公义得到满足 （1），因此，罪债必须得到完全的偿还，或是由我们自己偿还，或是由别人代为偿还（2）。\n\n（1）出20:5,23:7; 罗2:1-11 （2）赛53:11; 罗8:3-4\n\n13．问：我们自己能够偿还这罪债吗？ 答：当然不能。相反，我们每天都在加增罪债 （1）。\n\n（1）诗130:3; 太6:12; 罗2:4-5\n\n14．问：有没有其他受造物能替我们赎罪呢？ 答：没有。首先，神不会因人犯的罪而刑罚其他受造物（1）。其次，没有一个受造物能够承担神对罪的永怒（2），从而使人得到拯救。\n\n（1）结18:4,20; 来2:14-18 （2）诗130:3; 鸿1:6\n\n15．问：那么，人必须寻求一位怎样的中保和救赎者呢？ 答：他必须是真人 （1），且是无罪的人 （2）；但同时，他必须比一切受造物更有能力，也就是说，他同时必须是真神（3）。\n\n（1）林前15:21; 来2:17 （2）赛53:9; 林后5:21; 来7:26 （3）赛7:14,9:6; 耶23:6; 约1:1; 罗8:3-4\n\n主日6\n\n16．问：为什么他必须是真人，且是无罪的人？ 答：他必须是真人，因为按着神公义的要求，人犯罪，必须由人来偿还罪债 （1）；他必须是无罪的人，因为罪人不能为他人偿还罪债 （2）。\n\n（1）罗5:12,15; 林前15:21; 来2:14-16 （2）来7:26-27; 彼前3:18\n\n17．问：为什么他必须同时是真神呢？ 答：他必须是真神，才能藉着他神性的大能 （1），在他的人性中担当起神的忿怒 （2），并使我们重获他为我们赢得的公义和生命 （3）。\n\n（1）赛9:6 （2）申4:24; 鸿1:6; 诗130:3 （3）赛53:5,11; 约3:16; 林后5:21\n\n18．问：那么，谁是那位中保，既是真神，同时又是真实而无罪的人呢？ 答：就是我们的主耶稣基督 （1），神使“他成为我们的智慧、公义、圣洁、救赎”（林前 1:30）。\n\n（1）太1:21-23; 路2:11; 提前2:5,3:16\n\n19．问：你从哪里得知这事呢？ 答：从神圣的福音中得知。这福音是神首先在伊甸园里亲自启示（1），后来由族长 （2）和众先知 （3）宣告，并由律法中所论及的献祭和其他礼仪来预表 （4），最后藉着他的独生子来成就的（5）。\n\n（1）创3:15 （2）创12:3,22:18, 49:10 （3）赛53; 耶23:5-6; 弥7:18-20; 徒10:43; 来1:1 （4）利1:7; 约5:46; 来10:1-10 （5）罗10:4; 加4:4-5; 西2:17\n\n主日7\n\n20．问：因着亚当，众人都灭亡了 。那么是否藉着基督，众人都得救了呢？ 答：不是。只有那些凭真信心连于基督，并接受他一切恩惠的人才会得救 （1）。\n\n（1）太7:14; 约1:12,3:16,18,36; 罗11:16-21\n\n21．问：什么是真信心？ 答：真信心是一种确知，藉此我认定神在圣经中向我们启示的一切皆为真理 （1）；同时，真信心也是一种确信（2），坚信神完全是出于他的恩典，且单单因着基督的功劳（3），把赦罪之恩 （4）、永远的公义和救赎，不仅赐给其他信徒，也赐给了我 （5）。这信心是圣灵藉着福音在我心中做成的 （6）。\n\n（1）约17:3,17; 来11:1-3; 雅2:19 （2）罗4:18-21,5:1,10:10; 来4:16 （3）罗3:20-26; 加2:16; 弗2:8-10 （4）罗1:17; 来10:10 （5）加2:20 （6）徒16:14; 罗1:16,10:17; 林前1:21\n\n22．问：那么，基督徒必须相信什么？ 答：基督徒必须相信福音的一切应许 （1），也就是基督教大公无疑信条总结并教导的内容。 （1）太28:19; 约20:30-31\n\n23．问：这些信条有哪些内容？ 答：我信神，全能的父，创造天地的主。 我信我主耶稣基督，神的独生子； 因圣灵感孕，从童贞女马利亚所生；在本丢彼拉多手下受难，被钉在十字架上，受死， 被埋葬，降在阴间；第三天从死里复活；他升天，坐在全能父神的右边；将来必从那里降临，审判活人死人。 我信圣灵。 我相信圣而公之教会，我相信圣徒相通；我相信罪得赦免； 我相信身体复活；我相信永生。阿们！\n\n主日8\n\n24．问：这些信条是怎样划分的呢？ 答：分为三部分：第一部分论及父神和我们的受造；第二部分论及子神和我们的得赎；第三部分论及圣灵和我们的成圣。\n\n25．问：既然神只有一位 （1），那么你为什么说有三位，即圣父、圣子和圣灵呢？ 答：因为神在圣经里就是这样启示他自己的 （2），这三个不同的位格乃是独一、真实、永在的神。\n\n（1）申6:4; 赛44:6,45:5; 林前8:4,6 （2）创1:2,3; 赛61:1,63:8-10; 太3:16-17,28:18-19; 路4:18; 约14:26,15:26; 林后13:14; 加4:6; 多3:5-6\n\n主日9 26．问：当你宣告“我信神，全能的父，创造天地的主”时，你相信什么？ 答：我相信我主耶稣基督永在的父也是我的神、我的父。虽然他有大能从无有中创造了天地并其中的万有（ 1），又以他永恒的计划和护理托住并管理着这一切（ 2），但他因他儿子基督的缘故作了我的神和天父（ 3）。我毫无疑惑、完全相信他必供应我身体和灵魂一切的需要 （4）；此外，在我经过今生的流泪谷时，无论他给予我什么样的逆境，他都会使之变为于我有益 （5）。他之所以能如此行，乃因他是全能的神 （6）；他也乐意如此行，因他是我信实的天父 （7）。\n\n（1）创1;2; 出20:11; 伯38,39; 诗33:6; 赛44:24; 徒4:24,14:15 （2）诗104:27-30; 太6:30,10:29; 弗1:11 （3）约1:12-13; 罗8:15-16; 加4:4-7; 弗1:5 （4）诗55:22; 太6:25-26; 路12:22-31 （5）罗8:28 （6）创18:14; 罗8:31-39 （7）太6:32-33,7:9-11\n\n主日10\n\n27．问：你如何理解“神的护理”？ 答：神的护理是指神藉着他全能、永在的能力 （1），仍然托住天地万有，如同他用手托住一般 （2）；他也管理着这一切 ——不论一草一木、雨水干旱、丰年荒年、日用饮食、健康疾病、富足贫穷 （3），所临到我们的一切，皆非出于偶然 （4），乃是出于天父大能的手 （5）。\n\n（1）耶23:23-24; 徒17:24-28 （2）来1:3 （3）耶5:24; 徒14:15-17; 约9:3; 箴22:2 （4）箴16:33 （5）太10:29\n\n28．问：知道神创造万有并且仍护理、托住万有对我们有何益处呢？ 答：这让我们可以在逆境中忍耐 （1），在顺境中感恩（2）；对于未来，我们可以深信这位信实的父神，任何受造之物都不能叫我们与神的爱隔绝 （3），因万有都在他的手中；若不是出于神的旨意， 万有都不能转动（4）。\n\n（1）伯1:21-22; 诗39:10; 雅1:3 （2）申8:10; 帖前5:18 （3）诗55:22; 罗5:3-5,8:38-39 （4）伯1:12,2:6; 箴21:1; 徒17:24-28\n\n子神和我们的得赎\n\n主日11\n\n29．问：为什么神的儿子被称为“耶稣”，即救主呢？ 答：因为他把我们从一切的罪中拯救出来 （1），又因为除他以外别无拯救 （2）。\n\n（1）太1:21; 来7:25 （2）赛43:11; 约15:4-5; 徒4:11-12; 提前2:5\n\n30．问：那些从圣徒身上、从自身或从别处寻找拯救或福乐的人，也信独一的救主耶稣吗？ 答：他们不信。虽然，在言语上，他们指着耶稣夸口，但实际上却否认独一的救主耶稣 （1）。然而，耶稣是不是一位完全的救主，二者之一必是真理： 要么耶稣不是一位完全的救主， 要么凡凭真信心接受这位救主的人，就必定在他里面得着救赎所必需的一切 （2）。\n\n（1）林前1:12-13; 加5:4 （2）西1:19-20,2:10; 约壹1:7\n\n主日12\n\n31．问：为什么称他为“基督”，即受膏者呢？ 答：因为他被父神所立，又被圣灵所膏 （1），作我们的大先知和教师 （2），向我们完全启示神在我们的救恩上预定的奥秘计划和旨意 （3）；他是我们唯一的大祭司（4），藉着他一次献上的身体救赎了我们 （5），又在父神面前不住地为我们代求 （6）；他是我们永远的君王（7），用他的话语和圣灵统管我们，护卫并保守我们不失去他为我们获得的救恩 （8）。\n\n（1）诗45:7; (来1:9); 赛61:1 (路4:18); 路3:21-22 （2）申18:15; ( 徒3:22) （3）约1:18,15:15 （4）诗110:4 (来7:17) （5）来9:12,10:11-14 （6）罗8:34; 来9:24; 约壹2:1 （7）亚9:9; (太21:5); 路1:33 （8）太28:18-20; 约10:28; 启12:10-11\n\n32．问：为什么你被称为基督徒呢？ 答：因为藉着信，我成为基督肢体的一部分 （1），从而在他的受膏上有份 （2），以至于我作为先知宣告他的名（3）；作为祭司把自己献给他，当作感恩的活祭 （4）；又作为君王，用自由和无亏的良心在今生与罪和魔鬼争战 （5），并且从此以后，与他一同作王，永远统治万物（6）。\n\n（1）林前12:12-27 （2）珥2:28; (徒2:17); 约壹2:27 （3）太10:32; 罗10:9-10; 来13:15 （4）罗12:1; 彼前2:5,9 （5）加5:16-17; 弗6:11; 提前1:18-19 （6）太25:34; 提后2:12\n\n主日13\n\n33．问：既然我们也是神的儿女，为什么基督还被称为神的独生子呢？ 答：因为唯有基督是神永恒的、本来的儿子 （1）；而我们是因着基督，靠着恩典，蒙神收纳，成为他的儿女的（2）。\n\n（1）约1:1-3,14,18; 3:16; 罗8:32; 来1; 约壹4:9 （2）约1:12; 罗8:14-17; 加4:6; 弗1:5-6\n\n34．问：你为什么称他为“我们的主”呢？ 答：因为他不是用金银 ,而是用他的宝血 （1）买赎了我们，使我们的身体和灵魂 （2）脱离罪的捆绑； 他又将我们从撒但一切的权势中解救出来，使我们作他自己的产业（3）。\n\n（1）彼前1:18-19 （2）林前6:20; 提前2:5-6 （3）西1:13-14; 来2:14-15\n\n主日14 35．问：你宣告说“因圣灵感孕，从童贞女马利亚所生”，这句话是什么意思？ 答：这句话的意思是： 神的永恒儿子，从现在到永远都是永恒的真神 （1）；因圣灵的运行 （2），他从童贞女马利亚的血肉之身取了人的样式 （3），从而成为大卫的真正后裔（4），凡事与他的弟兄相同 （5），只是没有罪（6）。\n\n（1）约1:1; 10:30 -36; 罗1:3; 9:5; 西1:15-17; 约壹5:20 （2）路1:35 （3）太1:18-23; 约1:14; 加4:4; 来2:14 （4）撒下7:12-16; 诗132:11; 太1:1; 路1:32; 罗1:3 （5）腓2:7; 来2:17 （6）来4:15; 7:26 -27\n\n36．问：基督因圣灵感孕而生对你有什么益处呢？ 答：基督是我们的中保 （1）, 他以自己的无罪和全然圣洁，在神的面前遮盖了我成孕出生时就有的罪 （2）。\n\n（1）提前2:5-6; 来9:13-15 （2）罗8:3-4; 林后5:21; 加4:4-5; 彼前1:18-19\n\n主日15\n\n37．问：你如何理解他“受难”？ 答：基督在地上生活的整个时期，特别是最后阶段，用他的肉体与灵魂担当了神对全人类罪恶的忿怒 （1）。因此，藉着他的受难，基督成为唯一的赎罪祭 （2），他已将我们的身体和灵魂从永远的咒诅下救赎出来 （3），并从父神那里为我们获得了恩典、公义和永生 （4)。\n\n（1）赛53; 提前2:6; 彼前2:24; 3:18 （2）罗3:25; 林前5:7; 弗5:2; 来10:14; 约壹2:2,4:10 （3）罗8:1-4; 加3:13; 西1:13; 来9:12; 彼前1:18-19 （4）约3:16; 罗3:24-26; 林后5:21; 来9:15\n\n38．问：为什么基督在“本丢彼拉多手下受难”？ 答：基督本是无辜，却被属世的官长定了罪 (1）。正因如此，他使我们免受神本要施行在我们身上的严厉审判（2）。\n\n（1）路23:13-24; 约19:4,12-16 （2）赛53:4-5; 林后5:21; 加3:13\n\n39．问：基督被钉死在十字架上，而非以其他方式受死有什么特殊意义吗？ 答：有。藉此我确信，他担当了本该加在我身上的咒诅，因为凡钉在十字架上的是受神咒诅的 （1）。\n\n（1）申21:23; 加3:13\n\n主日16\n\n40．问：基督为什么必须自己卑微 , 以至于死呢？ 答：因为神的公义和真理 （1）要求如此：除了神子的死以外的任何方法都不能为我们偿还罪债 （2）。\n\n（1）创2:17 （2）罗8:3; 腓2:8; 来2:9,14-15\n\n41．问：为什么耶稣要被“埋葬”呢？ 答：他被埋葬 ,证明他确实死了 （1）。\n\n（1）赛53:9; 约19:38-42; 徒13:29; 林前15:3-4 42．问：既然基督已经为我们死了，为什么我们还必须死呢？ 答：我们的死不是为自己的罪作赎价，而是终止犯罪，是进入永生的门 （1）。\n\n（1）约5:24; 腓1:21-23; 帖前5:9-10\n\n43．问：从基督在十字架上的献祭和受死，我们还得到了哪些益处呢？ 答：藉着基督的死，我们的旧人与他同钉十字架，并与他同死、同埋葬 （1）,以至于肉体的邪情私欲不能再在我们里面作王 （2）；相反，我们可以将自己当作感恩的祭献给他（3）。\n\n（1）罗6:5-11; 西2:11-12 （2）罗6:12-14 （3）罗12:1; 弗5:1-2\n\n44．问：信条中为什么加上“降在阴间”这句话呢？ 答：好使我在极大的悲痛和试探中能够坚信 ，藉着他在遭受这一切苦难 （1）时所忍受的无法言表的痛苦、疼痛、恐惧和苦楚，尤其是在十字架上所忍受的，我主耶稣基督已经拯救我脱离了地狱的痛苦和折磨 （2）；也使我能因信这一切而得着安慰。\n\n（1）诗18:5,6; 116:3; 太26:36-46; 27:45,46; 来5:7-10 （2）赛53\n\n主日17\n\n45．问：基督的复活使我们得到了哪些益处呢？ 答：第一，他藉着复活战胜了死亡，叫我们在他以死为我们获得的义上有份 （1）。第二，藉着他的能力，我们也得以复活，得着新生命 （2）。第三，基督的复活是我们将来荣耀复活的确据 （3）。\n\n（1）罗4:25; 林前15:16-20; 彼前1:3-5 （2）罗6:5-11; 弗2:4-6; 西3:1-4 （3）罗8:11; 林前15:12-23; 腓3:20-21\n\n主日18\n\n46．问：你如何理解他“升天”？ 答：基督在门徒眼前从地上被接升天 （1）；他为我们的益处（2）留在那里，直到他再来，审判活人死人 （3）。\n\n（1）可16:19; 路24:50-51; 徒1:9-11 （2）罗8:34; 来4:14,7:23-25,9:24 （3）太24:30; 徒1:11\n\n47．问：这样，基督岂不是没有照他所应许的，与我们同在直到世界的末了吗 （1）？ 答：基督是真人，也是真神。就他的人性而言，他已经不在地上了 （2）；但就他的神性、威严、恩典和灵而言，他从未离开过我们 （3）。\n\n（1）太28:20 （2）太26:11; 约16:28,17:11; 徒3:19-21; 来8:4 （3）太28:18-20; 约14:16-19,16:13\n\n48．问：但如果基督的神性所在之处不都有人性同在的话，他的神人二性岂不是彼此分离了吗？这岂不是说他的神人二性是彼此分开的吗？ 答：绝非如此！因为他的神性是不受限制、无处不在的 （1）。因此，他的神性必然超乎他所取的人性，却又在人性之内，并且仍与之联合 （2）。 （1）耶23:23-24; 徒7:48-49 （2）约1:14,3:13; 西2:9\n\n49．问：基督升天对我们有什么益处呢？ 答：第一，他在天上他父面前作我们的代求者 （1）；第二，我们的主耶稣基督的肉身在天上，这就确保了基督作为我们的头，也要把我们这些作他肢体的带到他那里去（2）；第三，他差遣圣灵作为担保 （3），使我们藉着圣灵的能力不求地上的事，但求天上的事，那里有基督坐在神的右边 （4）。\n\n（1）罗8:34; 约壹2:1 （2）约14:2,17:24; 弗2:4-6 （3）约14:16; 徒2:33; 林后1:21-22,5:5 （4）西3:1-4\n\n主日19\n\n50．问：为什么要加上“坐在全能父神的右边”呢？ 答：因为基督升到天上，为的是要在那里彰显他是教会的头（1），父藉着他管理万有 （2）。\n\n（1）弗1:20-23; 西1:18 （2）太28:18; 约5:22-23\n\n51.问：我们从元首基督的这种荣耀中得到哪些益处呢？ 答：第一，藉着他的圣灵，基督将诸般属天的恩赐浇灌给我们这些作他肢体的人 （1）；第二，藉着他的权能，基督护卫并保守我们免遭一切仇敌的苦害 （2）。 （1）徒2:33; 弗4:7-12 （2）诗2:9; 110:1 -2; 约10:27-30; 启19:11-16 52．问：基督“将来必从那里降临，审判活人死人”，这对你有什么安慰呢？ 答：这使我能在诸般的忧愁和逼迫中，仰望并迫切地等候曾为我的缘故甘愿受神的审判， 又除去我一切咒诅的那一位来作从天降临的审判官 （1）。那时，他必要将他的和我的一切仇敌都丢入永刑中，却要将他所有的选民 ，包括我，都带到他自己那里，得享天上的喜乐和荣耀 （2）。\n\n（1）路21:28; 罗8:22-25; 腓3:20-21; 多2:13-14 （2）太25:31-46; 帖前4:16-17; 帖后1:6-10\n\n圣灵神和我们的成圣\n\n主日20\n\n53．问：论到圣灵，你相信什么？ 答：第一，我相信圣灵与父和子同为永恒的真神 （1）；第二，他也是赐给我的 （2），使我凭着真信心，在基督并他一切的恩惠中有份 （3）；又使我得安慰 （4），并永远与我同在 （5）。\n\n（1）创1:1-2; 太28:19; 徒5:3-4; 林前3:16 （2）前6:19; 林后1:21-22; 加4:6; 弗1:13 （3）加3:14; 彼前1:2 （4）约15:26; 徒9:31 （5）约14:16-17; 彼前4:14\n\n主日21\n\n54．问：论到“圣而公之教会”，你相信什么？ 答：我相信神的儿子 （1）一直在藉着他的圣灵和圣言（2），从全人类中 （3） ，从世界的起初到末了 （4）为他自己召聚、护卫、保守，并存留他的子民 （5），使之在真信心上合一 （6），成为一个蒙选得永生的教会 （7）。我相信我现在是 （8），也永远是这教会中活泼的一员（9）。\n\n（1）约10:11; 徒20:28; 弗4:11-13; 西1:18 （2）罗1:16; 10:14 -17; 弗5:26 （3）创26:4; 启5:9 （4）赛59:21; 林前11:26 （5）诗129:1-5; 太16:18; 约10:28-30 （6）徒2:42-47; 弗4:1-6 （7）罗8:29; 弗1:3-14 （8）约壹3:14,19-21 （9）诗23:6; 约10:27-28; 林前1:4-9; 彼前1:3-5\n\n55．问：你怎样理解“圣徒相通”？ 答：第一，作为基督的肢体，每一个信徒都与他联合，并在他一切的丰富与恩赐上有份 （1）。第二，每一个信徒都有义务为其他肢体的益处和福祉随时随地、甘心乐意地使用自己的恩赐 （2）。\n\n（1）罗8:32; 林前6:17; 12:4 -7, 12-13; 约壹1:3 （2）罗12:4-8; 林前12:20-27; 13:1 -7; 腓2:4-8\n\n56．问：论到“罪得赦免”，你相信什么？ 答：我相信，因基督满足了神的公义，神将不再记念我的诸罪（1），也不再记念我一生必须与之争战的罪性 （2）；反而仁慈地将基督的义赐给我，使我永不被神定罪 （3）。\n\n（1）诗103:3-4,10,12; 弥7:18-19; 林后5:18-21; 约壹1:7;2:2 （2）罗7:21-25 （3）约3:17-18,5:24; 罗8:1-2\n\n主日22\n\n57．问：“身体复活”带给你什么安慰？ 答：在我死后，不仅我的灵魂会立刻被提到基督 ——我的元首那里 （1），而且我的身体也将因着基督的大能而复活，与我的灵魂再次联合，并与基督荣耀的身体相似（2）。\n\n（1）路16:22,23:43; 腓1:21-23 （2）伯19:25-26; 林前15:20,42 -46,54; 腓3:21; 约壹3:2\n\n58．问：你从“我相信永生”这句话中得着什么安慰？ 答：既然现在我的心已经初尝到永远福乐的滋味 （1），那么此生之后，我必得享完全的福乐，就是那眼睛未曾看见、耳朵未曾听见、人心也未曾想到的福乐；我要在这样的福乐中永远赞美神 （2）。\n\n（1）约17:3; 罗14:17; 林后5:2-3 （2）约17:24; 林前2:9\n\n我们得称为义\n\n主日23\n\n59．问：相信以上这些信条对你有什么帮助 ？ 答：这使我在基督里得以在神面前称义，并且成为永生的承受者（1）。\n\n（1）哈2:4; 约3:36; 罗1:17,5:1-2 60．问：你怎样在神面前称义呢？ 答：唯独藉着真心信靠耶稣基督 （1）。尽管我的良心控告我严重地干犯了神的一切诫命，从未守住任何一条（2），并且仍然倾向于行诸般的恶 （3），但是神以他白白的恩典 （4），而非因我的任何功德 （5），将基督按律法要求完全偿还一切罪而成就的，以及他的义和圣洁都归给了我（6），好像我从来没有罪，也从未犯过任何罪，又像我自己已经做到了基督为我成就的完全的顺服一样（7），只要我凭信心接受这个恩典就够了 （8）。\n\n（1）罗3:21-28; 加2:16; 弗2:8-9; 腓3:8-11 （2）罗3:9-10 （3）罗7:23 （4）罗3:24; 弗2:8 （5）申9:6; 结36:22; 多3:4-5 （6）罗4:3-5; 林后5:17-19; 约壹2:1-2 （7）罗4:24-25; 林后5:21 （8）约3:18; 徒16:30-31; 罗3:22\n\n61．问：你为什么说唯独因信称义呢？ 答：我在神面前蒙悦纳 、得称为义 ，不是因为我的信心有什么价值 ，而是唯独因着基督的顺服、义和圣洁 （1）。唯独藉着信心，我才能得着此义，并使之成为我自己的义（2）。\n\n（1）林前1:30-31,2:2 （2）罗10:10; 约壹5:10-12\n\n主日24\n\n62．问：为什么我们的善行不能成为我们在神面前的义，或者至少是部分的义呢？ 答：因为能在神的审判台前站得住的义必须是绝对完美且完全合乎神律法的 （1）；然而，即使我们今生最好的善行都是不完美的，且是被罪玷污了的 （2）。\n\n（1）申27:26; 加3:10 （2）赛64:6\n\n63．问：神应许按着各人所行的在今生和来世奖赏各人 。即便如此，我们的善行还是不能为我们赚取什么吗 （1）？ 答：不能，因为这奖赏不是赚得的，而是出于神的恩典（2）。\n\n（1）太5:12; 来11:6 （2）路17:10; 提后4:7-8\n\n64．问：这个教导岂不会使人随性而为，甚至道德败坏吗？ 答：不会。因为凡凭真信心连于基督的人，不可能不结出感恩的果子 （1）。\n\n（1）太7:18; 路6:43-45; 约15:5\n\n圣言与圣礼\n\n主日25\n\n65．问：如此说来， 我们唯独因信才有份于基督及其一切的恩惠。那么这信是从何而来的呢？ 答：它是从圣灵而来的（1）。圣灵藉着福音的传讲在我们心里做工，生发信心 （2），并藉着圣礼的施行使之得以坚固（3）。\n\n（1）约3:5; 林前2:10-14; 弗2:8; 腓1:29 （2）罗10:17; 彼前1:23-25 （3）太28:19-20; 林前10:16\n\n66．问：什么是圣礼？ 答：圣礼是圣洁的、可见的标志和印记。神设立圣礼是为了用它们更完整地向我们宣告和印证福音的应许 （1）。这应许就是 ，因着基督在十字架上一次完成的献祭，神仁慈地赦免了我们的罪， 并赐给了我们永生 （2）。\n\n（1）创17:11; 申30:6; 罗4:11 （2）太26:27-28; 徒2:38; 来10:10\n\n67．问：圣言和圣礼都是为了使我们专心相信耶稣基督在十字架上的献祭是我们得救的唯一根基吗？ 答：是的，的确如此。圣灵藉着福音教导我们，又藉着圣礼向我们保证，我们得救完全是基于基督在十字架上一次完成的献祭（1）。\n\n（1）罗6:3; 林前11:26; 加3:27\n\n68．问：基督在新约中设立了几个圣礼？ 答：设立了两个圣礼：洗礼和圣餐 （1）。\n\n（1）太28:19-20; 林前11:23-26\n\n圣洗礼\n\n主日26\n\n69．问：洗礼是如何向你表明并印证基督在十字架上一次的献祭于你有益的呢？ 答：乃是这样：基督设立这外在的水洗 （1），并以此应许，他的宝血和圣灵必洗去我灵魂中一切的污秽，即所有的罪，正如水洗去人身体的污秽一样 （2）。\n\n（1）太28:19 （2）太3:11; 可16:16; 约1:33; 徒2:38; 罗6:3-4; 彼前3:21\n\n70．问：受基督宝血和圣灵的洗是什么意思呢？ 答：受基督宝血的洗是指藉着恩典，因基督在十字架上牺牲而为我们流的宝血，我们白白得蒙神的赦罪 （1）。受他圣灵的洗是指我们被圣灵更新，成为圣洁，作基督的肢体，叫我们越来越向罪死，且敬虔度日，无有瑕疵 （2）。\n\n（1）结36:25; 亚13:1; 弗1:7; 来12:24; 彼前1:2; 启1:5,7:14 （2）约3:5-8; 罗6:4; 林前6:11; 西2:11-12\n\n71．问：基督在哪里应许我们，他要用他的宝血与圣灵洗涤我们，正如洗礼的水洗涤我们一样呢？ 答：在基督设立洗礼时，他说“所以，你们要去使万民作我的门徒，奉父、子、圣灵的名给他们施洗”（太28:19）；“信而受洗的必然得救，不信的必被定罪”（可16:16）。圣经上称洗礼为重生的洗和除罪的洗之处，也都重申了这个应许。（多 3:5；徒22:16）\n\n主日27\n\n72．问：外在的水洗能除去罪吗？ 答：不能。唯有耶稣基督的宝血和圣灵才能洗去我们一切的罪（1）。\n\n（1）太3:11; 彼前3:21; 约壹1:7\n\n73．问：既然如此，圣灵为什么称洗礼是重生和除罪的洗呢？ 答：神如此说是有充分理由的。他要教导我们，基督的宝血和圣灵洗去我们一切的罪，正如水洗去身体上的污秽一样（1）。但更重要的是，他要藉此神圣的保证和标志使我们确信，我们灵魂中的罪污确实得以洗除，正如我们身体上的污秽被水洗去一样（2）。\n\n（1）林前6:11; 启1:5,7:14 （2）可16:16; 徒2:38; 罗6:3-4; 加3:27\n\n74．问：婴孩也要受洗吗？ 答：是的 ，因为他们与父母同属于神的圣约和教会 （1）。藉着基督的宝血，神将得救的恩典和赐人信心的圣灵应许给了他们，正如应许给他们的父母一样 （2）。因此，藉着洗礼这一圣约记号，婴孩也必须被纳入基督的教会，从而从非信徒的儿女中被分别出来 （3）。在旧约中，这是藉着割礼完成的 （4），而在新约时代，割礼已被洗礼所取代（5）。\n\n（1）创17:7; 太19:14 （2）诗22:10; 赛44:1-3; 徒2:38-39,16:31 （3）徒10:47; 林前7:14 （4）创17:9-14 （5）西2: 11-13\n\n圣餐\n\n主日28 75．问：圣餐是如何向你表明并印证，你有份于基督在十字架上一次的献祭及其一切恩惠的呢？ 答：乃是这样：基督吩咐我和众信徒吃这擘开的饼、喝这杯，为的是记念他。 藉此，他赐下了两个应许（1）：其一，正如我亲眼看见主的饼为我擘开，主的杯递给了我一样，基督的身体在十字架上为我而舍，他的宝血为我而流也是确凿无疑的；其二，正如我从牧师的手里接过并亲口尝了象征基督身体和宝血的饼和杯一样 ，基督亲自用他那被钉的身体和流出的宝血喂养和更新我的灵魂，直到永远。\n\n（1）太26:26-28; 可14:22-24; 路22:19-20; 林前11:23-25\n\n76．问：吃基督被钉的身体，喝他所流的宝血是什么意思？ 答：首先， 这意味着我们相信并接受基督所受的一切苦和他的受死，并因此获得赦罪和永生 （1）。其次，这意味着藉着住在基督和我们里面的圣灵，我们越来越与他圣洁的身体合一 （2）。因此，虽然基督在天上 （3），我们在地上，我们还是他肉中的肉，骨中的骨 （4）；我们永远靠着这一位圣灵而活，且受他掌管，正如我们身上的肢体靠着一个灵魂生存，由同一个灵魂掌管一样 （5）。\n\n（1）约6:35,40, 50-54 （2）约6:55-56; 林前12:13 （3）徒1:9-11,3:21; 林前11:26; 西3:1 （4）林前6:15,17; 弗5:29-30; 约壹4:13 （5）约6:56-58,15:1-6; 弗4:15-16; 约壹3:24\n\n77．问：基督在何处应许说，他要用自己的身体和宝血使信徒得喂养和更新，就像使他们从吃这擘开的饼、喝这杯中得喂养一样？ 答：在设立圣餐时。经上记着说：“主耶稣被卖的那一夜， 拿起饼来，祝谢了，就擘开，说：‘这是我的身体，为你们舍的。你们应当如此行，为的是记念我。’饭后，也照样拿起杯来，说：‘这杯是用我的血所立的新约。你们每逢喝的时候，要如此行，为的是记念我。’你们每逢吃这饼，喝这杯，是表明主的死，直等到他来。”（林前11:23-26）后来，保罗重申了这一应许，说：“我们所祝福的杯，岂不是同领基督的血吗？我们所擘开的饼，岂不是同领基督的身体吗？我们虽多，仍是一个饼、一个身体，因为我们都是分受这一个饼。”（林前 10:16,17）\n\n主日29\n\n78．问：那么，这饼和酒真的是变成基督的身体和宝血了吗？ 答：绝对不是！洗礼中的水并不变成基督的宝血，水本身也无法洗去罪，只不过是神所设立的记号和保证而已（1）。同样，圣餐中的饼也不变成基督真正的身体 （2）,而只是按圣礼的本质和特性 （3），被称为基督的身体（4）。\n\n（1）弗5:26; 多3:5 （2）太26:26-29 （3）创17:10-11; 出12:11,13; 林前10:3-4; 彼前3:21 （4）林前10:16-17,11:26-28\n\n79．问：那么，基督为什么称这饼是他的身体，这杯是他的血，是用他的血所立的新约呢？另外，为什么保罗也说到同领基督的身体和血呢？ 答：基督这样说是有充分理由的，因为他想藉此圣餐教导我们，正如饼和酒维持我们今世的生命一样，他那被钉的身体和流出的宝血是那喂养我们灵魂，使之存到永生的真正饮食（1）。但更重要的是，他要藉这有形的记号和保证向我们担保：第一，藉着圣灵的做工，我们的确是在分享他的真身体和宝血 （2），正如我们口里承认这为记念他而设立的神圣标记一样确定无疑；第二，他的一切苦难和顺服也确实成为我们的，好像我们受了苦，并偿还了自己的罪债一样 （3）。\n\n（1）约6:51,55 （2）林前10:16-17,11:26 （3）罗6:5-11\n\n主日30\n\n80．问：圣餐与天主教的弥撒有什么不同？ 答：圣餐向我们证明：第一，藉着耶稣基督在十字架上一次的献祭，我们所有的罪都完全得了赦免 （1）；第二，藉着圣灵，我们被连于基督 （2），如今他的真身体在天上父神的右边 （3），他要在那里接受我们的敬拜 （4）。但天主教的弥撒却教导说：第一，活人死人都不能因基督的受难而罪得赦免，除非神甫每天为人献上基督；第二，基督的身体是以饼和酒的形式呈现的，因此基督应在饼和酒中受敬拜。由上可知，弥撒基本上否定了耶稣基督的一次献祭和他的受难。它不过是一种当受咒诅的偶像崇拜而已。\n\n（1）太26:28; 约19:30; 来7:27; 9:12,25 -26,10:10-18 （2）林前6:17,10:16-17 （3）约20:17; 徒7:55-56; 来1:3,8:1 （4）约4:21-24; 腓3:20; 西3:1; 帖前1:10\n\n81．问：什么人可以到主的桌前领圣餐呢？ 答：这样的人可以领圣餐 ：他们因自己的罪厌恶自己， 但相信因基督的缘故，自己的罪已得赦免，尚存的软弱也因基督的受苦和受死得蒙遮盖；他们也越来越渴慕信心得坚固，生命得更新。但那假冒为善和不悔改的人来领圣餐，就是吃喝自己的罪了 （1）。\n\n（1）林前10:19-22; 11:26 -32\n\n82．问：那些在言行上显为不信不虔的人，也可以领圣餐吗？ 答：绝不可以，因为如此行就是亵渎神的圣约，神的忿怒会降在全会众身上 （1）。所以，照着基督和他众使徒的吩咐，基督的教会有责任使用掌管天国钥匙的权柄，不许这等人领圣餐，直到他们的生活归正为止。\n\n（1）诗50:16; 赛1:11-17; 林前11:17-34.\n\n主日31\n\n83．问：什么是天国的钥匙？ 答：就是神圣福音的宣讲和教会的纪律。藉此两者，天国向信者开放，向不信者关闭 （1）。\n\n（1）太16:19; 约20:21-23\n\n84．问：天国是如何藉着神圣福音的宣讲开放或关闭的呢？ 答：基督是这样吩咐的：当教会宣讲并公开作见证说， 因着基督的功德，神已经真正赦免了每一个信徒所有的罪时 ，天国就向凡凭真信心接受这福音应许的人敞开；当教会宣讲并公开作见证说，神的忿怒和永远的定罪加在一切不信的和假冒为善的人身上时， 天国就向所有不悔改的人关闭。根据这福音的见证，神会在今生和来世施行审判 （1）。\n\n（1）太16:19; 约3:31-36,20:21-23\n\n85．问：天国是如何藉着教会纪律开放或关闭的呢？ 答：按照基督的命令，对那些自称是基督徒，却在教义和生活上显为不信的人，首先要以兄弟般的爱反复劝诫。他们若不弃恶离罪，就当上报教会，即向长老们汇报。他们若对长老们的警告也置若罔闻，就当被禁止领圣餐，然后，被长老们排除于教会之外，因此，他们也就被神拒绝于基督国度的门外 （1）。当他们承诺并表现出真正的悔改时，便可重新被接纳为基督的肢体和教会的会员 （2）。\n\n（1）太18:15-20; 林前5:3-5; 11-13; 帖后3:14-15 （2）路15:20-24; 林后2:6-11\n\n第三部论感恩\n\n主日32\n\n86．问：既然我们不是靠自己的任何功德，而是唯独因着基督的恩典从愁苦中得拯救的，那么，为什么我们还要行善呢？ 答：因为基督用他的宝血救赎了我们，并且藉着圣灵更新我们，使我们有他的形像，好叫我们用全部的生命，为基督所赐的一切恩惠向神表明我们的感恩 （1），而他也可以得着我们的称颂 （2）。此外，这还可以使我们因着信心的果子 （3），而确信自己有信心；并且透过我们敬虔的生活，为基督赢得我们的邻舍 （4）。 （1）罗6:13; 12:1 -2; 彼前2:5-10 （2）太5:16; 林前6:19-20 （3）太7:17-18; 加5:22-24; 彼后1:10-11 （4）太5:14-16; 罗14:17-19; 彼前2:12,3:1-2\n\n87．问：那些忘恩负义、拒不悔改归向神的人能得救吗？ 答：绝对不能。因为圣经说，淫乱的、拜偶像的、奸淫的、偷窃的、贪婪的、醉酒的、辱骂的、勒索的，或诸如此类的人，必不能承受神的国 （1）。\n\n（1）林前6:9-10; 加5:19-21; 弗5:5-6; 约壹3:14\n\n主日33\n\n88．问：什么是真正的悔改或归正呢？ 答：就是指旧人死去，活出新人 （1）。\n\n（1）罗6:1-11; 林前5:7; 林后5:17; 弗4:22-24; 西3:5-10\n\n89．问：什么是旧人死去呢？ 答：即真心为犯罪得罪神而忧伤痛悔，并且越来越憎恶罪，逃离它（1）。\n\n（1）诗51:3-4,17; 珥2:12-13; 罗8:12-13; 林后7:10\n\n90．问：什么是活出新人？ 答：即藉着基督，在神里面有真心的喜乐 （1）；喜爱照着神的旨意生活，行各样的善事，并以此为乐 （2）。\n\n（1）诗51:8,12; 赛57:15; 罗5:1,14:17 （2）罗6:10-11; 加2:20\n\n91．问：什么是善事？ 答：单指那些出于真信心 （1）、符合神的律法 （2）并为荣耀神（3）而行的事， 不是那些出于我们一己之见或人的规条而行的事 （4）。\n\n（1）林前10:31 （2）利18:4; 撒上15:22; 弗2:10 （3）约15:5; 罗14:23; 来11:6 （4）申12:32; 赛29:13; 结20:18-19; 太15:7-9\n\n十诫\n\n主日34\n\n92．问：什么是神的律法？ 答：神吩咐这一切的话，说：“我是耶和华你的神，曾将你从埃及地为奴之家领出来。\n\n一、除了我以外 ,你不可有别的神。\n\n二、不可为自己雕刻偶像；也不可做什么形像仿佛上天、下地和地底下、水中的百物。不可跪拜那些像；也不可侍奉它，因为我耶和华你的神，是忌邪的神。恨我的，我必追讨他的罪，自父及子，直到三四代；爱我、守我诫命的， 我必向他们发慈爱，直到千代。\n\n三、不可妄称耶和华你神的名；因为妄称耶和华名的，耶和华必不以他为无罪。\n\n四、当记念安息日，守为圣日。六日要劳碌作你一切的工， 但第七日是向耶和华你神当守的安息日。这一日你和你的儿女、仆婢、牲畜，并你城里寄居的客旅，无论何工都不可作，因为六日之内，耶和华造天、地、海和其中的万物，第七日便安息，所以耶和华赐福与安息日，定为圣日。\n\n五、当孝敬父母，使你的日子在耶和华你神所赐你的地上得以长久。\n\n六、不可杀人。\n\n七、不可奸淫。\n\n八、不可偷盗。\n\n九、不可作假见证陷害人。\n\n十、不可贪恋人的房屋；也不可贪恋人的妻子、仆婢、牛驴，并他一切所有的。” （1）\n\n（1）出20:1-17; 申5:6-21\n\n93．问：这些诫命是如何划分的？ 答：分为两部分：第一部分教导我们对神的责任；第二部分教导我们对邻舍的责任 （1）。\n\n（1）太22:37-40\n\n94．问：神在第一条诫命中吩咐了什么？ 答：为了我本人得救赎，我当躲避、逃离一切偶像崇拜（1）、巫术、邪术、迷信 （2），以及向圣徒或其他受造物求告（3）等事。此外，我当正确地认识独一的真神（4），唯独信靠他 （5），以谦卑 （6）和忍耐（7）的心顺服他，盼望唯独从他得着一切的好处 （8），并且尽心地爱他（9）、敬畏他 （10）、荣耀他 （11）。简而言之，我宁愿舍弃万有，也不做任何违背他旨意的事 （12）。\n\n（1）林前6:9-10,10:5-14; 约壹5:21 （2）利19:31; 申18:9-12 （3）太4:10; 启19:10,22:8-9 （4）约17:3 （5）耶17:5,7 （6）彼前5:5-6 （7）罗5:3,4:1; 林前10:10; 腓2:14; 西1:11; 来10:36 （8）诗104:27-28; 赛45:7; 雅1:17 （9）申6:5; (太22:37) （10）申6:2; 诗111:10; 箴1:7,9:10; 太10:28; 彼前1:17 （11）申6:13; (太4:10); 申10:20 （12）太5:29-30,10:37-39; 徒5:29\n\n95．问：什么是拜偶像？ 答：拜偶像就是信靠所拥有的或所臆造的，而不信靠或不单信靠藉着圣言启示自己的独一真神 （1）。\n\n（1）代上16:26; 加4:8-9; 弗5:5; 腓3:19\n\n主日35\n\n96．问：神在第二条诫命中吩咐了什么？ 答：我们不可用任何形式制作神的形像 （1），也不可用任何他在圣经中没有吩咐过的方式来敬拜他（2）。\n\n（1）申4:15-19; 赛40:18-25; 徒17:29; 罗1:23 （2）利10:1-7; 申12:30; 撒上15:22-23; 太15:9; 约4:23-24\n\n97. 问：那么，我们绝不可以制作神的任何形像吗？ 答：神的形像是不可以、也不可能以任何形式被绘制出来的。受造物可以被描绘，但是神禁止我们以膜拜为目的来制作或拥有他们的像，也禁止我们藉着拜他们来侍奉神（1）。\n\n（1）出34:13-14,17; 民33:52; 王下18:4-5; 赛40:25\n\n98.问：难道这些像放在教堂里用以教导平信徒也不允许吗？ 答：不允许，因为我们不应自以为比神有智慧，他不要他的百姓受教于哑巴偶像 （1），而要受教于对圣言的活泼宣讲（2）。\n\n（1）耶10:8; 哈2:18-20 （2）罗10:14-15,17; 提后3:16-17; 彼后1:19\n\n主日36\n\n99．问：神在第三条诫命中吩咐了什么？ 答：我们不可用咒诅 （1）、起假誓 （2）或起不必要的誓（3）来亵渎神或妄称神的名；面对这些事时，也不可保持缄默、袖手旁观 （4），以免使自己在这可怕的罪上有份。相反，我们必须单单用敬畏的心来称呼神的圣名（5），以至于真正认他 （6）、求告他 （7），并用我们一切的言行荣耀他的名 (8）。\n\n（1）利24:10-17 （2）利19:12 （3）太5:37; 雅5:12 （4）利5:1; 箴29:24 （5）诗99:1-5; 赛45:23; 耶4:2 （6）太10:32-33; 罗10:9-10 （7）诗50:14-15; 提前2:8 （8）罗2:24; 西3:17; 提前6:1\n\n100．问：以起誓和咒诅来亵渎神的名真是如此严重的罪，以至于神的忿怒也降在那些不尽力拦阻和制止该罪的人身上吗？ 答：确实如此 （1）！因为没有什么罪比亵渎神的名更严重、更激起神的忿怒。这就是为什么他命令要处死犯这罪的人（2）。\n\n（1）利5:1 （2）利24:16\n\n主日37\n\n101．问：那么，我们可以用敬虔的态度奉神的名起誓吗？ 答：可以。当政府要求公民起誓时，或确有必要起誓，其目的是维护真理、促进诚信，使神得荣耀、邻舍受益时，我们可以这样起誓。这种起誓是有圣经依据的 （1）。正因如此，旧约和新约里的圣徒都曾正当地起过誓 （2）。\n\n（1）申6:13,10:20; 耶4:1-2; 来6:16 （2）创21:24;31:53; 书9:15; 撒上24:22; 王上1:29-30; 罗 1:9; 林后1:23\n\n102．问：我们可以指着圣徒或其他受造物起誓吗？ 答：不可以。因为正当的起誓乃是呼求神的名，因唯有他鉴察人心，为真理作见证，并惩罚起假誓的人 （1）。没有任何受造物配得如此尊荣 （2）。\n\n（1）罗9:1; 林后1:23 （2）太5:34-37,23:16-22; 雅5:12\n\n主日38\n\n103．问：神在第四条诫命中吩咐了什么？\n\n答：第一，当坚持宣讲福音、坚持办学 （1）；特别在安息日，我当积极去神的教会 （2）聆听神的话语 （3），参加圣礼（4），与会众一同求告与我们立约的神 （5），并捐钱周济穷人 （6）。第二，我一生的年日都不要做恶事 ，让神藉着他的圣灵在我里面做工，使我今生就开始品尝永恒的安息 （7）。\n\n（1）申6:4-9,20-25; 林前9:13-14; 提后2:2,3:13-17; 多1:5 （2）申12:5-12; 诗40:9-10,68:26; 徒2:42-47; 来10:23-25 （3）罗10:14-17; 林前14:26-33; 提前4:13 （4）林前11:23-24 （5）西3:16; 提前2:1 （6）诗50:14; 林前16:2; 林后8;9 （7）赛66:23; 来4:9-11\n\n主日39\n\n104．问：神在第五条诫命中吩咐了什么？ 答：我当对父母和一切在上掌权者表示尊敬、爱戴和忠诚，我当谦卑顺服他们正确的训诲和管教 (1)，也当容忍他们的软弱与缺点 （2），因为我们受他们的管教是神的旨意（3）。\n\n（1）出21:17; 箴1:8,4:1; 罗13:1-2; 弗5:21-22; 6:1-9; 西3:18-4:1 （2）箴20:20,23:22; 彼前2:18 （3）太22:21; 罗13:1-8; 弗6:1-9; 西3:18-21 主日40\n\n105．问：神在第六条诫命中吩咐了什么？ 答：我不可在心思、言语或举止上，更不可在行为上，亲自或假借他人来羞辱、恨恶、伤害或杀害我的邻舍 （1），而当弃绝一切报复之心 （2）。此外，我也不可伤害自己，或鲁莽地自陷于危险之中 （3）。故此，掌权者佩剑也是为了阻止谋杀之事 （4）。\n\n（1）创9:6; 利19:17-18; 太5:21-22; 26:52 （2）箴25:21-22; 太18:35; 罗12:19; 弗4:26 （3）太4:7,26:52; 罗13:11-14 （4）创9:6; 出21:14; 罗13:4\n\n106．问：这条诫命仅仅论及谋杀吗？ 答：神以禁止谋杀的诫命教导我们，他憎恶谋杀的根源，如嫉妒、仇恨、恼怒并报复的心 （1）；他视这一切皆为谋杀（2）。\n\n（1）箴14:30; 罗1:29,12:19; 加5:19-21; 雅1:20; 约壹2:9-11 （2）约壹3:15\n\n107．问：我们只要不这样杀害邻舍就够了吗？ 答：不够。神将嫉妒、仇恨和恼怒定为罪的同时， 还吩咐我们要爱人如己 （1），对人要显出忍耐、和平、温柔、恩慈和友善 （2），尽我们所能使他免受伤害 ，甚至要善待我们的仇敌 （3）。\n\n（1）太7:12; 22:39; 罗12:10 （2）太5:5; 路6:36; 罗12:10,18; 加6:1,2; 弗4:2; 西3:12; 彼前3:8 （3）出23:4-5; 太5:44-45; 罗12:20\n\n主日41\n\n108．问：神在第七条诫命中教导我们什么？ 答：一切淫乱之事皆为神所咒诅 （1）。因此，我们必须从心里憎恶淫乱 （2），无论未婚已婚都要过有贞操、有节制的生活 （3）。\n\n（1）利18:30; 弗5:3-5 （2）犹22-23 （3）林前7:1-9; 帖前4:3-8; 来13:4\n\n109．问：神在这条诫命中只禁止淫乱及类似的可耻之罪吗？ 答：神的旨意是要我们保守自己纯全圣洁，因为我们的身体和灵魂都是圣灵的殿。因此，神禁止一切淫乱的行为、举动、言语、思想和欲望 （1），并一切可能诱使我们淫乱的事（2）。\n\n（1）太5:27-29; 林前6:18-20; 弗5:3-4 （2）林前15:33; 弗5:18\n\n主日42\n\n110．问：神在第八条诫命中禁止什么？ 答：神不但彻底禁止偷窃和抢夺 （1），也禁止诡诈的计谋和手段，例如虚假的度量、欺诈性的交易、伪钞与高利贷（2）；我们也不可以任何方式讹诈邻舍，无论以暴力，还是以强权的方式 （3）。此外，神禁止贪婪 （4）、滥用或浪费他给予的恩赐 （5）。\n\n（1）出22:1; 林前5:9-10,6:9-10 （2）申25:13-16; 诗15:5; 箴11:1; 12:22; 结45:9-12; 路6:35 （3）弥6:9-11; 路3:14; 雅5:1-6 （4）路12:15; 弗5:5 （5）箴21:20,23:20-21; 路16:10-13\n\n111．问：神在这条诫命中对你的要求是什么？ 答：我要尽自己所能增进邻舍的福祉；当按照我愿意人待我的方式去待别人；也当忠心做工，以使自己能帮助有需要的人（1）。\n\n（1）赛58:5-10; 太7:12; 加6:9-10; 弗4:28\n\n主日43\n\n112．问：神在第九条诫命中的要求是什么？ 答：我不可作假见证陷害人或歪曲人的话，不传播流言蜚语或诽谤人，不论断人，也不可未经查问就随同他人轻率地定人的罪 （1）；相反，我要远避一切谎言和欺诈， 视之为魔鬼的作为，是在神忿怒的刑罚之下的（2）。无论在法院，还是在其他任何地方，我都要喜爱真理 （3），诚实地述说和承认真理，又要尽力保护和促进邻舍的荣誉和好名声 （4）。\n\n（1）诗15; 箴19:5,9; 21:28; 太7:1; 路6:37; 罗1:28-32 （2）利19:11-12; 箴12:22; 13:5; 约8:44; 启21:8 （3）林前13:6; 弗4:25 （4）彼前3:8-9,4:8\n\n主日44\n\n113．问：神在第十条诫命中对我们有什么要求？ 答：我们心中丝毫不可有与神的任何一条诫命相违背的心思意念，总要竭尽心力恨恶一切罪恶，喜爱公义 （1）。\n\n（1）诗19:7-14,139:23-24; 罗7:7-8\n\n114．问：那些归信神的人能完全遵守这些诫命吗？ 答：不能。在今生，即使最圣洁的人也只是刚刚开始学着顺服（1）。然而，他们已经立定心志，开始遵照神的所有的诫命而非部分诫命生活 （2）。\n\n（1）传7:20; 罗7:14-15; 林前13:9; 约壹1:8 （2）诗1:1-2; 罗7:22-25; 腓3:12-16\n\n115．问：既然今生没有人能完全遵守这些诫命，神为什么仍要求十诫被严格地宣讲呢？ 答：第一，好叫我们在今生越来越知晓自己的罪性，从而更迫切地寻求在基督里的罪得赦免和公义 （1）。第二，好叫我们一方面求神赐下圣灵的恩典，一方面不断努力按神的形像被更新，直到此生之后达至完全 （2）。\n\n（1）诗32:5; 罗3:19-26,7:7,24-25; 约壹1:9 （2）林前9:24; 腓3:12-14; 约壹3:1-3\n\n祷告\n\n主日45\n\n116．问：为什么祷告对基督徒来说是必不可少的呢？ 答：因为神要求我们感恩，而祷告是感恩中最重要的一部分（1）；另外，神将他的恩典和圣灵只赐给那些不住祈求、满心渴慕神恩赐，并为这些恩赐感谢神的人 （2）。 （1）诗50:14-15; 116:12 -19; 帖前5:16-18 （2）太7:7-8; 路11:9-13\n\n117．问：什么样的祷告才蒙神悦纳和垂听？ 答：第一，我们必须为神所吩咐我们祈求的一切事，真心地呼求那位在圣经中启示自己的独一真神 （1）。第二，我们必须完全知晓自己的需要和愁苦，好叫我们在神的面前谦卑自己 （2）。第三，我们必须坚信，虽然自己不配，但神必因主基督的缘故，垂听我们的祷告，因这是他在圣经里应允我们的 （3）。\n\n（1）诗145:18-20; 约4:22-24; 罗8:26-27; 雅1:5; 约壹5:14-15; 启19:10 （2）代下7:14,20:12; 诗2:11,34:18, 62:8; 赛66:2; 启4 （3）但9:17-19; 太7:8; 约14:13-14,16:23; 罗10:13; 雅1:6\n\n118．问：神吩咐我们向他祈求什么？ 答：他吩咐我们向他祈求身体和灵魂所需的一切 （1），就是我们的主基督在他亲自教训我们的主祷文中所包含的内容。\n\n（1）太6:33; 雅1:17\n\n119．问：什么是主祷文？ 答：“我们在天上的父，愿人都尊你的名为圣。愿你的国降临。愿你的旨意行在地上，如同行在天上。我们日用的饮食，今日赐给我们。免我们的债，如同我们免了人的债。不叫我们遇见试探，救我们脱离凶恶。因为国度、权柄、荣耀，全是你的，直到永远。阿们。” （1）\n\n（1）太6:9-13; 路11:2-4\n\n主日46\n\n120．问：为什么基督吩咐我们称呼神为“我们的 ……父”呢？ 答：为了在我们祷告的一开始就唤起我们对神当存的孩子般的敬畏与信靠 ——这是我们祷告的基础。换言之，神已因着基督的缘故成为我们的父；生身的父尚且不拒绝我们肉身的要求，神就更不会拒绝我们凭信心向他呈上的祈求了（1）。\n\n（1）太7:9-11; 路11:11-13\n\n121．问：这里为什么加上“在天上” 这个词呢？ 答：为的是教导我们不要以属世的眼光看待神属天的尊荣（1），而要期望从他的全能，获得我们身体和灵魂所需的一切（2）。\n\n（1）耶23:23-24; 徒17:24-25 （2）太6:25-34; 罗8:31-32\n\n主日47\n\n122．问：主祷文中的第一个祈求是什么？ 答：“愿人都尊你的名为圣”。换言之，求神首先让我们正确地认识他 （1），并在他一切显其大能、智慧、良善、公义、怜悯和真理的作为中，尊他为圣，荣耀、颂赞他（2）；求神也让我们管理好全身心，即我们的思想、言语和行为，使他的名不因我们被亵渎，而总是受到尊荣和赞美（3）。\n\n（1）耶9:23-24,31:33-34; 太16:17; 约17:3 （2）出34:5-8; 诗145; 耶32:16-20; 路1:46-55,68-75; 罗11:33-36 （3）诗115:1; 太5:16\n\n主日48\n\n123．问：第二个祈求是什么？ 答：“愿你的国降临”。即求神用他的话语和圣灵来管理我们，使我们越来越顺服他 （1）；保守、兴旺他的教会（2）；败坏魔鬼的作为，摧毁凡高抬自己、抵挡神的一切权势，粉粹所有违背他圣言的诡计 （3）。求神行这一切事，直到他完美的国度来到，他在其间作万物之主（4）。\n\n（1）诗119:5,105, 143:10; 太6:33 （2）诗51:18,122:6-9; 太16:18; 徒2:42-47 （3）罗16:20; 约壹3:8 （4）罗8:22-23; 林前15:28; 启22:17,20\n\n主日49\n\n124．问：第三个祈求是什么？ 答：“愿你的旨意行在地上，如同行在天上”。即求神使我们和众人舍弃自己的意愿，毫无怨言地顺服他的旨意，因唯有他的旨意是美善的 （1）；也求神使每个人如同天使般（2）甘心、忠诚地履行神赋予的职分和呼召（3）。\n\n（1）太7:21,16:24-26; 路22:42; 罗12:1-2; 多2:11-12 （2）诗103:20-21 （3）林前7:17-24; 弗6:5-9\n\n主日50\n\n125．问：第四个祈求是什么？ 答：“我们日用的饮食，今日赐给我们”。即求神赐给我们身体所需的一切 （1），叫我们承认他是一切美善的唯一泉源（2）；若没有他的祝福，我们的苦心经营、劳碌以及他所给予的恩赐都不能使我们得益 （3）。所以，求神让我们不再信靠受造之物，而唯独信靠神 （4）。\n\n（1）诗104:27-30; 145:15 -16; 太6:25-34 （2）徒14:17,17:25; 雅1:17 （3）申8:3; 诗37:16,127:1-2; 林前15:58 （4）诗55:22;62;146; 耶17:5-8; 来13:5-6\n\n主日51\n\n126．问：第五个祈求是什么？ 答：“免我们的债，如同我们免了人的债” 。即恳求神因基督宝血的缘故，不将我们的任何过犯和仍留在我们身上的罪恶归给我们这些可怜的罪人 （1），正如我们在自己身上看到他恩典的这一确据，就立定心志，真心地饶恕我们的邻舍 （2）。\n\n（1）诗51:1-7; 143:2; 罗8:1; 约壹2:1-2 （2）太6:14-15,18:21-35\n\n主日52\n\n127．问：第六个祈求是什么？ 答：“不叫我们遇见试探，救我们脱离凶恶”。即我们自身实在软弱，靠自己没有一刻能站立得住 （1)，而且我们的死敌——魔鬼（2）、世界（3）和自身的情欲 （4）不断地攻击我们；所以，求神用圣灵的大能扶持我们、坚固我们，好叫我们在这属灵的争战 （5）中不致为仇敌所胜，而是始终坚定地抵挡仇敌，直到最终我们大获全胜 （6）。\n\n（1）诗103:14-16; 约15:1-5 （2）林后11:14; 弗6:10-13; 彼前5:8 （3）约15:18-21 （4）罗7:23; 加5:17 （5）太10:19-20,26:41; 可13:33; 罗5:3-5 （6）林前10:13; 帖前3:13; 5:23\n\n128．问：主祷文是如何结束的？ 答：“因为国度、权柄、荣耀，全是你的，直到永远”。即我们向神祈求这一切，因为他是我们的王，掌管万有，他不仅愿意，而且也有能力将一切的好处赐给我们 （1）；也因为他的名而非我们的名应得一切的荣耀，直到永远（2）。\n\n（1）罗10:11-13; 彼后2:9 （2）诗115:1; 耶33:8-9; 约14:13\n\n129．问：“阿们”是什么意思？ 答：“阿们” 的意思是 “真的，确实如此”。因为神已垂听我的祷告，这一事实远比我心中的感觉、比我对他听我祷告的渴望更为确实 （1）。\n\n（1）赛65:24; 林后1:20; 提后2:13", "status": "附件阅读版 · 网站逐字核验未完成", "note": "用户提供的《敬拜赞美手册》（2015）印刷页 48–94，清理换行、页码与排版空白；内容含原书经文注释。不是已完成逐字校验的 CCI 网站转录。"}, {"title": "多特信经", "url": "https://ccifellowship.org/books/book-of-praise/confessions/canons-of-dort", "text": "多特信经\n\n中国改革宗教会三项联合信条的第三个信条是《多特信经》，又称为《反对抗辩派的五大点》。《多特信经》在1618-1619年的改革宗多特大会上被采纳。多特大会是一次国际性的大会，与会代表主要来自荷兰改革宗教会，另有二十七位来自其他国家的教会。\n\n多特大会的召开是因为阿米念主义的兴起和蔓延严重干扰了改革宗教会的信仰。荷兰莱顿大学的神学教授阿米念和他的追随者们背离了改革宗信仰，教导他们的“五大点”：神预见有些人会信而拣选他们；耶稣为所有人付上了罪的赎价；人的败坏不是全方位的；神赐恩典，但人可以选择不接受；信徒有失去救恩的可能。多特大会对阿米念所教导的这五点予以驳斥，驳斥的内容记录在《多特信经》中（正是这个原因，《多特信经》又名《反对抗辩派的五大点》）。大会同时阐明了改革宗教导的五大点，即无条件的拣选、特定的救赎、 人的全然败坏、不可抗拒的恩典和圣徒永蒙保守。\n\n《多特信经》的每一项都包括正反两方面的观点，一方面陈述改革宗的正确教义，一方面驳斥阿米念主义的错谬。尽管在结构上它只分为四个部分，因为第三 、第四项被合并成了一项 ，但我们还是说《多特信经》有五项教义，第三个部分通常被称为第三 /四项教义。改革宗教会的所有圣职人员在就职前都必须签署文书 ，认同《多特信经》、《比利时信条》和《海德堡要理问答》这三大联合信条。\n\n第一项教义论神的拣选与弃绝\n\n第一条全人类都该被神定罪\n\n正如使徒保罗所说 ，：“普世的人都伏在神审判之下”（罗3:19），“因为世人都犯了罪，亏缺了神的荣耀”（罗3:23），而“罪的工价乃是死”（罗 6:23），人都在亚当里犯了罪，处在咒诅之下，当受永死 （1）。因此，即使神定意要任凭全人类陷在罪中，处在咒诅之下，并定他们的罪，他也没有对任何人行不义。\n\n（1）罗5:12\n\n第二条神差爱子\n\n然而，“神差他独生子到世间来……神爱我们的心在此就显明了”（约壹 4:9），“叫一切信他的，不至灭亡，反得永生”。（约 3:16）\n\n第三条福音的传讲\n\n为了使人归信，神在他所定的时刻，施恩差派传这大喜信息的使者，到他所预定要听到福音的人中间去（1）。藉着使者的传讲，神呼召世人悔改并信靠被钉十字架的基督（2），因为“人未曾信他，怎能求他呢？未曾听见他，怎能信他呢？没有传道的，怎能听见呢？若没有奉差遣，怎能传道呢？”（罗 10:14-15）\n\n（1）赛52:7 （2）林前1:23-24 第四条两种结局\n\n神的忿怒停留在不信此福音的人身上 （1）。但是，凭真实活泼的信心接受福音，并信救主耶稣的人，就蒙神拯救，脱离他的忿怒，免遭灭亡，并得永生 （2）。\n\n（1）约3:36 （2）可16:16; 罗10:9\n\n第五条不信的缘由与信的源头\n\n与其他诸罪一样，不信的缘由和罪责丝毫不在于神，而在于人 （1）。然而， 信耶稣基督以及藉他而得的救恩却是神白白的恩典，因为以弗所书第 2章第8节说：“你们得救是本乎恩，也因着信。这并不是出于自己，乃是神所赐的。”腓立比书第 1章第29节也说：“因为你们蒙恩……得以信服基督。”\n\n（1）来4:6\n\n第六条神永恒的定旨\n\n神适时地赐信心给一部分人而不给其他人，是出于他永恒的定旨 （1）。这是自古以来就显明这些事的主所说的（2）。主又照着他旨意所预定的，随己意行做万事（参弗1:11）。对于选民，无论他们的心多么刚硬，神都按着这定旨施恩软化他们的心，使他们回转归信；然而，对于不蒙拣选的人，神就按着公义任凭他们邪恶与刚硬。这向我们显明，虽然人都该被定罪，但是，神以他的恩慈和公义将他的选民与不蒙拣选的人截然分开，这就是神在圣经中向我们启示的拣选与弃绝的定旨。尽管人顽梗悖逆、不洁、易变，歪曲神的定旨从而自取败坏，但这定旨给属神、敬畏神的人带来极大的安慰。\n\n（1）徒13:48 （2）彼前2:8\n\n第七条拣选的定义\n\n拣选是神不变的旨意。在创立世界以先 （1），神就根据他的主权和美意，在基督里，从全人类，即因人自己的过错而堕落犯罪，失去原初的完全，从而招致灭亡的人中，拣选了特定数量的特定的人，使他们得救。这些人得救完全是靠着神的恩典，因他们既不比其他人好，也不更配得神的恩典；他们与不蒙拣选的人一样活在愁苦之中。神也在永恒中指派基督作所有选民的中保与元首，并得救的根基。因此，他定意将他所要拯救的人交与基督，并以他的话语，藉着圣灵，有效地呼召、引领他们进入与基督的相交中；神也定意赐他们在基督里的真信心，使他们称义并成圣；在以大能保守他们连于基督之后 （2），神最终要使他们得荣耀，以彰显他的慈爱，也因自己荣耀、丰富的恩典而得着称颂 （3）。正如经上所记：“就如神从创立世界以前，在基督里拣选了我们，使我们在他面前成为圣洁，无有瑕疵；又因爱我们，就按着自己意旨所喜悦的，预定我们藉着耶稣基督得儿子的名分，使他荣耀的恩典得着称赞。这恩典是他在爱子里所赐给我们的。”（弗1:4-6）经上又说：“预先所定下的人又召他们来；所召来的人又称他们为义；所称为义的人又叫他们得荣耀。”（罗8:30）（4）\n\n（1）弗1:4,11 （2）约17:2 （3）约17:12 （4）约6:37,44; 约17:24\n\n第八条拣选定旨的唯一性\n\n拣选只有一种。 无论是在旧约之下还是在新约之下，得救之人的拣选定旨都是同一个， 没有多个 ，因为圣经宣告说，神旨意的美意、目的和计划只有一个 （1）。\n\n按此旨意，他已在永恒中拣选我们得恩典、得荣耀，也预定我们得拯救 、走他为我们预备的得救之道 （2）。\n\n（1）申7:7,9:6; 弗1:4-5 （2）弗2:10\n\n第九条拣选不是基于神预见我们会信\n\n人不是因神预见他会信，又会因信生出顺服、圣洁和其他的好品性，符合神的条件而蒙神拣选的 ，而是因蒙了神的拣选而信，又从信生出顺服、圣洁等好品性的。因此，拣选是所有与救恩相关的福祉的源头 ；人蒙了神的拣选才有信心、圣洁和其他源于得救的恩典，也才有蒙选的最终果效——永生（1）。关于这一点，使徒保罗教导说：“神……在基督里拣选了我们，使我们在他面前成为圣洁，无有瑕疵。”（弗 1:4）\n\n（1）罗8:30\n\n第十条拣选出于神的美意\n\n神唯独出于他的美意施恩拣选。这美意不在于神从所有可能的条件中选出人的某些品质和行为，作为得救的条件，而在于他从所有罪人中拣选了特定的一些人归自己所有。正如经上所记 ，“双子还没有生下来，善恶还没有作出来”（罗 9:11-13），神就对利百加说：“将来大的要服侍小的。”（创 25:23）经上又说 ，“我爱雅各，却恶以扫”（玛 1:2-3）；“凡预定得永生的人都信了”（徒13:48）。\n\n第十一条拣选的不变性\n\n神是全智、不变、全知、全能的，因此，他的拣选既不可能被撤消或重选，也不可能被变更或作废；选民不可能被丢弃 （1），其数目也不会减少 （2）。\n\n（1）约6:37 （2）约10:28\n\n第十二条确信蒙拣选\n\n虽然选民各自处于不同的阶段 ，各人的基督身量也大小不一，但神在所定的时候会让他们确信自己蒙了永恒不变的拣选而得救恩。然而，选民不是通过好奇地窥探神隐秘之事（1），而是通过对自身的观察 （2）才有这样的确信的。他们在属灵的、圣洁的喜乐中，从自己身上看到圣经所指的、由蒙拣选而生的经久不衰的果子，如基督里的真信心、对神孩童般的敬畏、真心为罪忧伤 （3）、饥渴慕义（4）等等。\n\n（1）申29:29; 林前2:10-11 （2）林后13:5 （3）林后7:10 （4）太5:6\n\n第十三条确信蒙拣选的重要性\n\n神的儿女意识到自己蒙了拣选，又确信了这一点，就更应该每日在神面前谦卑自己，赞美神对他的洪恩，洁净自己（1），热切地爱他，以回应他对我们的大爱（神先爱我们） （2）。因此，这拣选的教义本身，以及对这教义的思考绝不会叫选民不勤于遵守神的命令，也不会让他们误认为自己进了保险箱而有恃无恐。以神公正的审判来看，这些事通常发生在轻率地认为自己已得到蒙选之恩，或空谈、妄谈这恩典，却又不行选民之道的人身上。\n\n（1）约壹3:3 （2）约壹4:19\n\n第十四条如何教导拣选的教义\n\n按着神极其智慧的旨意，拣选教义被旧约和新约时代的众先知、基督自己和众使徒所传讲，而后又被写入圣经。拣选教义是为教会准备的，因此，今天的教会也应该适时适地地按神的旨意教导此教义 （1）；教导时要有明辨之心，有恭敬、敬虔的态度 ，而不是好奇地窥探至高者的隐秘作为；教导的目的是使神至圣的名得着荣耀，他的子民得着活泼持续的安慰 （2）。\n\n（1）徒20:27 （2）伯36:23-26; 罗11:33;12:3; 林前4:6\n\n第十五条圣经中所描述的弃绝圣经向我们阐明了这一永恒不变的、人所不配得的拣选。它特别作进一步宣告说，并非所有人都蒙了拣选；有些人没有被拣选，换言之，神有意不选他们 （1）。神出于他至高的主权和极公义、无可指摘、不变的美意，预定任凭后者留在因人自己的过错而陷入的愁苦中 （2），不将得救的信心与归信的恩典赐给他们。按着神的定旨，为了神的公义得以彰显，这些各行其道 （3）、落在神公义的审判之下的人最终将因其不信和其他诸罪受到永远的定罪和刑罚。这就是有关弃绝的定旨，它绝不会使神成为罪恶之源（这种念头都是亵渎神的），只会宣告他是可畏的、无可指摘的、公义的审判者与施报应的神。\n\n（1）罗9:22 （2）彼前2:8 （3）徒14:16\n\n第十六条对弃绝教义的回应\n\n有些人还没有清楚地觉察到自己在基督里有活泼的信心（1）、内心的确信、良心的平安，也没有感觉到自己热切地追求孩子般的顺服，或靠基督以神为乐 （2），但是，他们用上了神应许在蒙选之人里面生发上述这一切的施恩方法。这样的人不应该一听到神的弃绝就倍感惊慌，也不该将自己列入被弃者之列，倒要殷勤使用这些方法，热切盼望得更丰富的恩典，以敬畏、谦卑的心等候确信自己蒙拣选这一时刻的到来。另有一些人真心渴望归向神，单单讨神的喜悦，并愿脱离这取死的身体 （3），可是他们在敬虔和信心的道路上并不能达到预期目标。这样的人更不该因着这弃绝教义而惊恐，因为慈爱的神已经应许说，将残的灯火他不吹灭，压伤的芦苇他不折断 （4）。然而，还有一些人，他们漠视神和救主耶稣基督，完全活在世上的思虑和钱财的迷惑之中 （5）。如果他们不诚心归向神，那么神弃绝的教义对他们就真是可怕的 （6）。\n\n（1）雅2:26 （2）林后1:12; 罗5:11 （3）腓3:3; 罗7:24 （4）赛42:3; 太12:20 （5）太13:22 （6）来12:29\n\n第十七条死于婴幼期的信徒儿女\n\n我们须根据神的话语来辨别神的旨意。神宣告说，信徒的儿女是圣洁的，不是因为他们的本性圣洁，而是因为他们与父母共同承受恩典之约 （1）。因此，敬虔的父母不该怀疑在婴幼期被神召回而离世的儿女已蒙了拣选、得了救恩（2）。\n\n（1）创17:7; 赛59:21 （2）徒2:39; 林前7:14\n\n第十八条不是反对，而是赞美\n\n对于那些对神施恩拣选一些人，却按公义严厉地弃绝另外一些人这一教义持反对意见的人 （1）， 我们要用使徒保罗的话回应他们：“你这个人哪，你是谁，竟敢向神强嘴呢？”（罗 9:20）又用我们救主的话说：“我的东西难道不可随我的意思用吗？” （太20:15）\n\n因此，我们以敬畏的心，赞美这奇妙的事，并用使徒保罗的话来赞叹：“深哉，神丰富的智慧和知识！他的判断何其难测！他的踪迹何其难寻！谁知道主的心？谁作过他的谋士呢？谁是先给了他，使他后来偿还呢？因为万有都是本于他，倚靠他，归于他。愿荣耀归给他，直到永远。阿们！”（罗 11:33-36）\n\n（1）太20:15; 伯40:1-5\n\n错谬反驳\n\n在解释了关于神的拣选与弃绝的正确教义后，联盟总会会议驳斥了以下错谬：\n\n错谬一：神的旨意是拯救那些会信且会持守信仰、顺服神的人。这是神拣选人得救的全部和完整的旨意。除此以外，圣经中没有任何有关这一定旨的启示了。\n\n驳斥：这个错谬是具有欺骗性的，是与圣经教导相抵触的。圣经的确宣告神拯救那些会信他的人，就是神从永恒中拣选的人。神在特定的时间将在基督里的信心与持守所信之道的毅力赐给他的选民 ，而非其他人。经上记着说，“你从世上赐给我的人，我已将你的名显明与他们 ”（约17:6）；又说，“凡预定得永生的人都信了 ”（徒13:48）；还说，“就如神从创立世界以前，在基督里拣选了我们，使我们在他面前成为圣洁，无有瑕疵”（弗1:4）。\n\n错谬二：神的拣选有几种不同的类别：一种是一般的（general），没有特定对象的（ indefinite ）；另一种是特殊的（ particular ），有特定对象的（ definite ）。后者又分为两种：不完全拣选（ incomplete election ）与完全拣选（ complete election ）。“不完全拣选”是指神对这个特定对象的拣选是可撤消的、非绝对的、有条件的；“完全拣选”是指神对这个特定对象的拣选是不会撤销的、绝对的、无条件的。换言之，神使一些人蒙拣选得信心（ election unto faith ），而另一些人蒙拣选得救恩（election unto salvation ）。因此，有些人蒙拣选因信而得称为义，但并不一定得到救恩。\n\n驳斥：这些说法都是人臆造的，没有任何圣经依据。它们使拣选的教义遭到严重的践踏，救恩的金链被人为扯断。经上说：“预先所定下的人又召他们来；所召来的人又称他们为义；所称为义的人又叫他们得荣耀 。”（罗8:30）\n\n错谬三：关于神拣选的美意与目的，圣经并没有说神拣选某些特定的人而非其他人，而是说，神不按其他任何条件（如遵守律法）拣选人，只看一个人会不会有信这一行为。这行为本身虽没有功德，也只是由信心生出的不完全的顺服，但它却是得救的条件。因着神的恩典，这信的行为被算为完全的顺服，配得永生作为赏赐。\n\n驳斥：这种错谬抢夺了神的美意以及基督的功德所带来的果效，它不仅使人背离称义完全是神的恩典这一真理，也让人觉得圣经复杂难懂。这种教导与使徒保罗的话相抵触。保罗说：“神救了我们，以圣召召我们，不是按我们的行为，乃是按他的旨意和恩典；这恩典是万古之先在基督耶稣里赐给我们的。”（提后 1:9）\n\n错谬四： 一个人蒙拣选得信心的条件是他善用本性之余光，敬虔、谦卑、温柔，适合承受永生。\n\n驳斥：假如这是真的，那么拣选就取决于人了。这很有伯拉纠教导的味道，与使徒保罗的教导不符，因为保罗说：“我们从前也都在他们中间，放纵肉体的私欲，随着肉体和心中所喜好的去行，本为可怒之子，和别人一样。然而神既有丰富的怜悯，因他爱我们的大爱，当我们死在过犯中的时候，便叫我们与基督一同活过来（你们得救是本乎恩）。他又叫我们与基督耶稣一同复活，一同坐在天上，要将他极丰富的恩典，就是他在基督耶稣里向我们所施的恩慈，显明给后来的世代看。你们得救是本乎恩，也因着信。这并不是出于自己，乃是神所赐的；也不是出于行为，免得有人自夸。”（弗 2:3-9）\n\n错谬五：对特定对象的不完全、非绝对的拣选是基于神预见他们有信心、会悔改，圣洁、敬虔，或许刚刚开始，或许已持续了一段时间；而完全的、绝对的拣选是基于神预见他们会在信心、悔改、圣洁与敬虔上持守到底。他们的持守符合了承受福音的条件，因为这一点， 蒙拣选的人比未蒙选的人更配得救恩。因此，信心、由信生出的顺服、圣洁、敬虔与持守信仰都不是因蒙了不变的拣选要在永恒中得荣耀而结出的果子，而是蒙拣选的原因和必要条件，神正是预见一些人会努力满足这样的先决条件才完全拣选他们的。\n\n驳斥：这种说法是错误的，是与整本圣经背道而驰的。圣经不断将以下话语刻在我们心版上：拣选 “不在乎人的行为，乃在乎召人的主”（罗 9:11）； “凡预定得永生的人都信了”（徒 13:48）；“就如神从创立世界以前，在基督里拣选了我们，使我们在他面前成为圣洁”（弗1:4）；“不是你们拣选了我，是我拣选了你们”（约15:16）；“既是出于恩典，就不在乎行为”（罗 11:6）； “不是我们爱神，乃是神爱我们，差他的儿子为我们的罪作了挽回祭，这就是爱了”（约壹 4:10）。\n\n错谬六：蒙拣选得救恩并非都是不变的。有些人虽然按神的定旨蒙了拣选，但仍然会灭亡，而且是永远的灭亡。\n\n驳斥：这种说法犯了严重的错误，它把神说成是会改变的，使信徒不能从神拣选的不变性中得安慰；它也是与圣经相抵触的，因为圣经上说：（一）蒙拣选之人不会被迷惑；（二）凡父所赐的，基督一个也不会失落（见约6:39）；（三） 神使他所预定、所召、所称为义的人得荣耀（见罗 8:30）。\n\n错谬七：除非拣选是可变的、不确定的，否则蒙了不变的拣选要在永恒中得荣耀的人在今生就结不出蒙选的果子，也不知道、不确信自己已蒙此拣选。\n\n驳斥：说神不变的拣选具有不确定性不仅是十分荒谬的，也是与真信徒的经历不相符的。由于真信徒清楚地意识到自己蒙拣选，所以，他们与使徒保罗一同欢喜快乐，赞美神的这一恩典（见弗 1）；他们也与基督的门徒一同欢喜，因为他们的名记录在天上（路 10:20）。当信徒喊着说 “谁能控告神所拣选的人呢？” (罗8:33)的时候，他们是在用自己已蒙拣选这一事实去抵挡魔鬼射来的燃烧着的箭。\n\n错谬八：神既没有因自己的公义而索性定意将任何人留在亚当的堕落所带来的罪和咒诅之中，也没有在赐归信所需的恩典时遗漏任何人。\n\n驳斥：圣经上清楚地写道：“神要怜悯谁，就怜悯谁；要叫谁刚硬，就叫谁刚硬”（罗 9:18）；又宣告说 ，“因为天国的奥秘，只叫你们知道，不叫他们知道”（太13:11）；圣经还记着：“耶稣说：’父啊，天地的主，我感谢你！因为你将这些事，向聪明通达人就藏起来，向婴孩就显出来。父啊，是的，因为你的美意本是如此。”（太11:25-26）\n\n错谬九：神将福音传给一些人而非其他人，这不完全是因为神的美意如此，也是因为他们比那些人更好 、更配得着福音。\n\n驳斥：摩西反对这种观点，他对以色列说：“看哪，天和天上的天，地和地上所有的，都属耶和华你的神。耶和华但喜悦你的列祖，爱他们，从万民中拣选他们的后裔，就是你们，像今日一样。”（申 10:14-15）；基督也说：“哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能，若行在推罗、西顿，他们早已披麻蒙灰悔改了。”（ 太11:21）\n\n第二项教义论基督的死和人藉此而得的救赎\n\n第一条神的公义所要求的刑罚\n\n神不仅极其仁慈，也极其公义。正如他自己在圣经中所启示的那样（ 1），按着神公义的要求，我们当为冒犯他无限的威严而受刑罚（ 2）。 我们的身体和灵魂不但要受暂时的刑罚， 也要受永远的刑罚；除非神的公义得到满足，否则，我们无法逃脱这样的刑罚。\n\n（1）出34:6-7 （2）罗5:16; 加3:10\n\n第二条基督满足了神的公义\n\n虽然我们自己不能满足神的公义，也不能救自己脱离神的忿怒，但是，神以他无限的仁慈，赐下他的独生爱子作我们的中保（ 1），使他为我们、又替我们成为罪（ 2）和在十字架上的咒诅（ 3），从而替我们满足了神的公义。\n\n（1）约3:16; 罗5:8 （2）林后5:21 （3）加3:13\n\n第三条基督之死有无限价值\n\n神儿子的死是唯一的、最完美的赎罪祭和赎价（ 1），具有无限的价值，足以补赎普天下人所犯的一切罪（ 2）。\n\n（1）来9:26,28; 10:14 （2）约壹2:2\n\n第四条基督之死无价的原因\n\n基督之死无价是因为甘愿受死的那位不仅仅是一位真正的人、完全圣洁的人（ 1），也是神的独生爱子（ 2）， 与圣父和圣灵同有永恒和无限的本质（这些都是作我们救主的必要条件）；此外，基督之死无价还因为他担当了我们犯罪后本该承受的神的忿怒和咒诅（ 3）。\n\n（1）来4:15,7:26 （2）约壹4:9 （3）太27:46\n\n第五条福音的普世宣告\n\n福音的应许乃是：凡信被钉死在十字架上的基督的人都不至灭亡，反得永生（ 1）。按神的美意，这应许应当与神要罪人悔改归信的吩咐一同不加分别地对万国万民（2），即普世的人宣讲（ 3）。\n\n（1）约3:16 （2）林前1:23; 太28:19 (3) 徒2:38,16:31\n\n第六条为何有人不信基督\n\n然而，许多人蒙福音所召，却不悔改，也不信基督，反倒在不信中灭亡（ 1），这不是因为基督在十字架上所献的祭有什么缺陷或不足，而是因为他们自己的过错。\n\n（1）太22:14; 诗95:11; 来4:6\n\n第七条为何有人信基督\n\n真心信基督，且藉着基督的死脱离罪，从灭亡中得蒙拯救的人得到此益处，是单单因为神的恩典；这恩典是神在基督里，从永恒中赐予他们的（ 1）。其实，神并不欠任何人恩典（ 2）。\n\n（1）林后5:18 （2）弗2:8-9\n\n第八条基督之死的果效\n\n神至高主权的定旨和恩慈的旨意与目的，就是要他独生子极其宝贵的死所带来的赐生命、施救赎的果效临到所有的选民（ 1），将称义的信心唯独赐给他们，并藉此使他们必得拯救（ 2）。这意味着，神定意叫基督藉着十字架上所流的宝血坚立新约（ 3），有效地从各民、各族、各国、说各种语言的人中（ 4）拯救那些（而且只有那些）从永恒中就蒙拣选得救的人，就是圣父赐给基督的那些人；父神也定意叫基督将他藉着自己的死为他们获得的信心（5），以及圣灵其他的得救恩赐都赐给他的选民；又叫他用其宝血洗除他们所有的罪（ 6），无论这罪是原罪还是实际的罪，是信之前还是信之后所犯的罪；父神还叫基督信实地保守他们到底（ 7），最终在荣耀中将他们献给自己，无瑕无疵（ 8）。\n\n（1）约17:9 （2）弗5:25-27 （3）路22:20; 来8:6 （4）启5:9 （5）腓1:29 （6）约壹1:7 （7）约10:28 （8）弗5:27\n\n第九条父神定旨的成全\n\n这一定旨是出于神对选民永远的爱；从创世之初直至今日，神一直以大能使之得以成全，并会继续成全在选民身上，阴间一切的权柄对此定旨的阻挠都是枉然的（ 1）。及至时候满足，选民将被召聚成为一体（ 2）；世上始终会有教会 ——她由信徒组成（ 3），以基督的宝血为根基。此教会坚贞不渝地爱她的救主，忠心地服侍他（救主是新郎，在十字架上为他的新妇舍命）（ 4），并颂赞他，从今时直到永远。\n\n（1）太16:18 （2）约11:52 （3）王上19:18 （4）弗5:25\n\n错谬反驳\n\n在解释了关于基督的死和人藉此而得救赎的正确教义后，联盟总会会议驳斥了以下错谬：\n\n错谬一：父神已命定他的儿子死在十字架上，但他并没有明确地定旨基督具体要拯救哪些人。即使基督藉着死所成就的救恩没有被实际地运用到任何人身上，它也是必要的、有益的、宝贵的，是完整的、完美无缺的。\n\n驳斥：这种说法藐视了父神的智慧与耶稣的功德，是与圣经不符的。因为我们的救主耶稣曾说过：“我为羊舍命，我也认识他们”（约 10:15，27）；关于救主，先知以赛亚说：“耶和华以他为赎罪祭。他必看见后裔，并且延长年日，耶和华所喜悦的事必在他手中亨通 ”（赛 53:10）；最后，这种说法也与大公教会的相关信条相抵触。\n\n错谬二：基督受死的目的不在于藉着他的宝血坚立恩典之新约，而只在于为父神再获与人立约的权利，无论是恩典之约还是行为之约。\n\n驳斥：这种说法与圣经相抵触，因为圣经教导说：基督已成为更美之约的中保（见来 7:22），这约就是藉着基督的死所立的新约（见来 9:15）；只有当基督受了死，这约才有效力（见来 9:17）。\n\n错谬三：基督藉着他的补赎并没有实际地为任何人赢得救恩，也没有为人赢得使之有效地做成自己救恩的信心。基督只是为父神获得了以新的方式与人交往的权柄和完美的意愿，好让父按他的意愿开出新的条件。然而，满足这些条件靠的是人的自由意志。因此，没有人满足这些条件和众人都满足这些条件的可能性都存在。\n\n驳斥：教导这种错谬的人太轻视基督的受死，根本不承认基督之死所带来的最重要的果效与益处。他们将伯拉纠主义的错谬从地狱中召回来。\n\n错谬四：父神藉着中保基督的受死与人所立的新的恩典之约不在于我们因信基督的功德而在神面前称义并得救，而在于这样一个事实：神已不再要求人要完全顺服律法，而是将信心和由信心生出的不完全的顺服算为完全顺服律法，并且恩慈地认定这样的信和顺服配得永生作为奖赏。\n\n驳斥：这教义与圣经教导相违背。圣经说：“如今却蒙神的恩典，因基督耶稣的救赎，就白白地称义。神设立耶稣作挽回祭，是凭着耶稣的血，藉着人的信。”（罗3:24-25）教导这种错谬的人，与不敬畏神的苏西尼派（Socinus）一样，在关于人在神面前称义的方面，都宣扬一种怪异的新方法，而这种新方法是与大公教会的共识不符的。\n\n错谬五：所有人都被神接纳，可以与神和好，进入恩典之约。所以，没有人应该因原罪而被定罪，也没有人会为此而被定罪；所有人都脱离了原罪的罪疚。\n\n驳斥：这种观点与圣经相冲突，因为圣经说，“我们本为可怒之子”（弗 2:3）。\n\n错谬六：就神而言，他愿意将基督受死所带来的益处平等地赐与所有人。然而，有些人得到了赦罪之恩和永生，有些人却没有得到。这种根本性差别是在于人的自由意志（神赐恩典时虽然一视同仁，但是否把神的恩典应用到自己身上取决于人的自由意志），而不在于神特别的怜悯，就是运行在他们里面、使他们（而非其他人）将神的恩典应用到自己身上的那种怜悯。\n\n驳斥：教导这种错谬的人滥用 “获得救恩”与“应用救恩”之间的区别，迷惑那些不谨慎、思想不够成熟的人。他们看似在有条有理地阐述它们的区别，其实是企图将伯拉纠主义错谬的毒素逐渐灌输给人。\n\n错谬七：基督不可能死，也不需要死，更没有为神最深爱的、蒙拣选得永生的人而死，因为他们不需要基督的死。\n\n驳斥：这种教义与使徒保罗的教导相抵触，因为保罗说：“他（基督）是爱我，为我舍己。”（加 2:20）；又说：“谁能控告神所拣选的人呢？有神称他们为义了。谁能定他们的罪呢？有基督耶稣已经死了。”（罗 8:33-34）这就是说，基督为他们死；救主也亲自确告我们，“我为羊舍命”（约 10:15）；又说： “你们要彼此相爱，像我爱你们一样， 这就是我的命令。人为朋友舍命，人的爱心没有比这个大的 。”（约 15:12-13）\n\n第三、四项教义论人的败坏、向神归正及其方法\n\n第一条堕落带来的后果\n\n起初，人是照着神的形像造的，悟性中具备关于创造主和一切属灵之事的完备的真知识；他的心思和意念正直，情感纯洁。因此，人曾经是完全圣洁的（ 1）。但是，在魔鬼的煽惑下，人以他的自由意志背叛了神，把自己这些极好的恩赐都剥夺了（ 2）；同时，他使自己的悟性有了盲区、可怕的昏昧、虚妄的思想以及判断上的错谬， 使自己的心思和意念邪恶、叛逆和顽固，又使自己在情感上不洁（3）。\n\n（1）创1:26-27 （2）创3:1-7 （3）弗4:17-19\n\n第二条败坏的传播\n\n人堕落后变为败坏，败坏的父亲又生出败坏的儿女（1），就这样，败坏从亚当传给了除基督之外（ 2）的所有后裔（ 3）。这不是出于古时伯拉纠派所说的效仿，而是出于堕落本性的遗传，是神公义的审判。\n\n（1）伯14:4; 诗 51:5 （2）来4:15 （3）罗5:12\n\n第三条人的全然无能\n\n因此，所有的人都是在罪中成孕而生的，本为可怒之子，不能行出任何善事以拯救自己，反而倾向于作恶，死在罪中，成为罪的奴仆（ 1）。若没有圣灵使人重生的恩典（2），人既没有意愿，也没有能力转向神并改邪归正，甚至连预备自己归正的意愿和能力也没有。\n\n（1）弗2:1,3; 约8:34; 罗6:16-17 （2）约3:3-6; 多3:5\n\n第四条罪人本性中余光的不足\n\n可以肯定，人在堕落之后，本性中仍有一些余光，藉此余光，人对神（ 1）、对自然事物、对区分善恶仍有一些概念，对美德和外在的好行为也能表现出一些尊重（2）。然而，罪人本性中的余光远不足以使人认识神救赎的道理，也不能使人真正归信，因此，他不会在自然和民事上善用这光。实际上，无论这光是什么，人已经以各种方式全面地污染了它，又以自身的邪恶压制了它。人这样做的结果是使自己的罪在神面前无可推诿（ 3）。\n\n（1）罗1:19-20 （2）罗2:14-15 （3）罗1:18, 20\n\n第五条律法的不足\n\n人本性中余光的不足也使人不能够完全遵守十诫，即神藉着摩西特意赐给犹太人的律法。虽然律法显明了人罪恶重大，并使人越来越知罪，但是，它既没有指出救赎的方法，也没有给人脱离愁苦的能力；律法因肉体的软弱而有所不能行，就将人留在了咒诅之下。因此，人不能通过守律法而获得救恩（ 1）。\n\n（1）罗3:19-20,7:10,13; 罗8:3; 林后3:6-7\n\n第六条人需要福音\n\n因此，神以圣灵的大能，藉着他的话语，也就是那使人与神和好的事工（ 1），成就了人本性中的余光和律法都不能行的事。这与神和好的事工就是有关弥赛亚的福音，神乐意藉着它拯救在旧约和新约之下的一切信徒（ 2）。\n\n（1）林后5:18-19 （2）林前1:21\n\n第七条为何福音只给了一些人，却不给其他人\n\n神旨意的奥秘在旧约时代只显明给了少数人，但在新约时代，却不分种族地显明给了更多的人（ 1）。这样安排的原因不在于一些人比其他人更配得神的恩典，也不在于他们更善用本性中的余光，而是因为神主权的美意和人不配得的神的大爱（ 2）。因此，我们这些本该遭受刑罚，却得了不配得之洪恩的人，应当以谦卑、感恩的心（ 3）承认这恩典。 至于那些没有得此恩典的人 ，我们应该像使徒约翰一样，赞美神所行的审判严厉而又公义（ 4），决不应该好奇地窥探隐秘之事（ 5）。\n\n（1）弗1:9,2:14; 西3:11 （2）罗2:11; 太11:26 （3）罗11:22-23 （4）启16:7 （5）申29:29\n\n第八条福音诚挚的呼召\n\n凡蒙福音所召的人，都是蒙了诚挚的呼召（ 1），因为神用他的话语真诚、恳切地启示了他所喜悦的，即一切蒙召的都应来到他面前（ 2）。此外，他诚挚地应许将永生和灵魂的安息赐给所有到他面前且信他的人（ 3）。\n\n（1）赛55:1; 太22:4 （2）启22:17 （3）约6:37; 太11:28-29\n\n第九条为何有人蒙召却没有来到神的面前\n\n许多人藉着福音事工蒙召，却没有来到神的面前，也没有归信。这不可归咎于福音，也不可归咎于藉着福音让我们认识的基督，更不能归咎于那用福音呼召人，并给人各样恩赐的神，而要归咎于人自己 (1)。他们中有些人蒙了召却不留意，也不接受生命之道；有些人虽然接受，却没有用心领受，因此，当短暂的信带来的喜乐一消失，他们便转离了真道；还有些人，他们今生的忧虑和世俗的享乐如荆棘挤住了真道的种子，因此也不能结出果子来。这是我们的救主在撒种比喻中的教导（ 2）。\n\n（1）太11:20-24,22:1-8,23:37 （2）太13\n\n第十条为何其他人蒙召就来到神面前\n\n另有一些人藉着福音事工蒙召，就来到神面前并归信了。这并不是因为他们因用自由意志接受了基督，所以比其他同样得了充分恩典却用自由意志不接受基督的人好（那是骄傲的伯拉纠异端的主张），因此，他们能来到神面前不应归功于他们自己，而应归功于神 (1)。神从永恒中就在基督里拣选了属他的百姓，及至时候满足，他便有效地呼召他们，赐他们信心和悔改的能力，救他们脱离黑暗的权势，带领他们进入他爱子的国度 (2)。他所做的这一切都是为了使信徒宣告那召他们出黑暗、入奇妙光明者的伟大作为 (3)；使他们不是指着自己，而是指着主夸口(4)。这是使徒们在多处经文里所作的见证。\n\n（1）罗9:16 （2）西1:13; 加 1:4 （3）彼前2:9 （4）林前1:31; 林后10:17; 弗2:8-9\n\n第十一条神是如何使人归信的神以如下方式在选民中实施他的美好旨意，并在他们中间做使其真正归信的工作：他不仅确保选民听到福音，且藉着圣灵，强有力地光照他们的理性，以使他们正确地认识、分辨属圣灵的事 (1)；通过使人重生之圣灵有效地做工，神也穿透到人的内心深处 (2)，打开并软化那封闭和刚硬的心 (3)，给那未受割礼的心施行割礼；神又将新的性情注入他们的意志 (4)，使已死的意志复苏，使邪恶的变为良善，使不愿意的变为愿意，使顽梗的变为顺服(5)，他还感动且强化他们的意志，使之像一棵好树，能结出善行的果子 (6)。\n\n（1）来6:4-5; 林前2:10-14 （2）来4:12 （3）徒16:14 （4）申30:6 （5）结11:19,36:26 （6）太7:18\n\n第十二条重生完全是神的工作\n\n归信就是重生，是成为新造的人，是从死里复活 (1)。选民归信完全是神在我们里面做工，其间根本没有我们的参与，这是圣经特别强调的。因此，重生和归信完全不是靠说教、劝勉而实现的，也不是在神做了他的那部分工以后，靠人的力量完成的。它无疑是超自然的、最强有力的，同时也是极其可喜、奇妙、神秘和不可言喻的工作。根据这伟大之工的作者神所默示的圣经之教导，重生也是神的大能，并不亚于创世之工或使死人复活 (2)。因此，神以这奇妙的方式在其心中做工的所有人都确实、无误、有效地重生了，而且也真正地信了 (3)。此后，他们被更新了的意志不仅受神的启发和感动，而且也在神的感动下积极地发挥作用。所以，人说自己信而悔改都是藉着所受的恩典，这话是对的。\n\n（1）约3:3; 林后4:6; 5:17; 弗5:14 （2）约5:25; 罗4:17 （3）腓2:13\n\n第十三条重生之道深不可测\n\n信徒在今生不能完全领会神是怎样做成重生之工的，但同时，靠着神使他们重生的这一恩典，他们足以知道和经历到自己心里信了，也爱他们的救主（ 1）。\n\n（1）约3:18; 罗10:9\n\n第十四条为何信心是神赐的礼物\n\n信心是神所赐的礼物（ 1）。这不是说，它由神提供，然后由人凭自由意志决定取舍，而是由神实实在在地赐予人，并注入到人的心思意念中；这也不是说，神只赐给人信的能力，然后等待人的自由意志同意信，或有信的行为。信心是神所赐的礼物乃是说，那使人立志行事（ 2），甚至在众人中行万事的神，不但使人有信的意志，也有信的行为。\n\n（1）弗2:8 （2）腓2:13\n\n第十五条对待神恩典的正确态度\n\n神不欠任何人恩典。他对人能有什么亏欠呢？有谁是先给予神，而后神要偿还他的呢 (1)？对于一个除了罪和虚伪之外一无所有的人，神能欠他什么呢？所以，是领受神恩典的人亏欠了神，他要向神献上永远的感谢。然而，论及那些没有领受这恩典的人，无论是根本不在意这些属灵的事，只满足于自己现状的，还是自以为安全，自以为有、其实一无所有却枉然夸口的 (2)，抑或是只在表面上承认信仰，改变生活的，我们都要以使徒为榜样，用最善意的方式判断、谈论他们 (3)，因为人心的隐秘处，我们并不知道。至于那些尚未蒙召的人，我们应当为他们向使无变为有的神 (4)祷告。即便如此，我们丝毫不可以在他们面前自高自大 (5)，好像我们与他们有别似的。\n\n（1）罗11:35 （2）摩6:1; 耶7:4 （3）罗14:10 （4）罗4:17 （5）林前4:7\n\n第十六条人的自由意志不是被剥夺了， 而是被更新了\n\n堕落后的人还是人，并没有失去人的悟性和意志；蔓延到全人类的罪也没有夺去我们的人性，而是把堕落和灵性的死亡带给了人 (1)。相应地，当神赐予人重生的恩典时，他没有把人当作毫无意识的木头或石头对待，也没有夺走人的意志与特性，更没有粗暴地压制人的意志，而是使人的意志被更新，并医治它、纠正它，乐意以他的大能使人降服 (2)。这带来的结果是，在原本完全被属肉体的悖逆和抗拒所充满的意志中，属圣灵的、即时、真心的顺服开始占上风，而我们灵命的更新和我们意志的自由就在于这样的顺服。如果一切美善的奇妙创造主不这样对待我们，那么我们这些因滥用自由意志而自取灭亡、失去起初的圣洁与公义的人就没有希望通过自由意志从堕落中站起来。\n\n（1）罗8:2; 弗2:1 （2）诗51:12; 腓2:13\n\n第十七条神使用方法使人重生\n\n神以他的全能创造和维系我们肉身生命时并不排除，反倒需要使用一些方法。他照着自己无限的智慧和良善，定意用这些方法来施展他的大能 (1)。同样，在前文所述的使我们重生的超自然工作 (2)中，神也决不排除或停止使用福音，因为这福音是全智的神所命定的重生的种子、心灵的食粮 (3)。正因如此，众使徒以及接续他们的众教师，都将神的这项恩典虔诚地教导给人，以此使神得荣耀，使众人降卑。与此同时，他们也没有忽略用福音圣洁的教训，保守人遵行神的话语、圣礼与教会纪律 (4)。所以今天，无论是在教会中施教的，还是受教的，都不该试探神，试图让神将本已按其美好定旨紧密连接在一起的分开。恩典是藉着劝诫而传授给我们的 (5)，我们越愿意尽本分，在我们里面做工的神的这一恩典就越容易彰显其光辉，神的工作也就开展得越好。愿一切的荣耀，因着神做工的方法、救恩的果子及其功效，永远只归于神 (6)。阿们！\n\n（1）赛55:10-11; 林前1:21 （2）雅1:18 （3）彼前1:23,25; 2:2 （4）徒2:42; 林后5:11-21; 提后4:2 （5）罗10:14-17 （6）犹24-25\n\n错谬反驳\n\n在解释了人的败坏与向神归正的正确教义后，联盟总会会议驳斥了以下错谬：\n\n错谬一：确切地说，原罪本身不足以使全人类被定罪，并遭受今世和永远的刑罚。\n\n驳斥：这与使徒保罗的话相抵触，因为他说：“这就如罪是从一人入了世界，死又是从罪来的 ,于是死就临到众人，因为众人都犯了罪”（罗 5:12）； “原来审判是由一人而定罪”（罗 5:16）；又说：“罪的工价乃是死”（罗6:23）。\n\n错谬二：属灵的恩赐，或者说，好的品行与美德，如善良、圣洁、公义，不属于人最初受造时意志的一部分，因此，也就不存在所谓始祖堕落时它们就离开了人的意志这一说。\n\n驳斥：这种说法与使徒保罗在以弗所书第 4章第24节中所描述的神的形像相违背。在那节经文中，保罗说，神的形像中有仁义和圣洁，而这二者无疑属于意志的一部分。\n\n错谬三：人的灵性虽然死了，但属灵的恩赐并未与人的意志分开，因为意志本身从来没有败坏过，只是人心地昏暗，情感任性，阻碍了它发挥作用。一旦这些障碍被清除，意志就可以完全发挥它原有的能力；意志本身有能力决定选择或不选择呈现在它面前的各样美善。\n\n驳斥：这是一种新奇而错误的思想，企图高抬自由意志的能力 ,是与先知耶利米的话背道而驰的。先知耶利米说：“人心比万物都诡诈，坏到极处。”（耶 17:9）；也与使徒保罗的话相冲突，使徒保罗说：“我们从前也都在他们中间 ，放纵肉体的私欲，随着肉体和心中所喜好的去行。”（弗 2:3）\n\n错谬四：未重生之人并不是真的完全死在罪中，也没有被夺去追求属灵之善的全部能力，例如，饥渴慕义、追求属灵生命，也能献上神所喜悦的忧伤痛悔的心为祭。\n\n驳斥：这明明与圣经清晰的见证相抵触。经上说：“你们死在过犯罪恶之中”（弗 2:1）； 人“终日所思想的尽都是恶”（创 6:5）；“人从小时心里怀着恶念”（创8:21）。此外 ,只有重生的、蒙召得福的人才会渴慕脱离愁苦，追求属灵生命，并向神献上忧伤痛悔的心为祭物（见诗 51:17；太5:6）。\n\n错谬五：败坏的、属血气的人能善用普遍恩典（即阿米念主义者所说的“本性之光”），或堕落后余留在人身上的恩赐，来逐渐获得更大的恩典，即得听福音或得救的恩典，进而得着救恩。神正是这样向所有人提供了认识基督，得着信心并悔改所需的足够的、有效的方法，以此向人表明，他乐意将基督启示给所有人。\n\n驳斥：不仅历世历代的经验证明这是错误的，而且圣经也证实这种说法与事实不符。神“将他的道指示雅各，将他的律例、典章指示以色列。别国他都没有这样待过；至于他的典章，他们向来没有知道”（诗 147:19，20）；“他在从前的世代，任凭万国各行其道”（徒 14:16）； 另外，“圣灵……禁止他们（保罗和他的同工）在亚细亚讲道，他们就经过弗吕家、加拉太一带地方，到了每西亚的边界，他们想要往庇推尼去，耶稣的灵却不许。”（徒16:6-7）\n\n错谬六：当人真正归信时，神并不能将任何新的品质、能力或恩赐注入到人的意志中。因此，我们起初归信时所凭借的、使我们成为信徒的信心，并不是神给人的一种品质或恩赐，而只是人的行为。换言之，神只给了我们信的能力，但信心本身不能被称作是神的恩赐。\n\n驳斥：这种教导与圣经相悖。圣经告诉我们，神将新的性情，如信心、顺服和爱心放在我们心里：“我要将我的律法放在他们里面，写在他们心上”（耶 31:33）；“我要将水浇灌口渴的人，将河浇灌干旱之地；我要将我的灵浇灌你的后裔，将我的福浇灌你的子孙”（赛44:3）；圣经又说：“因为所赐给我们的圣灵，将神的爱浇灌在我们心里”（罗 5:5）。与此同时，这种教导也与教会一贯的做法相违背，因为教会借先知的话祷告说：“求你使我回转，我便回转。”（耶 31:18）\n\n错谬七：人本着神的恩典归向神，但这恩典只是一种温和的劝告，它以最得体、最符合人性的做工方式使人归信。所谓“劝告的恩典不足以使属血气的人变为属灵的人”的说法是没有根据的。事实上，若不通过这种温和的劝告，神也无法使人的意志同意归向神。神的能力大于撒但的能力，这表现在神所应许的福分是永远的，而撒但所应许的好处只是暂时的。\n\n驳斥：这完全是伯拉纠主义思想，与整本圣经相违背。圣经告诉我们，除了温和的劝告之外 ，圣灵神还以更大能的做工方式使人归信，如经上所说：“我也要赐给你们一个新心，将新灵放在你们里面。又从你们的肉体中除掉石心，赐给你们肉心。”（结 36:26）\n\n错谬八：在使人重生的事上，神不是用他全能的力量强制性地、万无一失地使人的意志屈服，以使他们信而悔改。即使神完成了使人归正的一切恩典之工，即使神打算使人得重生，也愿意使他重生，人仍然可以抵挡神、抵挡圣灵。事实上，人常常这样抵挡，从而完全阻止自己得重。所以，一个人能否得重生，其决定权还是在他自己手上。\n\n驳斥：这种说法无异于完全否认神的恩典在我们归信之事上的功效，并且使全能的神的工作屈从于人的意志。这与使徒保罗的教训相悖，因为他说神“向我们这信的人所显的能力是何等浩大”（弗 1:19）；他祷告求神“用大能成就你们一切所羡慕的良善和一切因信心所做的工夫”（帖后1:11）；同时，彼得也说：“神的神能已将一切关乎生命和虔敬的事赐给我们。”（彼后 1:3）\n\n错谬九：恩典与自由意志二者同是人归信的原因，同做使人归正的初期工作。在做工的次序上，恩典并不先于意志。在人的意志发动并定意要归信之前，神并不从实质上帮助人的意志，以使人归信。\n\n驳斥：很久以前，早期教会就根据使徒保罗的教导谴责伯拉纠主义的这种错误教义。保罗说：“据此看来，这不在乎那定意的，也不在乎那奔跑的，只在乎发怜悯的神”（罗9:16）；又说：“使你与人不同的是谁呢？你有什么不是领受的呢”（林前 4:7）；他还说：“因为你们立志行事，都是神在你们心里运行，为要成就他的美意。”（腓2:13）\n\n第五项教义真信徒能持守信仰\n\n第一条重生的人并非已脱离罪性\n\n那些按神旨意蒙召与他的儿子我们的主耶稣基督相交， 并被圣灵重生的人，显然脱离了罪的权势与奴役（ 1）， 但他们在今世并没有完全脱离罪身和肉体的软弱（ 2）。\n\n（1）约 8:34; 罗6:17 （2）罗7:21-24\n\n第二条信徒每天都因软弱犯罪\n\n信徒每天都会因软弱犯罪；他们所行的最好的善事也有瑕疵（ 1）。正因如此，他们不断地谦卑在神面前，逃到被钉十字架的基督那里寻求庇护，越来越多地藉着祷告和操练圣洁（ 2）来治死肉体，渴望并努力地向着做完全人这一标竿奔跑，直到最终（ 3）脱离取死的身体，在天堂与神的羔羊一同执掌王权（ 4）。\n\n（1）约壹1:8 （2）西3:5 （3）提前 4:7; 腓 3:12,14 （4）启5:6,10\n\n第三条神保守属他的人\n\n因着残留在人里面的罪，以及来自世界和撒但的引诱，那些悔改归信的人如果靠自己的力量，就不能在恩典中站立（1）。但是，神是信实的，他一旦赐恩典给属他的人，就仁慈地在恩典中坚固他们，并以大能保守他们一直在这恩典中，直到世界末了（ 2）。\n\n（1）罗7:20 （2）林前10:13; 彼前1:5\n\n第四条真信徒也可能犯严重的罪\n\n神借以坚固和保守真信徒常在恩典中的能力虽然极大（1），不是肉体所能胜的，但是，信徒并不总是被神带领和感动到一个地步，从而不会因自己的过错做某些事离开神恩典的指引，最终因受肉体情欲的诱惑而顺从情欲。因此，信徒必须时常警醒祷告（ 2），免得入了迷惑（ 3）， 否则，他们不仅可能因受肉体、世界和撒但的引诱而犯下严重的、可怕的罪，有时，神按着他的公义，甚至许可他们真的陷入这样的罪中。圣经中大卫、彼得及其他圣徒犯罪，就充分地说明了这一点（ 4）。\n\n（1）弗1:19 （2）帖前5:6, 17 （3）太26:41 （4）撒下11; 太26\n\n第五条犯罪导致的一系列后果\n\n信徒犯下恶劣的罪，就大大得罪神，招致死罪，叫圣灵担忧；自己无法操练信心，使良心受到重创，有时在一段时间内甚至会有失去神恩宠的感觉（ 1）。他若真心悔改，就能回归正道，神慈父般的脸会再次光照他（ 2）。\n\n（1）撒下12; 弗4:30 （2）诗32:3-5; 民6:25\n\n第六条神不许可属他的人迷失\n\n根据他不变的拣选定旨（ 1），即使那些属他的人犯了可怕的罪，有丰富怜悯的神也不将他的灵从他们那里完全撤回（2）；他也不允许他们深陷罪中，以致失去神儿子的名分和得称为义的地位 （3），也不允许他们犯罪，以至于死 （4），更不允许他们犯下亵渎圣灵的罪以致完全遭他弃绝，自取永远的灭亡 （5）。\n\n（1）弗1:11,2:4 （2）诗51:11 （3）加4:5 （4）约壹5:16-18 （5）太12:31-32\n\n第七条神会再次更新属他的人，使他们悔改\n\n当属神的人犯罪时，神首先保守那不朽坏的重生的种子存留在他们里面，使它免遭毁坏，也不致丧失（ 1）。 然后，藉着他的道和灵，神确实、有效地更新他们，使他们悔改（ 2）。这样做的结果是，他们真心为自己所犯的罪向神忧伤（ 3）；藉着信，他们以痛悔的心，寻求并得着因中保流宝血而得来的赦罪之恩；他们再一次经历与神和好的福分，并爱慕他的慈悲与信实（ 4）；从此以后，他们会恐惧战兢，更加勤勉地做成自己得救的工夫（ 5）。 （1）彼前 1:23 （2）约壹 3:9 （3）林后 7:10 （4）诗32:5,51:19 （5）腓 2:12\n\n第八条三一神恩典的保守\n\n完全失去信心与恩典，深陷罪中，直到最后失丧的情况不会发生在属神的人身上。这不是靠信徒自己的功德或力量，而是藉着人所不配得的神的恩典。这种情况对信徒而言不但很容易发生，而且一定会发生，但对神而言则不可能发生，因为他的定旨不会改变（ 1），他的应许不会落空，按其旨意发出的呼召不会撤回（ 2），基督的功德、代求与保守不会无效（ 3），圣灵的印记既不会作废，也不会被抹去（ 4）。\n\n（1）诗33:11 （2）来6:17; 罗8:30; 9:11 （3）路 22:32; 罗8:34 （4）弗 1:13\n\n第九条信徒确信蒙保守\n\n信徒自己能够对选民蒙保守得救恩和真信徒能持守信仰有十足的把握（ 1）。照着神赐的信心的程度（ 2），信徒也确实对上述两点有把握，他们都坚信自己现在是，并且永远是真信徒，是教会里活泼的一员，也坚信自己得了赦罪之恩和永生（ 3）。\n\n（1）罗8:31-39 （2）提后4:8 （3）提后4:18 第十条此确信的来源\n\n这确信不是来源于圣经以外的某个“给个人的启示”，而是来源于：（一）信神的应许，这应许是神为了让我们得安慰而在他话语中丰丰富富地启示给我们的； （二）圣灵与我们的心同作见证，证明我们是神的儿女和后嗣（1）；（三）为神的缘故认真地追求清洁的良心（ 2），行真正的善事。如果神的选民在今生没有从最后得胜的盼望中得到实在的安慰（ 3），也没有永远得荣耀的可靠保证，那么他们就比众人更可怜（ 4） 。\n\n（1）罗8:16-17; 约壹 3:1-2 （2）徒 24:16 （3）罗8:37 （4）林前 15:19\n\n第十一条此确信不总能感受到\n\n同时，圣经也作见证：信徒在今生不得不与肉体的各种怀疑争战；在遭受巨大试探时，他们并不总能感觉到这样的确信，也不总认为自己肯定能持守这信仰。然而， 赐各样安慰的父神（ 1），必不叫他们受试探过于他们所能受的，在受试探的时候，总要给他们开一条出路；他也必藉着圣灵，使信徒再次确信自己能持守这信仰（ 2）。\n\n（1）林后 1:3 （2）林前 10:13\n\n第十二条此确信是追求圣洁的动力\n\n对持守信仰有把握绝不会使真信徒骄傲自满，相反，它能生出谦卑，对神产生孩童般的敬畏（ 1）和真敬虔，也会使信徒在每一次争战中忍耐、热切祷告，在患难中坚定不移，坚持宣告真理，并在神里面常常喜乐（ 2）。此外，思想持守信仰所带来的益处也激励信徒不断真心地感恩并行善（ 3），这一点从圣经的见证与圣徒的例子中都得到了证明。 （1）罗12:1 （2）诗56:12-13 （3）诗116:12; 多 2:11-14; 约壹 3:3\n\n第十三条此确信不会导致忽视敬虔\n\n这种确信不会让犯罪跌倒后被重建的人（ 1）变得不在意或忽视敬虔，而会使他们更谨守遵行主已经预备好的道（2）。通过行在其间，他们不会对自己蒙保守持守信仰这一点失去信心，免得因滥用父神的良善而使恩慈的神再次掩面不看他们（ 3），从而招致自己的灵魂遭受更大的痛苦。的确，对敬畏神的人而言，神向他们仰脸比生命更甜美，而神掩面不看他们则比死亡更痛苦（ 4）。\n\n（1）林后 7:10 （2）弗 2:10 （3）诗63:4; 赛 64:7 （4）耶 33:5\n\n第十四条持守信仰所用的方法\n\n正如神喜悦藉着福音的宣讲在我们身上开始这恩典之工，同样他也藉着听道、读经（ 1），默想经文、圣经的劝勉、警告和应许 (2）以及圣礼这些方法来维持、继续，并完成这恩典之工（ 3）。\n\n（1）申 6:20-25 （2）提后 3:16-17 （3）徒 2:42\n\n第十五条此项教义为撒但所恨，为教会所爱\n\n为了荣耀他的名、安慰敬虔的人，神已将真信徒能持守信仰并对此有确切把握（ 1）的这一教义丰丰富富地启示在圣经中，并印刻在了信徒的心上。这项教义是肉体不能明白、为撒但所憎恨的，是被世人讥笑、被愚昧和伪善者滥用的，也是遭异端攻击的。然而，基督的新妇（教会）却视之为无价之宝（ 2），始终挚爱着它，并坚定地为之辩护；而其计划不可抗拒、其势不可阻挡（ 3）的神，会确保教会继续如此行。愿尊贵与荣耀单单归于圣父、圣子、圣灵三位一体的神，直到永远（ 4）。 阿们。\n\n（1）启14:12 （2）弗 5:32 （3）诗33:10-11 （4）彼前 5:10-11\n\n错谬反驳\n\n在解释了真信徒能持守信仰这一正确教义后，联合总会会议驳斥了以下错谬：\n\n错谬一：真信徒持守信仰不是拣选的结果，也不是神藉着基督之死赐给人的礼物，而是新约的一个条件。在蒙所谓绝对的拣选与称义之前，人必须通过他的自由意志满足这一条件。\n\n驳斥：持守信仰是因蒙了拣选，也是神藉着基督的死、复活与代求赐给选民的礼物，因为圣经作见证说：“惟有蒙拣选的人得着了，其余的就成了顽梗不化的。”（罗11:7）；“神既不爱惜自己的儿子为我们众人舍了，岂不也把万物和他一同白白地赐给我们吗？谁能控告神所拣选的人呢？有神称他们为义了。谁能定他们的罪呢？有基督耶稣已经死了，而且从死里复活，现今在神的右边，也替我们祈求。谁能使我们与基督的爱隔绝呢？”（罗 8:32-35）\n\n错谬二：神的确赐给信徒充分的力量，使他们得以持守信仰；如果他们履行自己的责任，神也乐意使这力量长存在他们里面。然而，即使凭信心持守信仰所需的和神借以保守其信心的一切都已具备，人最终能否持守信仰还要看其意志所作的决定。\n\n驳斥：这种观念无疑含有伯拉纠主义的错误思想。它虽旨在给人自由，但实际上是叫人抢夺神的荣耀，这与圣经的一贯教导相抵触。圣经的教导使人没有任何理由夸口，也使人将从中所得的益处单单归因于神的恩典，并因此将一切颂赞都归给神。这种错谬也与保罗的见证相违背。保罗说：“他也必坚固你们到底，叫你们在我们主耶稣基督的日子无可责备。”（林前 1:8）\n\n错谬三：真正重生的信徒不但有可能真的完全跌倒，失去称义的信心以及神的恩典和救恩，而且，他们也确实常常失去这些，从而永远地迷失了。 驳斥：这种观点不仅彻底否认了称义、重生的恩典，和基督对信徒持续的保守，而且也与圣经教导相违背。保罗说：“惟有基督在我们还作罪人的时候为我们死，神的爱就在此向我们显明了。现在我们既靠着他的血称义，就更要藉着他免去神的忿怒”（罗 5:8-9）；使徒约翰教导说：“凡从神生的，就不犯罪，因神的道存在他心里；他也不能犯罪，因为他是由神生的”（约壹 3:9）；耶稣基督也曾说：“我又赐给他们永生 ,他们永不灭亡，谁也不能从我手里把他们夺去。我父把羊赐给我，他比万有都大 ,谁也不能从我父手里把他们夺去。”（约 10:28-29）\n\n错谬四：真正重生的信徒仍然有可能犯“以至于死”的罪，即亵渎圣灵的罪。\n\n驳斥：使徒约翰在说到“有至于死的罪，我不说当为这罪祈求”（约壹 5:16）之后，紧接着说： “我们知道凡从神生的，必不犯罪（此处指上文所说的“至于死的罪 ”——译注），从神生的，必保守自己，那恶者也就无法害他。”（约壹 5:18）\n\n错谬五：除非得到特别的启示，我们不可能确信自己今生一直能持守这信仰。\n\n驳斥：这一说法使信徒在今生不能因确信而得着安慰，也会导致罗马教皇的追随者们所持的怀疑被再次引入教会。然而，圣经一直给真信徒这样的确信，这不是通过特别的、离奇的方式启示给他们，而是藉着神儿女所特有的记号，以及神一贯的应许。所以，使徒保罗特别宣告说，任何受造之物都不能叫我们与神的爱隔绝；这爱是在我们的主基督耶稣里的（见罗 8:39）；使徒约翰也说：“遵守神命令的，就住在神里面，神也住在他里面。我们所以知道神住在我们里面，是因他所赐给我们的圣灵。”（约壹3:24）\n\n错谬六：确信自己蒙保守得救恩的教义本身一定会带来虚假的安全感，这对操练敬虔、好品德和祷告等是有害无益的。恰恰相反，对自己蒙保守得救恩留有怀疑是值得称赞的。\n\n驳斥：这种说法是无视神恩典的有效和大能，也是无视内住在我们里面的圣灵所做的做工。它违背了使徒约翰的教导：“亲爱的弟兄啊，我们现在是神的儿女，将来如何，还未显明；但我们知道，主若显现，我们必要像他，因为必得见他的真体。凡向他有这指望的，就洁净自己，像他洁净一样。”（约壹 3:2-3）此外，这种说法在新旧约中真信徒的榜样面前也站不住脚，因为他们虽然确信自己蒙保守得救恩，却仍然恒切祷告、操练各样的敬虔。\n\n错谬七：暂时性的信心与称义和得救的信心，除了在时间长短上有所不同之外并没有差别。\n\n驳斥：在马太福音第 13章第20-23节和路加福音第8章第13节中，基督亲自阐明，除了持续时间长短的区别之外，暂时性的信与真信心之间还有三方面的不同：（一）前者好比撒在石头地上，后者撒在好地上，即在“新心”里；（二）前者没有根，而后者扎根很深；（三）前者不结果子，而后者则不断地、稳定地结出数量不同、大小各异的果子。\n\n错谬八：一个人在第一次重生又迷失后，还能再次重生，甚至常常重生。这没有什么荒谬的。\n\n驳斥：这种观点否认了一个事实，即我们借以重生的种子是不能朽坏的；它也违背了使徒彼得的见证：“你们蒙了重生，不是由于能坏的种子，乃是由于不能坏的种子，是藉着神活泼常存的道。”（彼前 1:23）\n\n错谬九：基督从来没有为信徒恒久地持守信仰而祷告。\n\n驳斥：这与基督所说的话不符，基督亲口说：“我已经为你祈求，叫你不至于失了信心。你回头以后，要坚固你的弟兄。”（路 22:32）这也与使徒约翰的话相抵触，他说基督不但为众使徒祷告：“圣父啊，求你因你所赐给我的名保守他们，叫他们合而为一，像我们一样”（约17:11）；也为那些因使徒的话而信的人祷告：“我不但为这些人祈求，也为那些因他们的话信我的人祈求”（约17: 20）；基督又说，“我不求你叫他们离开世界，只求你保守他们脱离那恶者”（约 17:15）。", "status": "附件阅读版 · 网站逐字核验未完成", "note": "用户提供的《敬拜赞美手册》（2015）印刷页 95–138，清理换行、页码与排版空白；内容含原书经文注释。不是已完成逐字校验的 CCI 网站转录。"}];
window.DEEP_DIVES=[{"title": "01 · 为什么必须从三一神开始，而不是从人的宗教需要开始？", "refs": "威告 2、8；小要理 4–6、21–28；大要理 6–11、36–56；比利时 8–11；海德堡 24–25", "paragraphs": ["若以人感到缺少什么为起点，神容易被缩成满足需要的工具。圣经却从神创造、说话、审判与应许开始：人的意义来自与这位神的关系。因此小要理开篇所讲的荣耀与享受，不是两项目标相互妥协，而是受造生命在真实归属中得满足。神不靠人的称赞弥补缺乏；敬拜使人承认已经存在的荣耀。", "三一教义同时保障救恩不是神临时起意。父差遣子，子甘心完成中保使命，灵将救赎施行在人身上；这是独一神不可分割的作为，按位格各有合宜的秩序。不能说父只有愤怒、子才有爱，也不能说圣灵只是传递能量。道成肉身属于子，而非父或灵变成人；位格有别不导致三种互不相干的工作。", "欧陆与威敏的共同根基先在古代大公信仰。尼西亚所守护的与父同质，使救主真正能赐生命；亚他那修信经所区分的位格与本质，防止把三一化成三神或三种面貌。日常祷告于是成为教义的实践：靠圣灵，借中保，到父面前；坦然不等于随便，敬畏不等于退避。"]}, {"title": "02 · 圣经神学与系统神学：历史展开与整体判断如何互相校正？", "refs": "威告 1、7–8；小要理 2–3、20；大要理 3–6、30–35；比利时 2–7、17", "paragraphs": ["读创世记十五章时，先看亚伯兰在后裔、应许与未得之地面前的处境；读出埃及记时，先看已蒙拯救的民族如何进入圣约生活。历史处境使经文不沦为随意抽取的励志句。随后再看使徒如何在罗马书四章、加拉太书三章解释亚伯拉罕，便会认识因信而义不是新约抛弃旧约后才出现的发明。", "圣经神学追踪应许、后裔、国度、圣殿、祭司与安息的推进，不等于把每个石头、颜色都找成基督的密码。预表须受经文关系与新约成全的约束。系统神学则追问：整本圣经怎样共同说明称义、圣礼或教会？它不能让一段经文排除另一段，而须区分层次、对象与语境。", "圣约是两者相接的重要线索。神在历史中以真实应许与命令对待百姓；基督是应许的中心与成全者。旧约与新约有同一救恩实质，却不是在启示清晰度、礼仪及群体行政上毫无变化。记忆时可用四个问题：当时对谁说？在应许推进的哪一站？如何在基督里成全？今天怎样借信与顺服回应？"]}, {"title": "03 · 称义、成圣与联合：为什么既不可混淆，也不可分离？", "refs": "威告 10–16；小要理 29–35；大要理 66–78；比利时 22–24；海德堡 60–64", "paragraphs": ["与基督联合是理解救恩益处的关系中心；称义与成圣则回答不同问题。称义问罪人在圣洁审判者面前如何被接纳：根据是基督完整的顺服与满足，领受途径是信心。成圣问被接纳的人怎样被更新：圣灵使其真实离罪、爱神与行义。不是先让人积累一定程度圣洁，神才宣布接纳；也不是宣布接纳后，内在生命从此毫无关系。", "罗马书三至五章将恩典、信心、基督与宣告为义连在一起；罗马书六章随即拒绝仍旧住在罪中的推论。以弗所书二章也把不出于行为的得救与为善行而被造放在同一段中。顺序有神学意义：好行为不能进入称义的根据，却必在救恩结果中占有真实位置。", "信心也不可变成一种替代性的功德。抓住救生者的手并不使遇险者成为拯救自己的英雄；比喻有限，却可提醒人，信心的力量在它所领受的对象。软弱的信徒不必先检查自己是否信得足够强，才有资格看基督；他当直接投靠基督，并在圣道、祷告、圣礼与肢体相交中求信心增长。", "欧陆信条常从属于基督的安慰展开，威敏则更详细地区分宣告与更新。两种写法不应变成冷体系与暖灵修的对立。准确区分正是为安慰服务：一方面停止用自己的波动表现购买父的接纳，另一方面认真对付罪，因为恩典使人真正开始更新。"]}, {"title": "04 · 预定、普遍福音呼召与人的责任：为何不是互相抵销？", "refs": "威告 3、5、9–10；小要理 7、31；大要理 12–14、67–68；多特第一、第二及第三四项", "paragraphs": ["神的隐秘旨意与向人启示的命令，不是同一问题的两个竞争答案。我们不知道谁在永恒中蒙拣选，却确知福音要向万民宣告，听见者当悔改相信。不能把不知的事当作推翻明知命令的理由。多特对特定救赎的教导也没有取消诚恳、广泛的福音应许与呼召；阅读其第二项第五条尤其重要。", "护理中的第一因与第二因同样需要区分。约瑟兄长以恶意行动，神使同一历史事件服务于保全生命；使徒行传二章又同时说基督被交出在神定旨中，而钉他的人有罪。经文不是说两种解释只能选一个。神掌权不将受造者变成没有意志的石头，人负责也不使神只能被动补救。", "不应把拣选与定罪描述为神以相同方式制造信心和罪。人犯罪的恶归于受造者；救人归于恩典。这里包含受造理性无法穷尽的深度，信条因此要求谨慎、谦卑地处理预定。它的牧养出口是颂赞、勤勉与确信，不是好奇地猜测天上名单。"]}, {"title": "05 · 圣礼的真实与界限：为什么既不是魔法，也不只是回忆？", "refs": "威告 27–29；小要理 91–97；大要理 161–177；比利时 33–35；海德堡 65–82", "paragraphs": ["神借人的耳朵传圣道，也借眼睛和身体可领受的记号印证应许。外在可见性不是属灵性的敌人，因为人本是有身体的受造者。然而记号不能与所指混同：水本身不是重生，饼酒本身不是变成基督身体。圣礼的效力来自圣灵与设立者的应许，并非物质机制或圣职者个人功力。", "圣餐因此不重做十字架，却使信徒在圣灵中真实分享已经成全的基督。哥林多前书十章把领杯饼与同属一个身体相连，十一章更把羞辱贫穷者与不合宜领餐相连。因此省察不只是我今天有没有感动，还包括我是否信靠主、愿意悔改、与身体相爱。", "婴孩洗礼与成人认信则使人看见圣约施行的两种处境。儿女领受应许的记号，不是得到不需信心的自动救恩；成年归信者先认信，也不是以其认信功劳配得恩典。受洗者的一生都须学习与基督同死同活。领袖应认真守护圣餐，也应按大要理一百七十二问安慰忧伤却愿来投靠基督的疑惑者。"]}, {"title": "06 · 律法、自由与敬拜：恩典如何产生有形的顺服？", "refs": "威告 19–22；小要理 39–84、98–107；大要理 91–152、178–196；海德堡 86–129", "paragraphs": ["律法与福音不能混为同一种话语：律法显明神的要求并揭露罪，福音宣告基督为罪人完成拯救。但救主不是把人带进没有神旨意的空白空间。海德堡的愁苦、拯救、感恩与威敏的当信、当行，在结构上都表明被救赎者要学习遵行神命令。", "十诫的积极要求使伦理超出避免犯法。不可杀人召人保护生命，不可偷盗召人维护邻舍益处，不可作假见证召人忠于事实。大要理九十九问的解释规则尤其重要：每一诫涉及思想、言语、行为及其原因机会；禁止罪也要求相反的义。但扩展须依经文与实际本分，不能让宗教领袖对他人生活取得无限裁量权。", "良心自由意味着神才是良心的主。它既保护信徒不受人为宗教条件辖制，也不把明确的圣经责任降为私人偏好。公共敬拜的规限原则则要求敬拜要素有神的设立根据；时间安排、语言、声学等处境须按普遍准则和审慎判断处理。把一切具体处境都神圣化与让敬拜完全随潮流，都偏离这一区分。", "欧陆圣约式敬拜常强调神的呼召与子民回应；长老会也强调圣道、祷告与圣礼。具体诗歌、乐器及节期实践在宗派间有差异，不能以一间教会的做法概括所有改革宗。阅读认信文件与教会秩序、辨认相应版本，是进行公平比较的前提。"]}, {"title": "07 · 教会与末世：为何个人得救必然走向共同生活？", "refs": "威告 25–26、30–33；小要理 36–38；大要理 61–65、79–90；比利时 27–32、37；海德堡 54–58", "paragraphs": ["圣经并不把救恩描画为许多孤立灵魂各自与神签约。以弗所书二章从个人得救进入犹太人与外邦人同为一家；四章将恩赐赐给身体，使众人长成。教会因此不是信仰完成后的附属社团，而是基督借普通途径牧养子民的群体。圣徒相通必须具体到探访、奉献、接纳与彼此担当。", "可见与无形区分不是建立两个教会，而是分别人的历史辨认与神最终完全的认识。前者认真对待公开认信、圣约儿女、圣礼与纪律；后者提醒人，外在地位不能自动代替内在信靠。纪律也须以挽回、保护群体与尊荣神为目的；悔改可以恢复相交，却不自动恢复公职或取消民事责任。", "最后两章把救恩推向身体复活与最后审判。信徒死后与主同在是真实安慰，但最终盼望仍是身体与受造界的更新。公义审判使受压者知道邪恶不会永被遗忘；公开接纳使软弱信徒知道最终判语在基督里。教会因此能在今世忠心服事，而不把任何人间秩序误当已经圆满的新天新地。"]}];